  Item_10062_Desc = {
    Text = "這下沒人敢用它來占卜吉兇了吧。\n被融蝕漿覆蓋的紫色水晶，用於提升超維界域喚醒體的技能等級。"
  },
  Item_10062_Name = {
    Text = "殘破礦晶"
  },
  Item_10063_Desc = {
    Text = "那是古老意志的失落靈識。 彌薩格通過神秘的儀式啟發喚醒體的靈識，受到啟發的喚醒體將永久增強精神能力。\n重複獲得艾爾瓦時轉換獲得，用於啟動艾爾瓦的啟靈。"
  },
  Item_10063_Name = {
    Text = "殘片·艾爾瓦"
  },
  Item_10063_StoryDesc = {
    Text = "重複獲得艾爾瓦時轉換獲得，用於啟動艾爾瓦的啟靈。"
  },
  Item_10064_Desc = {
    Text = "由彌薩格大學創始人研究出的，能夠提升喚醒體能力的製劑。\n由銀芯與秘藥調配而成，呈現出一種奇異的色澤。\n可以為喚醒體提供500經驗值。"
  },
  Item_10064_Name = {
    Text = "靈知製劑Ⅰ"
  },
  Item_10065_Desc = {
    Text = "記錄此鑰令後，可在編隊時選擇鑰令技能：「小小心願」。\n\n女孩在六歲生日的那天許下心願：\n擁有一隻名為「波波」的玩具熊，以及愛——不需要太多，一點點就夠了。\n女孩從來都不是一個擅長幻想的人，也不是一個貪心的人。"
  },
  Item_10065_Name = {
    Text = "小小心願"
  },
  Item_10065_StoryDesc = {
    Text = "女孩在六歲生日的那天許下心願：\n擁有一隻名為「波波」的玩具熊，以及愛——不需要太多，一點點就夠了。\n女孩從來都不是一個擅長幻想的人，也不是一個貪心的人。"
  },
  Item_10066_Desc = {
    Text = "當靈知被無限放大，它將觸及真相的一角。\n由銀芯驅動的特殊儀器，能按照預設值永久提升喚醒體的能力。\n守密人達到40級後，可以選擇任一喚醒體，使其獲得以下增幅：\n·等級提升至50級\n·所有技能提升至3級\n·突破等階提升至4階"
  },
  Item_10066_Name = {
    Text = "靈知增幅器Ⅴ"
  },
  Item_10067_Desc = {
    Text = "傳說中最初的魔偶創造者，以雙手殺死魔偶。\n隨機掉落猩紅之擁密契套裝部件。"
  },
  Item_10067_Name = {
    Text = "猩紅之擁"
  },
  Item_10068_Desc = {
    Text = "當靈知被無限放大，它將觸及真相的一角。\n由銀芯驅動的特殊儀器，能按照預設值永久提升喚醒體的能力。\n守密人達到50級後，可以選擇任一喚醒體，使其獲得以下增幅：\n·等級提升至60級\n·所有技能提升至4級\n·突破等階提升至5階"
  },
  Item_10068_Name = {
    Text = "靈知增幅器Ⅵ"
  },
  Item_10069_Desc = {
    Text = "全面而綜合的提高生存與續航能力，額外的猩紅熔爐儲存上限和傷害成長能夠帶來更多可能。"
  },
  Item_10069_StoryDesc = {
    Text = "創生的父神自星空中來。\n那時的地是赤焰熱土，烈火熊熊。父神的足踏在火上。\n父神說，火終將熄，火便這麼做了。\n流動的土成了地，父神在地上寫下神言：\n地將做生靈的基。\n山谷就成了山谷，平原就成了平原。\n神言穩固，這是第一塊石板。\n\n父神看雲厚重，說，雲終落雨，雲便這麼做了。\n雨彙聚成流水，父神在其上寫下神言：\n水將做溫床。\n水就成了湖、成了海，海就淹沒了地。\n神言穩固，這是第二塊石板。\n\n父神看水暗淡，說，光當降臨，光便這麼做了。\n光落在水上，父神在光上寫下神言：\n光將滋養。\n光就帶來溫暖。\n神言穩固，這是第三塊石板。\n\n父神見地、水、光皆有了，說，生命將臨。\n祂讓自己的血流下，在其上寫下神言：\n血將孕育新生。\n父神的血散了去，成了有生命的物，在海中繁衍。\n神言穩固，這是第四塊石板。\n\n父神見生有了，說，生物將永恆地變化。生物便這麼做了。\n微不可見的物爬上退了海水的地。\n父在變化的物上寫下神言：\n變化不可停止。\n爬上陸地的物就長出根莖，長出四肢，長出各種模樣。\n神言穩固，這是第五塊石板。\n\n父神見生有了，變化也有了，說，死亦將至。死便來了。\n衰老的死去，病弱的死去。父神在死上寫下神言：\n死的將回歸到最初。\n死者的軀體就慢慢消了，回到父神的懷抱。\n神言穩固，這是第六塊石板。\n\n父神見生、死、變化都有了，說，這些都是我的造物，我將留下祝福。\n父神取出自己的骨，在上面寫下神言：\n在萬物的末路，可用我的骨，代行我的權。\n以血肉的代價賦予生機。\n神言穩固，這是第七塊石板。\n\n父神看一切都有了，就停下來休息。\n水將父神包裹起來，光為父神提供溫暖，地將父神遮蓋。\n而後父神長眠，萬物都依照父神的言生存，那就是現在的世界。"
  },
  Item_10070_Desc = {
    Text = "當靈知被無限放大，它將觸及真相的一角。\n由銀芯驅動的特殊儀器，能按照預設值永久提升喚醒體的能力。\n守密人達到20級後，可以選擇任一喚醒體，使其獲得以下增幅：\n·等級提升至30級\n·突破等階提升至2階"
  },
  Item_10070_Name = {
