  Item_10082_Name = {
    Text = "紫色命輪疊位材料（開發用）"
  },
  Item_10083_Desc = {
    Text = "你將不朽。\n在超驗存在中掉落的記憶凝晶，用以在彌薩格商店中兌換物品。"
  },
  Item_10083_Name = {
