  },
  Item_10092_Name = {
    Text = "隕星碎塊"
  },
  Item_10093_Desc = {
    Text = "請在專業人士的幫助下打開。\n封裝著古老密契的神秘木匣，可在無光之境中獲得。\n可獲得扭曲雙子白密契套裝部件"
  },
  Item_10093_Name = {
    Text = "無序契皿Ⅲ"
  },
  Item_10094_Desc = {
    Text = "主屬性從暴擊率、暴擊傷害、死亡抵抗和傷害強效中隨機獲得1個。"
  },
  Item_10094_Name = {
    Text = "生機榨取Ⅲ"
  },
  Item_10094_StoryDesc = {
    Text = "臍帶連接著無窮無盡的未來。"
  },
  Item_10095_Desc = {
    Text = "為了人類存續。\n被保存在畫框裡的記憶。用以升格血肉界域喚醒體的材料。"
  },
  Item_10095_Name = {
    Text = "記憶副本"
  },
  Item_10096_Desc = {
    Text = "給予我們未可知曉的認知。\n源自菲林詩社的特殊膠片，能轉寫人的認知。\n用以升格超維界域喚醒體的材料。"
  },
  Item_10096_Name = {
    Text = "認知範本"
  },
  Item_10097_Desc = {
    Text = "花語：離我遠點。\n低莖海百合的化石。用於提升深海界域喚醒體的技能等級。"
  },
  Item_10097_Name = {
    Text = "低莖海百合"
  },
  Item_10098_Desc = {
    Text = "詹金如她的老鼠夥伴布朗一般機敏迅捷，神出鬼沒。\n·借助超維躍遷，造成大量傷害\n·擁有隨機應變的傷害能力"
  },
  Item_10099_Desc = {
    Text = "主屬性從暴擊率、暴擊傷害、銀鑰充能等級和狂氣回充等級中隨機獲得1個。"
  },
  Item_10099_Name = {
    Text = "生機榨取Ⅰ"
  },
  Item_10099_StoryDesc = {
    Text = "臍帶連接著無窮無盡的未來。"
  },
  Item_10100_Desc = {
    Text = "釋放狂氣爆發後能夠額外獲取狂氣和臨時暴擊傷害，絕佳的運氣往往能夠與隊友一同分享自身的好運。"
  },
  Item_10100_Name = {
    Text = "好運時間"
  },
  Item_10100_StoryDesc = {
    Text = "沿著泰姆河一路向下，向右拐至貝克曼街，繼續行走大約一百英尺，你就能在那不起眼的角落看到「萊克偵探事務所」。\n\n作為倫蒂尼恩破案率最高的偵探事務所，這裡沒有塞滿專業書籍的大書架，沒有貼滿剪報的牆面，也沒有精緻的下午茶。\n你大機率只會撞見門前掛著的「有事外出」標牌以及趴在一旁的疲憊老狗。\n\n若是運氣好點，在某個天氣晴朗的週日上午，你興許能等到宿醉歸來的名偵探先生。\n此時他剛結束上一把賭局，兜裡沒剩幾個錢，你可以盡情向他提出你的無理委託：尋找貓咪、解救入了邪教的老母親、搜集丈夫的外遇證據……\n只要你有，他就能接。\n\n「我享受瀕死前的瞬間，所以我註定會成為一名賭徒。」\n「那成為偵探呢？恕我直言，我看不出尋找貓咪和瀕死之間的相關性。」\n「不，你不明白……尋找真相的過程本身就已足夠迷人，不論大小。就像……」\n「就像奔赴一場和死亡的約會。」"
  },
  Item_10101_Desc = {
    Text = "造成更多狂氣和中毒的同時能夠獻祭敵方生命轉化為臨時暴擊傷害，虔誠的信仰能夠驅使更多的觸腕。"
  },
  Item_10101_Name = {
    Text = "虔誠的偉力"
  },
  Item_10101_StoryDesc = {
    Text = "螺湮的主宰啊，請聆聽我的禱告。\n降下你的預言，給予我啟示，\n讓我能夠復原你的國。\n在這無信仰的土地，在這海洋環繞的冰原，\n將你的石柱立起，將你的神殿搭建。\n\n號令深淵之主啊，台上的是獻給你的禮。\n純淨的血肉來自滿月的羔羊，強健的心來自成年的公牛，\n銳利的眼來自翱翔的雄鷹，堅硬的骨來自巡洋的鯨。\n青金石是你的王座，黃金是你的冠冕，\n請賜予我你的夢境，告予我神言，\n讓我能夠復原你的身。\n在這冰下的深淵，在這海下的領域，\n將正確時刻降生的母體奉獻。\n\n通曉萬事的利莫里亞之王啊，請回應我的禱告。\n自你入海長眠以來，已過了千百年，\n我以你的名，行你的事，宣揚你的美名，從未懈怠。\n堅定的是我的信仰，虔誠的是我的心。\n你是唯一的神王，是不朽者的化身，\n願你終結我的等待，再臨於世，讓我得以聆聽你智慧的言。"
  },
  Item_10102_Desc = {
    Text = "主屬性從狂氣回充等級、死亡抵抗、銀鑰充能等級和傷害強效中隨機獲得1個。"
  },
  Item_10102_Name = {
    Text = "猩紅之悸Ⅴ"
  },
  Item_10102_StoryDesc = {
    Text = "傳說中最初的魔像創造者，以血液滋養魔像。"
  },
  Item_10103_Desc = {
    Text = "主屬性從暴擊率、暴擊傷害、銀鑰充能等級和狂氣回充等級中隨機獲得1個。"
  },
  Item_10103_Name = {
    Text = "猩紅之悸Ⅰ"
  },
  Item_10103_StoryDesc = {
    Text = "傳說中最初的魔像創造者，以血液滋養魔像。"
  },
  Item_10104_Desc = {
    Text = "封裝大量銀芯的禮盒。它們只負責創造奇蹟。"
  },
  Item_10104_Name = {
    Text = "至尊銀芯禮盒"
  },
  Item_10105_Desc = {
    Text = "主屬性從暴擊率、暴擊傷害、銀鑰充能等級和狂氣回充等級中隨機獲得1個。"
  },
  Item_10105_StoryDesc = {
    Text = "為您奉上純潔的軀殼。"
  },
  Item_10106_Desc = {
    Text = "訶勒特代理院長特批的豐厚補給。\n封裝著珍稀材料的木盒，為執行密境課室的日常試訓與週常試訓任務的守密人提供援助。\n從以下素材中選擇一種：\n純白秘篇*12\n淬製心靈*12\n意識副本*12\n靈知模板*12"
  },
  Item_10106_Name = {
    Text = "Ⅱ級補給（已廢棄）"
  },
  Item_10107_Desc = {
    Text = "密契的本質即為禁忌的、難以被認知的知識。在使用拓片進行重新描繪後，密契的力量將得到進一步強化。"
  },
  Item_10107_Name = {
    Text = "密契拓寫（已廢棄）"
  },
  Item_10108_Desc = {
    Text = "王國貨幣的優雅代稱。處處皆可獲取，事事皆需使用。"
  },
  Item_10108_Name = {
    Text = "薔薇金券"
  },
  Item_10110_Desc = {
    Text = "主屬性從界域精通、黑印掉落、死亡抵抗和傷害強效中隨機獲得1個。"
  },
  Item_10110_Name = {
    Text = "機械降神Ⅵ"
  },
  Item_10110_StoryDesc = {
    Text = "機械是絕對純淨。"
  },
  Item_10111_Desc = {
    Text = "主屬性從暴擊率、暴擊傷害、銀鑰充能等級和狂氣回充等級中隨機獲得1個。"
  },
  Item_10111_Name = {
    Text = "36室之環Ⅰ"
  },
  Item_10111_StoryDesc = {
    Text = "旋轉，然後遺忘——這是她生命的全部。"
  },
  Item_10112_Desc = {
    Text = "喚醒儀式後，殘留在「黑池」中的浮沫。或許只有來自其他維度的商人能領會它的價值？"
  },
  Item_10112_Name = {
    Text = "根源浮沫（已廢棄）"
  },
  Item_10113_Desc = {
    Text = "漏風的家。總比沒有的好。\n被遺留的蛹殼。用於提升血肉界域喚醒體的技能等級。"
  },
  Item_10113_Name = {
    Text = "風乾蟲蛹"
  },
  Item_10114_Desc = {
    Text = "那是古老意志的失落靈識。 彌薩格通過神秘的儀式啟發喚醒體的靈識，受到啟發的喚醒體將永久增強精神能力。\n重複獲得「24」時轉換獲得，用於啟動「24」的啟靈。"
  },
  Item_10114_Name = {
    Text = "殘片·「24」"
  },
  Item_10114_StoryDesc = {
    Text = "重複獲得「24」時轉換獲得，用於啟動「24」的啟靈。"
  },
  Item_10115_Desc = {
    Text = "主屬性從暴擊率、暴擊傷害、界域精通和黑印掉落中隨機獲得1個。"
  },
  Item_10115_Name = {
