  },
  Item_116596_Name = {
    Text = "覲見奉禮"
  },
  Item_116597_Desc = {
    Text = "面見聖子所必須的證明，為聖子展示你嚮往光明的決心吧。\n\n至少掉落{s1}個"
  },
  Item_116597_Name = {
    Text = "覲見奉禮"
  },
  Item_116715_Desc = {
    Text = "用藤環與鳥羽製作的簡易捕夢網，有著並不可靠的靈性，使用後大部分時候會失敗，有時能夠打撈起夢殘缺的碎片，大多只是一些快速閃回的畫面。"
  },
  Item_116715_Name = {
    Text = "暗淡捕夢網"
  },
  Item_116716_Desc = {
    Text = "以奇異的古老鳥骨捆製成的捕夢網，能夠將夢境纖毫畢現地呈現在你的腦子裡，就像你真的經歷過那些故事，見過那些夢裡的人。美夢雖好，小心沉迷。"
  },
  Item_116716_Name = {
    Text = "蜃景捕夢網"
  },
  Item_116717_Desc = {
    Text = "用鹿皮繩與水晶點綴的捕夢網，形似眼珠的寶石賦予了它更好的靈性，使用後能夠窺見模糊而完整的夢境。逃避現實的人啊，努力去打撈一個美夢吧。"
  },
  Item_116717_Name = {
    Text = "靈光捕夢網"
  },
  Item_116762_Desc = {
    Text = "獲得幻衣「幻夢假日」後解鎖。\n「守密人，要和我走走，去海邊吹吹風嗎？」"
  },
  Item_116762_Name = {
    Text = "環行·拉蒙娜·幻夢假日"
  },
  Item_116763_Desc = {
    Text = "對於環行·拉蒙娜而言，生命是場匆促而往復的試煉。\n訓練，解決謎團，演算世界能夠邁向未來的機率，然後親眼見證那些她想要拯救的、渴望守護的美好破碎。\n一次又一次。\n再後來，生命是孤獨而無止境的等待。\n她在已經失去希望的破滅世界，仰望無垠的純黑色夜空，期待著來自遙遠維度的呼喚。\n一日又一日。\n這是她的宿命，她也習慣了這宿命，接受了這宿命，直到——\n「拉蒙娜，我們可是在度假，不要板著臉，笑一下啦~」\n「拉蒙娜，你看到了嗎？莉莉她們堆了個城堡，要不我們也加入？」\n「拉蒙娜，夏天怎麼能缺少霜淇淋！今天我請客，來，這是你的。」\n「拉蒙娜……」\n「拉蒙娜。」\n「拉蒙娜！」\n一聲又一聲熟悉的呼喚裡，夏日的陽光肆無忌憚地炙烤著萬物。\n她看到沙灘上的「城堡」在陽光下熠熠生輝，也感受到霜淇淋融化在手上留下的黏膩觸感。\n海水是涼的，沙子是熱的，墨菲準備的吉事果是甜的，萊克宴請的奎寧水是苦的。\n這一切都是那麼新奇，令她剋制不住想要感受更多，品味更多。\n最重要的是，那個人還在，就在她身旁，這樣的鮮活，這樣的真實。\n就好像曾經的那些毀滅、崩壞、痛苦、絕望，才是幻覺。\n“……”\n陽光炙曬的海濱裡，環行·拉蒙娜沉默，然後，緩慢而堅定地露出笑容。\n「是的，我們是在度假，所以守密人，要和我走走，去海邊吹吹風嗎？」\n與此同時，那無垠純黑色夜空下的她，也在淚水浸濕的眼罩下，於不願甦醒的清醒夢裡，露出了同樣的笑容。\n這次，她終於擁有了那些破碎過無數次的美好。\n哪怕，只是一場幻夢。"
  },
  Item_116763_Name = {
    Text = "幻夢假日"
  },
  Item_116764_Desc = {
    Text = "解鎖後，完成「銘刻的啟程」全部任務可額外獲得以下獎勵"
  },
  Item_116764_Name = {
    Text = "銘刻的啟程"
  },
  Item_116792_Desc = {
    Text = "「來啊，快活啊~」"
  },
  Item_116792_EmojiName = {Text = "引誘"},
  Item_116792_Name = {
    Text = "泰旖絲·引誘"
  },
  Item_116872_Name = {
    Text = "艾瑞卡房樹人"
  },
  Item_116873_Name = {
    Text = "莉莉房樹人"
  },
  Item_116874_Name = {
    Text = "奧爾拉房樹人"
  },
  Item_116875_Name = {
    Text = "我的房樹人"
  },
  Item_116878_Desc = {
    Text = "屬性為界域精通的命輪。"
  },
  Item_116878_Name = {
    Text = "你我終將重逢"
  },
  Item_116878_StoryDesc = {
    Text = "你和拉蒙娜從未約定再次相見。\n門扉在眼前緩緩合攏的刹那，你們心中劃定的別離的時限，已是註定的永恆。\n\n所以，當她在時光的罅隙裡，轉瞬即逝的相逢裡輕輕勾起你的小指……\n這已經是預期之外、足夠幸運的重逢。\n「你一點都沒有改變。」她說。\n\n為了這一句話語，為了指尖微弱的溫度……縱然遙隔兩個世界，你仍願傾盡所有，飛躍銀河與她相見。\n明年今日，勾指起誓。"
  },
  Item_117263_Desc = {
    Text = "逸散在不知誰的夢境中的情緒粒子，碰觸時彷彿能聽到誰回望來路時的迷茫低語。\n用於提升守密人在調查事件「樂園」中的共鳴。"
  },
  Item_117843_Desc = {
    Text = "彌薩格定期進行的太陽黑子輻射測量，用於排除喚醒體所受精神干擾。"
  },
  Item_117843_Name = {
    Text = "輻射監測"
  },
  Item_117844_Desc = {
    Text = "彌薩格定期進行的月球距離測量，用於確認黑池內銀芯的穩定性。"
  },
  Item_117844_Name = {
    Text = "月距遙感"
  },
  Item_117845_Desc = {
    Text = "彌薩格定期進行的潮汐水位測量，用於監測深海之內的銀芯豐富度指標變化。"
  },
  Item_118128_Desc = {
    Text = "記錄此鑰令後，可在編隊時選擇鑰令技能：「偏航船」。\n\n深海的使徒虔誠地跪伏於少女的階下，獻上名為忠貞之吻。\n在錯誤的航向上，她已經行進了太遠。"
  },
  Item_118128_StoryDesc = {
    Text = "海的使徒虔誠地跪伏於少女的階下，獻上名為忠貞之吻。\n在錯誤的航向上，她已經行進了太遠。"
  },
  Item_118305_Desc = {
    Text = "深潛經驗達到一定值時，深潛等級提升。可在幻夢深潛中獲得。"
  },
  Item_118305_Name = {
    Text = "深潛經驗"
  },
  Item_119011_Desc = {
