  Item_119432_Desc = {
    Text = "極少數守密人才能擁有的身分標識。\n筆尖是你的刻刀，以墨跡為磚石，在語言的裂隙中重建通天之塔。"
  },
  Item_119432_Name = {
    Text = "巴別塔之章"
  },
  Item_119432_StoryDesc = {
    Text = "本地化志願者頭像框"
  },
  Item_119689_Desc = {
    Text = "獲得幻衣「孽宴狂欲」後解鎖。\n「來吧小樹苗，釋放你的欲望，加入永不停息的狂歡吧！」"
  },
  Item_119690_Desc = {
    Text = "啪答……啪答……\n作為亞蘭最優秀的獵手，我早已習慣了各種惡劣的環境——沙漠、雨林、沼澤，甚至是充滿胃酸的巨獸腹中，都不會讓我產生一絲一毫的動搖。\n但不知為何，當我感受到身上這粘稠的液體時，我還是不適地抖了抖身子，就好像這是人類完全不能接觸的孽物。\n「好孩子……好孩子……」\n我變成了一個嬰兒？現在還不確定，但可以肯定，我的身體發生了某種變化。\n有一雙溫暖的手把我輕輕抱起，沒入身後哺育者的懷抱，同時一股飽滿的欲望纏裹著我，卻如羊水般溫暖令我安心。\n我嘗試了幾次，終於睜開了眼，但眼前令人恐懼的景象讓我不自覺地扭動身體，試圖將整個軀體沒入豐滿的乳房。\n那是觸手扭曲交錯的犄角、將頭部縱向分開的巨口、不斷滴落的綠色粘液，我從未見過這種恐怖的怪物……我本想移開視線，卻發現自己如同著魔一般，只能目不轉睛地盯著眼前的畸形之物。\n它們同樣在目不轉睛地盯著我，我輕易地從眼神中讀出了它們對我肉體的渴望。\n可為什麼……那瘋狂的眼神中，卻帶有如此純粹的期待？\n「乖孩子……別害怕……」\n如母親般溫柔的話語在我耳畔響起，那是溫暖的手掌拂過全身的感覺，這一刻我的心情突然變得平靜，彷彿身後之人真的是我的母親，而我此刻正處於最安全的港灣裡。\n雖然我的理性告訴我這並不可能，但我還是撒嬌似地蹭了蹭她正在幫我梳理毛髮的……等等……梳理毛髮？\n意識到什麼的我嘗試觸摸自己，卻發現眼前的並非是我那雙佈滿傷痕手，而是一隻漆黑的羊蹄。\n啊……原來如此……原來這才是我本來的樣貌，這才是母親賦予我的……\n當我意識到這一點時，血脈最深處所埋藏的一切瞬間浮現在我的眼前，我理解了我的身分、我的使命以及……我那無法被抑制的欲望。\n「吼——————！！」\n我迫不及待的從母親的懷中跳下，發出震耳欲聾的怒吼，衝入了兄弟姐妹之中。\n我要履行我的職責，我要踐行母親的意志。\n\n「吼——————————！！！！！！」\n隨著我的加入，所有兄弟姐妹同時發出興奮的狂吼，這吼聲震撼天地，宣告了宴會的開場。\n我們舔舐，我們糾纏，我們用粗大的觸手深入對方的每一個角落，隨後相互撕咬，任由彼此的血肉相互交融。\n我們向外奔去，無差別地吞噬眼前的所有，我們是狂欲之母降下的不祥子嗣，是這場孽宴上的唯一主角。\n無需壓抑自己的欲望，我們已褪去凡俗的外殼，我們將肆意吞噬，肆意繁衍，肆意釋放傳承自母親的無上欲望。\n這是場獻給母親的宴會，我們要把這世界化為污孽的血肉，獻給至高無上的母親！\n\n泰旖絲站在宴會中央，聆聽世界被吞噬的哀嚎。\n「沒錯，就是這樣。」\n看著已經完全踏入狂歡的子嗣，慈愛的母親露出了最本質的瘋狂。\n「去吧，去吧，無需再用那脆弱之物偽裝，向世界展示你們真實的模樣吧！」\n薄紗隨著舞步在空中飛舞，從中透出那抹若隱若現的蜜色。\n「你們是原初的使徒，你們不需要任何人承認，你們已無需再壓抑自己那不被世俗認可的欲望！」\n這是一支不會停息的舞，這是一場不會停止的孽宴。\n「去將這個世界，全部變成你們的兄弟姐妹吧！」"
  },
  Item_119952_Desc = {
    Text = "記錄此鑰令後，可在編隊時選擇鑰令技能：「重逢心願」。\n\n萬千思念化作流星，奔赴向你們再一次的相逢。"
  },
