  Item_120491_Desc = {
    Text = "記錄此鑰令後，可在編隊時選擇鑰令技能：「來自霧境」。\n\n那個世界的霧境調查團先鋒「茉夏」，是她。\n這個世界經受銀與血洗禮的「茉夏」，也是她。\n這張帶有「家鄉」氣息的工牌，是這場跨越維度的旅行的永恆見證。"
  },
