  Item_120965_Desc = {
    Text = "在「學期課題」中購買「核心課題」後可獲得。\n「彌薩格內部發行的限量郵票，同時也是某個俱樂部的門票之一，可以跟某位女士兌換一次奇妙的服務。」"
