    Text = "迷霧之源"
  },
  Item_122409_Desc = {
    Text = "「迷霧」外圍散溢出的物質，據說茉夏正在收集它們，用作提供給迷霧之源的養分。\n\n至少掉落{s1}個"
  },
  Item_122409_Name = {
    Text = "迷霧之視"
  },
  Item_122410_Desc = {
    Text = "在活動「霧境的燔禮」中完成成就獲得。\n「我叫茉夏，這次可要好好記住喲。」"
  },
  Item_122410_Name = {
    Text = "以銀鑰之名：茉夏"
  },
  Item_122410_StoryDesc = {
    Text = "茉夏玩法活動"
  },
  Item_123321_Desc = {
    Text = "解鎖後，完成「銀霜紀行」全部任務可額外獲得以下獎勵"
  },
  Item_123321_Name = {
    Text = "銀霜紀行"
  },
  Item_123478_Desc = {
    Text = "在「學期課題」中購買「核心課題」後可獲得。\n「純全無罪的蒼白使者啊，願父神庇佑你將行之路。」"
  },
  Item_123478_Name = {
    Text = "永不褪色的昨天：薩爾瓦多"
  },
  Item_123478_StoryDesc = {
    Text = "第28期學期課題"
  },
  Item_123481_Desc = {
    Text = "在「學期課題」中購買「核心課題」後可獲得。\n「守密人，昨天我送你的圍巾……喜歡麼？」"
  },
  Item_123481_Name = {
    Text = "永不褪色的昨天：艾繼絲"
  },
  Item_123481_StoryDesc = {
    Text = "第28期學期課題"
  },
  Item_123482_Desc = {
    Text = "在「學期課題」中購買「核心課題」後可獲得。\n「殺！殺！殺！！哈哈哈！鱒魚鮮血的香氣！」"
  },
  Item_123482_Name = {
    Text = "永不褪色的昨天：尤烏哈希"
  },
  Item_123482_StoryDesc = {
    Text = "第27期學期課題"
  },
  Item_123483_Desc = {
    Text = "在「學期課題」中購買「核心課題」後可獲得。\n「我會用這曾束縛我的鐵鏈，撕碎所有妄圖給我帶上枷鎖之人！」"
  },
  Item_123483_Name = {
    Text = "永不褪色的昨天：血鏈·希洛"
  },
  Item_123483_StoryDesc = {
    Text = "第26期學期課題"
  },
  Item_123484_Desc = {
    Text = "在「學期課題」中購買「核心課題」後可獲得。\n「玫瑰盛開的光景還是如此賞心悅目，來共飲一杯吧，我的朋友。」"
  },
  Item_123484_Name = {
    Text = "永不褪色的昨天：索蕾爾"
  },
  Item_123484_StoryDesc = {
    Text = "第27期學期課題"
  },
  Item_123485_Desc = {
    Text = "在「學期課題」中購買「核心課題」後可獲得。\n「今天孩子們會帶回來什麼呢？」"
  },
  Item_123485_StoryDesc = {
    Text = "第27期學期課題"
  },
  Item_123486_Desc = {
    Text = "在「學期課題」中購買「核心課題」後可獲得。\n「啊……請賜予我更多的疼痛吧~」"
  },
  Item_123486_Name = {
    Text = "永不褪色的昨天：雷婭"
  },
  Item_123486_StoryDesc = {
    Text = "第29期學期課題"
  },
  Item_123487_Desc = {
    Text = "在「學期課題」中購買「核心課題」後可獲得。\n「夜深了，小樹苗。來讓我們繼續……昨日未盡興之事吧~」"
  },
  Item_123487_Name = {
    Text = "永不褪色的昨天：泰旖絲"
  },
  Item_123487_StoryDesc = {
    Text = "第28期學期課題"
  },
  Item_123552_Desc = {
    Text = "「好漂亮的雪花糖啊……哎？誰說我想要！不過不收下你會失望的吧……多謝了。」"
  },
  Item_123552_Name = {
    Text = "薑餅派對·凱刻斯"
  },
  Item_123553_Desc = {
    Text = "「銀霜夜快樂，守密人。喏，這是禮物。」"
  },
  Item_123553_EmojiName = {
    Text = "給你禮物"
  },
  Item_123553_Name = {
    Text = "波呂克斯·給你禮物"
  },
  Item_123554_Desc = {
    Text = "「哎呀哎呀，猜猜魔法大師丟來的盒子裡，是禮物還是炸彈？」"
  },
  Item_123554_Name = {
    Text = "卡茜亞·扔"
  },
  Item_123555_Desc = {
    Text = "「能否請您與我在森林中駐足一小時？我想……再感受一次糖果屋的氣息。」"
  },
  Item_123555_Name = {
    Text = "薑餅派對·奧爾拉"
  },
  Item_123556_Desc = {
    Text = "「我會努力照亮大家的銀霜夜。」"
  },
  Item_123556_EmojiName = {Text = "發光"},
  Item_123556_Name = {
    Text = "法洛思·發光"
  },
  Item_123557_Desc = {
    Text = "「今夜，我們將饌飲薑餅和楓糖，來共慶這偉大派對！」"
  },
  Item_123557_Name = {
    Text = "薑餅派對·杜勒賽因"
  },
  Item_123558_Desc = {
    Text = "「冬渡節快樂，恩人。啊……帽子壓到羽毛了」"
  },
  Item_123558_EmojiName = {
    Text = "冬渡節快樂"
  },
  Item_123558_Name = {
    Text = "卡斯托爾·冬渡節快樂"
  },
  Item_123559_Desc = {
    Text = "不知名的存在在你的信箱裡留下了這封請柬——以及一些姜香撲鼻的碎餅乾渣。\n使用後可選擇一個尚未獲得的「薑餅派對」系列頭像。"
  },
  Item_123559_Name = {
    Text = "薑餅派對的請柬"
  },
  Item_123560_Desc = {
    Text = "傳說在銀霜夜的晚上將襪子掛在床頭，冬渡節清晨就能收到神秘禮物。切記，一定要掛洗過的襪子。\n使用後可選擇一個尚未獲得的「冬渡彌薩格」系列對戰表情。"
  },
  Item_123560_Name = {
    Text = "冬渡節的禮券"
  },
  Item_123561_Desc = {
    Text = "「幹什麼，你怎麼敢用這種不敬的表情看著本神母？！」"
  },
  Item_123561_EmojiName = {Text = "襪子"},
  Item_123561_Name = {
    Text = "誕妄·墨菲·襪子"
  },
  Item_123638_Desc = {
    Text = "孩子們在銀霜夜前夕準備的祈願箱，上面貼有寫著想要的禮物的字條。\n“我已經當了一年好孩子啦，這下冬渡使者總該給我禮物了吧！”"
  },
  Item_123638_Name = {
    Text = "銀霜祈願箱"
  },
  Item_123639_Desc = {
    Text = "只在冬渡節清晨出現的特殊禮物盒，被開啟後會迅速消失，因此鮮有人知曉這個秘密。\n“噓，這是好孩子跟冬渡使者之間的秘密哦。”"
  },
  Item_123639_Name = {
    Text = "冬渡禮物盒"
  },
  Item_123757_Desc = {
    Text = "在「學期課題」中購買「核心課題」後可獲得。\n「謝，謝謝您……啊！請不要靠近……會，會傷到您的……」"
  },
  Item_123757_StoryDesc = {
    Text = "第29期學期課題"
  },
  Item_124899_Desc = {
    Text = "記錄此鑰令後，可在編隊時選擇鑰令技能:「羅網轉輪」。\n\n紡織，丈量，以及裁斷。\n命運的神明無悲無喜，命運的紡輪亘古不息。"
  },
  Item_124899_Name = {
    Text = "羅網轉輪"
  },
  Item_124899_StoryDesc = {
    Text = "紡織，丈量，以及裁斷。\n命運的神明無悲無喜，命運的紡輪亙古不息。"
  },
  Item_125136_Desc = {
    Text = "屬性為傷害強效的命輪。"
  },
  Item_125136_Name = {
    Text = "玉蘭之餌"
  },
  Item_125136_StoryDesc = {
    Text = "那是我與父親移居海城的第二年、伊芙蓮在信中的哭訴使我心煩意亂、我已決意同她分別。這是由絲綢與烏木裝潢的富饒之地、所有食腐者都嗅到了它沉睡時的混亂、紙鈔的面值能換來等重的黃金、掌握了那些航線、就能以極小的成本撬動千萬倍的財富。\n然而伊芙蓮、也許是源於她晦澀難追的怪異血統導致的神經質、這個女人堅信所謂先祖的傳訊、東方有祂們的旁支所信奉的邪異神明、如同深海中的某種魚類、會懸垂下招搖美味的餌、將獵物引入一場難以察覺的緩慢進食。\n她錯了、海城沒有半絲來自海的鹹味。\n只有層層疊疊、馥郁到令人迷醉、又心生恐懼的白玉蘭。\n令我和父親同時陷落的白玉蘭。\n當我看到她的時候、那个名為「徐」的女人的身影出現在我視線中的第一秒、我就永遠不再可能從這片古老的陸地脫身了。\n她令人想要靠近、她令人想要占有、她令人想要@3\n她令人令人令人令人令人想要想要想要想要想要\n\n切碎割開砍碎永遠永遠永遠永遠永遠……@2@3@2！！\n啊、我為什麼來到這裡？我要帶走什麼？我是……誰？\n不再重要了、她邀請了我、我坐在那座大宅的桌前。\n早已與我一樣瘋狂的父親、臉上掛著乖順的笑、琳瑯滿目的配菜擺滿餐桌、顯得金屬帶蓋餐盤格格不入。\n\n徐逆著光線坐在夕陽中、光暈為她鑲上了一層絨絨的金邊、慢慢地、那把黑扇放下了。\n像伊芙蓮、像我幼時的玩伴、像朦朧間的艷遇……像我的母親。\n那是一張如同廟宇裡鎏金神像般端方美麗的臉。\n我沒有聽見吮吸聲、也沒有嗅到父親身上傳來的腥味、只是痴迷地注視著那張臉、以及那張臉的主人伸出一隻素白的手、揭開餐盤、撿拾出合適的肉、她用兩根細木棍將它鉗起、抬高。\n她喚我、烘烤過後的動物油脂滴在我的嘴角。\n「小先生、你該吃些東西。」\n我溫順而木訥地張開嘴。\n玉蘭花已經開了、它在簌簌地向我懸垂。\n——「無名者手記」"
  },
