  Item_127524_StoryDesc = {
    Text = "移動端登入活動頭像"
  },
  Item_127525_Desc = {
    Text = "「性能好、響應快、請選擇朵爾教授冠名授權的大型終端！」"
  },
  Item_127525_Name = {
