  Item_127525_StoryDesc = {
    Text = "PC端登入活動頭像"
  },
  Item_128552_Name = {Text = "車票"},
  Item_128659_Desc = {
    Text = "不僅祈歲節當天、接下來的整整半個月、磐龍古國四處都會洋溢著喜悅的氣氛。\n人們帶著禮物、四處走親訪友。所有象徵著財富、喜悅、以及祝福意味的好東西、都會帶著最美好的祝願被塞進這個禮盒。"
  },
  Item_128659_Name = {
    Text = "祈歲鴻運盒"
  },
  Item_128660_Desc = {
    Text = "在磐龍古國、每個孩子都盼望著祈歲節的到來。\n棗泥餅、花生酥、杏仁糖、還有父母長輩準備的壓歲錢、獲得這樣一份禮物、一定會度過吉祥如意的一年。"
  },
  Item_128660_Name = {
    Text = "祈歲吉祥箱"
  },
  Item_129143_Desc = {
    Text = "逸散在歡愉列車上的情緒粒子，觸碰時彷彿能聽到小「N」的笑聲。\n用於提升守密人在「疾馳的歡愉專列」中的共鳴。"
  },
  Item_129498_Desc = {
    Text = "貴賓積分達到一定值時、「雅室規格」等級提升。可在「疾馳的歡愉專列」中獲得。"
  },
  Item_129498_Name = {
    Text = "貴賓積分"
  },
  Item_129499_Desc = {
    Text = "紀錄此鑰令後、可在編隊時選擇鑰令技能：「歲末花火」。\n\n歲歲年年花相似、年年歲歲盼團圓。\n今夕祈歲、一枕之夢。願妾身的小茉莉花於故人身畔、攜手共賞萬千焰火之時、勿忘妾身情義。"
  },
  Item_129499_Name = {
    Text = "歲末花火"
  },
  Item_129499_StoryDesc = {
    Text = "歲歲年年花相似、年年歲歲盼團圓。\n今夕祈歲、一枕之夢。願妾身的小茉莉花於故人身畔、攜手共賞萬千焰火之時、勿忘妾身情義。"
  },
  Item_129628_Desc = {
    Text = "屬性為銀鑰充能等級的命輪。"
  },
  Item_129628_Name = {
    Text = "踏過泥濘的玫瑰"
  },
  Item_129628_StoryDesc = {
    Text = "在無法被記錄的某個循環中、環行·拉蒙娜踏過鐘樓後的花圃。\n餘光瞥見玫瑰園中、叢叢鮮花正綻放得妍烈。\n罕見的片刻停滯後、她便拋下所有無謂的遐思、繼續奔赴最終的戰場。\n泥濘潑濺在血色般濃烈的花瓣上、轉瞬被漆黑的融蝕漿吞噬、只留下風中傲然的背影。"
  },
  Item_129898_Desc = {
    Text = "在「學期課題」中購買「核心課題」後可獲得。\n「雅緻的餐品需要時間來雕綴，啊~我期待著，你那刻骨銘心的香味。」"
  },
  Item_129898_Name = {
    Text = "永不褪色的昨天：杜勒賽因"
  },
  Item_129898_StoryDesc = {
    Text = "第29期學期課題"
  },
