  },
  Item_130039_StoryDesc = {
    Text = "書架上除了枯燥的研究文獻之外，還有幾本看起來很有趣的兒童讀物。\n《灰姑娘》、《白雪公主》、《美人魚》、《乐佩公主》……它們的主人為何會將這些書收在書架上——如今已無從得知。\n\n那些故事編織著與現實截然不同的情節。「王子」、「公主」、「愛」……這些詞語令少女的心怦然悸動。\n\n夜空中閃爍的無數光芒傾灑向大地，彷彿即將匯成一條流淌的光之河。\n在灑落的月光中，少女悄悄踮起腳尖，假裝踩上一雙透明的玻璃鞋。彷彿一直在期盼著——這深沉、孤寂的漫漫長夜終將破曉……"
  },
  Item_130040_Desc = {
    Text = "純潔無瑕，令人心生親近的鱗粉，似乎和沙耶的苗圃能夠產生奇妙的共鳴。\n把它帶給沙耶，可以獲得來自她的獎勵。\n\n至少掉落{s1}個"
  },
