  },
  Item_130063_Desc = {
    Text = "記錄此鑰令後，可在編隊時選擇鑰令技能：「獻給新世界」。\n\n綻放，綻放，將整個世界染成歡喜的顏色。\n那是久遠的治癒，悠久的至福，是沙耶送給即將揭幕的新世界的，最後的禮物。"
