  Item_130224_Desc = {
    Text = "那是古老意志的失落靈識。 彌薩格透過神秘的儀式啟發喚醒體的靈識、受到啟發的喚醒體將永久增強精神能力。\n重複獲得沙耶時轉換獲得、用於激活沙耶的啟靈。"
  },
  Item_130224_Name = {
    Text = "殘片·沙耶"
  },
  Item_130224_StoryDesc = {
    Text = "重複獲得沙耶時轉換獲得、用於啟動沙耶的啟靈。"
  },
