  },
  Item_130547_StoryDesc = {
    Text = "第36期學期課題"
  },
  Item_130548_Desc = {
    Text = "在「學期課題」中購買「核心課題」後可獲得。\n「浪費科研時間來演話劇……不，我沒說不喜歡。咳咳，劇本上寫的是這個表情麼？」"
  },
  Item_130548_Name = {
    Text = "彌薩格幕間劇：朵爾"
  },
  Item_130548_StoryDesc = {
    Text = "第31期學期課題"
  },
  Item_130549_Desc = {
    Text = "在「學期課題」中購買「核心課題」後可獲得。\n「這是迷迭香，代表追憶；還有三色堇，代表思慮......啊，抱歉，我在念台詞。這段攜花而上的戲，我很喜歡。」"
  },
