  },
  Item_130554_StoryDesc = {
    Text = "第32期學期課題"
  },
  Item_130700_Desc = {
    Text = "小煤球，討厭，莫絲，喜歡！小煤球，上交，獎勵～\n\n至少掉落{s1}個"
  },
  Item_130700_Name = {
    Text = "海螺三號"
  },
  Item_130701_Desc = {
    Text = "小煤球，喜歡！莫絲，喜歡！收集，越多越好～\n\n至少掉落{s1}個"
  },
  Item_130701_Name = {
    Text = "海螺一號"
  },
  Item_130702_Desc = {
    Text = "朋友，喜歡，莫絲，收集！幫忙，獎勵！送給朋友～\n\n至少掉落{s1}個"
  },
  Item_130702_Name = {
    Text = "海螺二號"
  },
  Item_130703_Desc = {
    Text = "紀錄此鑰令後、可在編隊時選擇鑰令技能：「溺亡的純真」。\n\n即使深知注定溺亡、她依然義無反顧地投身冰冷的大海。\n因為這是她純真的思維中、拯救朋友的唯一方法。"
  },
  Item_130703_Name = {
    Text = "溺亡的純真"
  },
  Item_130703_StoryDesc = {
    Text = "即使深知注定溺亡、她依然義無反顧地投身冰冷的大海。\n因為這是她純真的思維中、拯救朋友的唯一方法。"
  },
  Item_130704_Desc = {
    Text = "專注於增幅使用者狂氣爆發的命輪、能夠在探索中周期性回覆狂氣並提高其狂氣爆發傷害、切換至怒濤姿態時提供大量界域精通。"
  },
  Item_130704_Name = {
    Text = "渺遠的伊甸園"
  },
  Item_130704_StoryDesc = {
    Text = "這是一座沒有記錄在任何海圖上的島嶼。\n從它誕生之初，名為「文明」的病毒便從未踏上過這片淨土。\n這裡只有沙灘，叢林，一眼望不到頭的大海，以及……一位小小的少女。\n………………………………\n「爸爸，媽媽，魚！」\n「嗷~~」\n兩隻海豚不緊不慢地游到少女腳邊，發出優美清脆的叫聲。\n其中一隻將少女馱起，另一隻接過少女手中剛被打暈的魚，一口將其吞下。\n「嗷~~」\n「嘿嘿，莫絲！厲害！」\n像不諳世事的孩童，少女做了個很有力量感的動作，來回應「爸爸」「媽媽」的誇獎。\n「今天，太陽！好！」\n「莫絲！爸爸！媽媽！散步！」\n聽聞少女的話，馱著少女的海豚輕吟一聲，繞著小島開始緩緩游動。\n溫暖的陽光灑在少女身上，驅散了數日前揮之不去的濕冷，輕柔的風拂過少女的髮絲，帶來了海洋慵懶的呼吸。\n笑聲，拍水聲，嬉鬧聲，與世隔絕的小島上沒有「文明」帶來的煩惱，只留下了最原始、最純粹的歡笑。\n兩獸一人如往常一樣，度過了原始又無憂的一天。\n………………………………\n直到那無邊的呼喚，將這份靜謐徹底吞噬。\n「回來吧……回來吧……」\n「@1需要你……@2……@4……需要你……」"
  },
  Item_130705_Desc = {
    Text = "朋友，喜歡，莫絲，收集！幫忙，獎勵！送給朋友～\n\n至少掉落{s1}個"
  },
  Item_130705_Name = {
    Text = "海螺二號"
  },
