  Item_130727_Name = {
    Text = "被囚禁的瘋狂"
  },
  Item_130727_StoryDesc = {
    Text = "吃掉吃掉吃掉吃掉……\n幻惑的魇思。\n碾碎碾碎碾碎碾碎……\n大海的喃喃自語。\n摧毀！摧毀！！摧毀！！！摧毀！！！！\n無法抑制的瘋狂。\n「莫絲好餓。」\n少女吞下滴淌鮮血的肉塊、可無論吃多少都無法緩解胃裡的虛無。\n「莫絲好渴。」\n少女咽下散發腥腐的海水、可無論喝多少都無法解除喉嚨的乾澀。\n「莫絲好困。」\n少女殴打麻木清醒的自己、可無論睡多久都無法抑制思維的疲憊。\n因為只有純粹的破壞、才能滿足體內的祂。\n「但是、莫絲、不要！」\n可少女拒絕了宿命的呼喚、特製的鋼鐵成了她無法退下的牢籠。\n她將自己打造成堅不可摧的監獄、用名為自己的拘束、囚禁了來自深海的瘋狂。\n「莫絲、關住了、壞蛋！」\n至此、自AF 1■■出現、吞噬無數生靈的大漩渦默斯克斯、於AF 31■、徹底歸於靜默。\n\n\n\n\n"
  },
  Item_130728_Desc = {
    Text = "朋友，喜歡，莫絲，收集！幫忙，獎勵！送給朋友～\n\n至少掉落{s1}個"
