  Item_132906_Desc = {
    Text = "獲得幻衣「臨時文本」後解鎖。\n「臨時文本」"
  },
  Item_132906_Name = {
    Text = "阿拉克涅·臨時文本"
  },
  Item_133338_Desc = {
    Text = "爆發性提供暴擊傷害增益的輔助型命輪"
  },
  Item_133338_Name = {
    Text = "私密午歇時間"
  },
  Item_133338_StoryDesc = {
    Text = "晨間的騎行要與郡中的鄉紳們並轡，探聽改革案的立場；冷餐會上要同各家的夫人交換得體的恭維，長桌晚宴要在銀燭台的光影裡聆聽那些冗長而虛偽的餐前禱詞，歌劇散場後還要在包廂的走廊裡應付沒完沒了的社交寒暄。\n\n「唯有後園草坪上的下午茶，是真正屬於我自己的時光。」\n「這可是我第一次邀請下午茶嘉賓，我將選擇話題的權力讓渡予你。」\n\n索蕾爾端起剛斟滿的紅茶。\n「你想要知道德·克雷梅伯爵在最新提交的議院改革案上的立場？或者博蒙納家族在兩黨之間微妙的押注？又或者單純對某位子爵小姐的秘密感興趣？」\n「全都不用？你只想知道我桌上的粉色甜點的味道？」\n她輕啜一口，原本望向遠方的目光落回你的身上。\n「那就好好品嚐一下吧。」\n「有些滋味，確實要自己動手，才能感同身受。」\n「你說對不對啊，我尊敬的——那位大人？」\n\n身著彌薩格校服的來客的領口和袖口黑霧四溢，霧氣很快滾動成一團濃黑的混沌。\n「嘻嘻嘻，你當真覺得，自己可以逃脫宿命嗎？」\n「陽光正好，我想要先享受我難得的清閒時光。想要品鑑時下最流行的紅茶和海綿蛋糕，請便。其他事情，還請在午歇時間結束後再來吧。」"
  },
  Item_133339_Desc = {
    Text = "解鎖後，完成「楓丹茶韻」全部任務可額外獲得以下獎勵"
  },
  Item_133339_Name = {
    Text = "楓丹茶韻"
  },
  Item_133355_Desc = {
    Text = "持續提供銀鑰能量的命輪，綻放時擁有更強大的效果。"
  },
  Item_133355_Name = {
    Text = "櫻花下的迷思"
  },
  Item_133355_StoryDesc = {
    Text = "作為彌薩格的優等生，拉蒙娜成功將理智與理性作為行事的絕對邏輯，保持著冷靜，保持著微笑，保持著無與倫比的可靠。\n但偶爾，這樣的拉蒙娜也會陷入迷思中，在面對世界的絕對恐怖，或者絕對的絢爛之時——\n注視著無邊無際，佔滿了所有視線的粉色，拉蒙娜無聲沉默。\n據她所知，不超過三週，櫻花就會從初開到落盡，所以這沉甸甸壓滿枝頭的花朵，縱橫而繁茂的枝葉，很快便會衰頹，陷入荒涼與蕭索。\n而人的可預期生命，遠不止三週，遠不止三年，遠不止三十年，卻也如這些櫻花樹，只有一次。\n人最大的幻覺，就是相信自己會永遠活著。\n拉蒙娜明白。\n花開花落，是自然界再普通不過的規律，而人的生死，歸根結底也只是自然界的現象罷了。\n拉蒙娜也明白。\n但生而為人，總是想要為自己的存在賦予意義，每個新生，也是為此，踏入了彌薩格的大門。\n他們是對抗融蝕的先行者，是守望人類未來的重要防線。\n他們的生命，不僅僅只是客觀的自然現象，哪怕注定消亡，也在切實改變著這個世界的軌跡。\n而在這期間，他們並肩戰鬥，風雨同行。\n就像一棵樹上的一朵花，依偎著另一朵花，一同含苞待放，一同飄搖墜落，一同盛開與枯萎。\n現在，該回去了。\n那朵可以依靠她，也值得她依靠的花朵，還在等著她。"
  },
  Item_133404_Desc = {
    Text = "在「學期課題」中購買「核心課題」後可獲得。\n「鏘鏘~這裡是您點的美食道具套餐~」"
  },
  Item_133404_Name = {
    Text = "彌薩格幕間劇：珈倫"
  },
  Item_133405_Name = {
    Text = "彌薩格幕間劇：塔薇"
  },
  Item_133406_Desc = {
    Text = "「啊啊啊！我不要看這些啊！」"
  },
  Item_133406_StoryDesc = {
    Text = "第32期學期課題"
  },
  Item_133477_Desc = {
    Text = "尚能行動的右手拖著少女殘破的軀體，緩緩地向漆黑的淤泥蠕動。\n鐵鏈交錯的響聲迴盪在空無一人的監牢裡，沒人會在意一個奴隸的死活，見證這一切的只有牆角的累累白骨。\n她不知道自己是否會成為這些白骨中的一員，她只知道，人們是如此畏懼它的力量。\n\n「起碼不會……比現在更差了……」\n\n淤泥順著少女纖細的食指逆流而上，瞬間覆蓋少女全身。\n它開始翻湧，開始沸騰，它像是終於找到了注定之人般欣喜若狂。\n許久，監牢內重歸平靜，扭曲的雙手從繭狀的淤泥中刺出，撕開了隔絕她與世界的最後壁障。\n少女平靜地注視著已經異化為黑色膿液的四肢，四肢和脖頸上的鐵鏈在全新的力量前脆弱不堪，她第一次感到如此輕鬆。\n她貪婪地呼吸著監牢內的空氣，儘管此刻周圍充滿生物屍體和排泄物的腐臭，但她毫不在乎。\n因為她終於品嚐到了，自出生起就夢寐以求的——自由的味道。\n監牢已破，復仇女神開始揮舞她的利爪，向所有奴役者發起復仇。\n……………………\n人們哭喊。\n「救，救命啊！這個奴隸發瘋了！衛兵！衛兵在哪？！」\n人們哀求。\n「不要殺我！求求你放了我……我，我把所有錢都給你！」\n人們逃竄。\n「王已經死了！快逃，快逃啊！她不是人……她不是人！」\n人們沉默。\n「…嗚…………呃………」\n……………………\n少女停止了屠殺，隨手拋下面容扭曲的頭顱，那是一副因異物堵塞呼吸道，窒息而死的模樣。\n宣洩過後的少女開始思考，她到底要做什麼。\n風裹挾著淤泥和血污，肆意塗抹著屍橫遍野的城邦。\n最終，少女踏出腳步。\n她將作為一個戰士，一個永不停歇的戰士，去埋下自由的種子。\n她將一路向北，直至極地盡頭。"
  },
