  },
  Item_133706_Desc = {
    Text = "「在很多、很多很多年以前，人類還沒有誕生的時候，鸚鵡螺就存在了。」\n「它們的螺殼記住了洋流的方向、海水的溫度、陸與海的變遷。」\n「它們也記住了所有的聲音，你聽。」\n年幼的諾締拉好奇地把海螺貼到耳邊，眼前的海浪在礁石上拍打，螺殼中傳來的浪潮聲在諾締拉的耳邊拍打。\n她驚喜地睜大了眼睛。\n「媽媽，如果我對它說話的話，下次我們重逢的時候，它也會記住我嗎？」\n那些溫柔的回答後來和海邊的風一起消散了，答案無人知曉。小小的諾締拉嘀嘀咕咕地和海螺說了很久的話，但擔心這個過小的殼沒辦法裝進太多，想了又想，最後決定留下最重要的一句。\n「你好，海螺，我會成為一個偉大的冒險家，再去找你的。等再見面，我一定能記得你，所以，約好了，你也要記得我啊！」\n後來、後來……\n後來發生了什麼呢，那已經是很多年以前的事情了。\n諾締拉覺得自己遺忘了什麼重要的事情，但就像螺殼會替鸚鵡螺記住一樣，諾締拉救了自己的朋友，她總覺得自己應該這麼做，因為似乎有人曾經為她做過。\n所以她偉大的冒險戛然而止，就像所有的冒險家都會有一個突如其來的結尾，她沉沉地向大海深處墜去。\n看到那枚快要被融蝕漿吞沒的鸚鵡螺時，諾締拉好像想起來了。\n這好像是很久之前的下午，被她放入大海的海螺。\n「下次我們重逢的時候，它也會記住我嗎？」\n在痛苦的窒息來臨之前，在最後一口空氣被水壓從肺中擠出去之前，諾締拉拼盡全力伸出手，把海螺貼到了耳邊。\n它伸出了濡軟的腹足。\n諾締拉什麼都沒能聽見。"
  },
  Item_133706_Name = {
    Text = "螺紋回音"
  },
  Item_133766_Desc = {
    Text = "與靈魂共鳴之物，如今只殘餘輪廓碎片。願散落各地的希望的聚合能帶來穿透現實的增幅。\n可以在「冶煉室」中合成「靈魂回溯之芯」。"
  },
  Item_133766_Name = {
    Text = "靈魂回溯碎片"
  },
  Item_133767_Desc = {
    Text = "可以窺見命運碎片的螺旋視窗，如今只殘餘輪廓殘片。願散落各地的希望的聚合能帶來穿透現實的增幅。\n可以在「冶煉室」中合成「命途回溯之芯」。"
  },
  Item_134301_Name = {
    Text = "初夏盛遊箱"
  },
  Item_134392_Desc = {
    Text = "屬性為黑印掉落的命輪。"
  },
  Item_134392_StoryDesc = {
    Text = "你漫步於星雲之間，見證流星一顆接一顆隕落。\n有些滾燙，有些耀眼，有些冰冷，有些灰暗——來不及告別，它們便拖著長尾，從天幕上逐一淡去。\n你捧起灰燼，想將存在的痕跡銘刻於心。\n但那些影像終究穿過指縫，穿過日漸稀薄的記憶，飛散在無垠時空裡。\n原來你也不過是萬千星雨中的一顆。\n但你不會停下。你要走下去，穿過漫長的寂滅，直至下一個紀元。\n直至繁星漫天。"
  },
