  Item_140416_Desc = {
    Text = "「以靈魂為樂器，演奏宇宙的共鳴。\n這混沌、無序、狂亂的音樂，為揭示世界的真相而鳴響。」"
  },
  Item_140416_Name = {
    Text = "不諧音合奏"
  },
  Item_140416_StoryDesc = {
    Text = "V2.5.1頭像禮包"
  },
  Item_140417_Desc = {
    Text = "第一樂章，起。在他高抬的雙手落入靜息之前，整座宇宙都迴響著終末的奏鳴之聲。"
  },
  Item_140417_Name = {
    Text = "寰宇奏鳴"
  },
  Item_140418_Desc = {
    Text = "「玫瑰滴落鮮血，於火中化作最後的詩章。優雅、浪漫、以及悄無聲息的淚珠。」"
  },
  Item_140418_Name = {
    Text = "玫瑰的詩章"
  },
  Item_140418_StoryDesc = {
    Text = "V2.5.1頭像禮包"
  },
  Item_140459_Desc = {
    Text = "在舉起指揮棒之前，世界充滿了令人厭惡的噪聲。\n父親的嚴苛手掌無數次重重落在琴蓋，宮廷走廊的蚊蠅竊竊私語，報紙上關於他的討論喋喋不休。\n「安靜。」\n@3皇家歌劇院，@3六年春。\n年輕的宮廷樂師第一次站上首席指揮的台階，質疑與期待的聲音同樣強烈。他是如此年輕、沉默，帶著他明亮灼人的天賦，如同一尊從未被允許現世的瓷器。如今，這尊瓷器第一次在殷紅的舞台上舉起指揮棒。\n在指揮棒抬起的一瞬間，整座劇院的空氣便被某種無形的力量攫住。那是引力與潮汐，是音樂的宇宙裡不可違逆的公理。\n指揮棒落下，音符撕開寂靜的帷幕，首席小提琴手的弓弦輕輕顫抖。他早已忘記面前站著的是一個比他小了五十歲的孩子，指揮棒的弧線帶領著他，他的手指已不再屬於自己。\n弦樂湧入，銅管應和，定音鼓在精確的節點炸響。每一個聲部都被無形的絲線牽引，臣服於指揮台上那些優雅的軌跡。\n哈姆林的嘴唇抿成一道冷淡的弧線，蒼白年輕的面孔精緻得近乎不真實。指揮棒的每一次揮動都帶著不容置疑的命令，從第一次握住指揮棒時他便清晰地知道，音樂從不是被演奏，而是被統治的。\n樂章行至華彩段，哈姆林望向木偶般的樂手，他的眼裡沒有任何人。在關於音樂的舞台上，他是唯一的獨裁者。\n終章。最後一個音符消亡在寂靜中，長久的沉默後掌聲如潮水般湧來。\n今天的頭條是屬於哈姆林的。年輕的天才收穫了從未有人收穫的名譽與追捧。面對此生第一次萬眾狂熱的喝彩，年輕的指揮家臉上沒有絲毫的笑意。\n他鞠躬，緩緩放下指揮棒，離開了人生第一次登上的舞台，推拒了宮廷的筵席，回到了他的琴房。\n凡庸的樂手，不夠精準的顫音，偏差了八分之一拍的呼吸——一切的瑕疵，都是對音樂的褻瀆。在滿堂喝彩中，他聽見了唯一真實的聲音：頭頂那座遙不可及的穹頂之後，有什麼東西正在為他鳴響。祂呼喚他，斥責他，等待他。他們終將相遇，在相遇的那一刻，他必須是完美的。\n那一天，惡魔樂師的序曲征服了他的第一座舞台。\n而那漫長的通往神祇的樂章，才剛剛開始奏響。"
  },
  Item_140459_Name = {
    Text = "萬籟序曲"
  },
  Item_140460_Desc = {
    Text = "獲得幻衣「萬籟序曲」後解鎖。\n「慢了八分之一拍。一場失敗的演出。」"
  },
  Item_140460_Name = {
    Text = "哈姆林·萬籟序曲"
