  Item_141172_Desc = {
    Text = "眾所週知，深淵裡的魚會隨便亂長，過於碩大是正常的，與人類相似……也是正常的。\n\n至少掉落{s1}個"
  },
  Item_141172_Name = {
    Text = "碩大的「獵物」"
  },
  Item_141173_Desc = {
    Text = "眾所週知，深淵裡的魚會隨便亂長，過於碩大是正常的，與人類相似……也是正常的。\n\n至少掉落{s1}個"
  },
  Item_141173_Name = {
    Text = "碩大的「獵物」"
  },
  Item_141174_Desc = {
    Text = "記錄此鑰令後，可在編隊時選擇鑰令技能：「空心人」。\n\n讓我們來講述關於你這一生所經歷的故事，它不會再有回音。\n就像海水灌入深淵，然後永遠留在這裡。"
  },
  Item_141174_StoryDesc = {
    Text = "讓我們來講述關於你這一生所經歷的故事，它不會再有回音。\n就像海水灌入深淵，然後永遠留在這裡。"
  },
