  },
  Item_141200_Name = {
    Text = "碩大的「獵物」"
  },
  Item_141201_Desc = {
    Text = "眾所週知，深淵裡的魚會隨便亂長，過於碩大是正常的，與人類相似……也是正常的。\n\n至少掉落{s1}個"
  },
  Item_141201_Name = {
    Text = "碩大的「獵物」"
  },
  Item_141202_Desc = {
    Text = "屬性為暴擊傷害的命輪。"
  },
  Item_141202_Name = {
    Text = "指向歧路的羅盤"
  },
  Item_141202_StoryDesc = {
    Text = "游走在商船和商船間，總是把身形藏在破舊布褂陰影裡的老巫師說，羅盤會把人們引領到祂該去的地方，水手們嬉鬧著嘲笑她帶著草藥味的廢話，丟下五個雷歐坊，換走這個精緻的黃銅裝飾物。\n然後他們停靠在後來失去了名字的小鎮港口，龐托斯喜歡這個故事，羅盤的主人喜歡龐托斯。\n當然，沒有人不喜歡幽默、開朗，來去瀟灑得像一陣風的龐托斯。\n它原本應該是很好的紀念，是龐托斯轉贈給他親愛的外甥以後，開啟對遙遠彼方的遐想的鑰匙——但它讓龐托斯找不到他，龐托斯不允許，也絕不會讓他的生活有另一種可能性。\n當許多年過去，龐托斯在月色中穿行過無數個黑夜，尋覓著那個應當回到厄波揚斯的身影的時候，他是這麼想的。\n哦，那個徒勞的，保護性的法術離開他了，龐托斯現在可以把他帶回來。\n只是龐托斯還不知道，「羅盤會把人們引領到祂該去的地方」，如同每條船都有自己的航線，不同的人總是會選擇不同的方向。"
  },
  Item_141203_Desc = {
    Text = "別管魚為什麼會在陸地上跑，這裡是厄波揚斯。\n\n至少掉落{s1}個"
  },
  Item_141203_Name = {
    Text = "新鮮的「獵物」"
  },
  Item_141204_Desc = {
    Text = "眾所週知，深淵裡的魚會隨便亂長，過於碩大是正常的，與人類相似……也是正常的。\n\n至少掉落{s1}個"
  },
  Item_141204_Name = {
    Text = "碩大的「獵物」"
  },
  Item_141205_Desc = {
    Text = "能夠增幅持有者造成的力量降低效果，並能夠在特定時機增幅隊伍暴擊傷害的命輪。造成擊殺後還可提高自身回合結束獲得的狂氣。"
  },
  Item_141205_Name = {Text = "活囚籠"},
  Item_141205_StoryDesc = {
    Text = "如果願望真的能實現，龐托斯希望離別在來臨之前，能夠打個招呼。\n他的父母消失得悄無聲息，一個平靜的午後，姐姐蕾莎付錢雇來了一輛人力車，然後是長長的、他當時還不認識的鐵皮怪物，在柴油味和轟隆聲中，他抵達了那座海邊小鎮。\n關於父母的去向，蕾莎沒有透露一個字，劇烈的爭吵後，他衝進了瀰漫著鹹腥味的港口。\n眼距過寬的海民們正在販售形狀怪異，來自人力所不可能到達的深淵的魚類。\n「喂，離遠一點，這些魚說不定和抓來它的那些東西一樣染上了詛咒。」\n路人壓低聲音，沒有人想看著這個初來乍到的漂亮青年蹚渾水。\n他習慣性地衝對方笑了笑，目光卻不自覺地落在那支晦暗腐敗的擬餌上，它大張的口腔遍布利齒，醜陋、扭曲、張揚，某個臆想中的聲音講述著這死物的一生。\n在幽暗的、無光的海底，它引誘、掠奪、無所不用其極，它的身體是一座牢固的囚籠，鎖困著它的子嗣、愛人、仇人、和獵物。\n它生命中美好的東西本該轉瞬即逝，但它把祂們全都留住了，祂們以它的身體為載體，緊密相依，永不分離。\n龐托斯猛地甩了甩頭，驚恐地在耳邊尖銳的鼓噪聲中環顧四周。\n聲音如潮水般消失了，他把一切當成一次恍神，在心裡嘲笑自己的神經質。\n然後毫無察覺地向既定的命運裡墜去。"
  },
  Item_141206_Desc = {
    Text = "別管魚為什麼會在陸地上跑，這裡是厄波揚斯。\n\n至少掉落{s1}個"
