    Text = "閉上眼睛，捂住耳朵，跟我一起默念，這是魚，這是魚。\n沒錯，只要在獵場裡的，都是魚。\n\n至少掉落{s1}個"
  },
  Item_141226_Name = {
    Text = "古老的「獵物」"
  },
  Item_141227_Desc = {
    Text = "閉上眼睛，捂住耳朵，跟我一起默念，這是魚，這是魚。\n沒錯，只要在獵場裡的，都是魚。\n\n至少掉落{s1}個"
  },
  Item_141227_Name = {
    Text = "古老的「獵物」"
  },
  Item_141228_Desc = {
    Text = "眾所週知，深淵裡的魚會隨便亂長，過於碩大是正常的，與人類相似……也是正常的。\n\n至少掉落{s1}個"
  },
  Item_141228_Name = {
    Text = "碩大的「獵物」"
  },
  Item_141229_Desc = {
    Text = "那是古老意志的失落靈識。 彌薩格通過神秘的儀式啟發喚醒體的靈識，受到啟發的喚醒體將永久增強精神能力。\n重複獲得龐托斯時轉換獲得，用於激活龐托斯的啟靈。"
  },
  Item_141229_Name = {
    Text = "殘片·龐托斯"
  },
  Item_141229_StoryDesc = {
    Text = "重複獲得龐托斯時轉換獲得，用於激活龐托斯的啟靈。"
  },
  Item_141230_Desc = {
    Text = "別管魚為什麼會在陸地上跑，這裡是厄波揚斯。"
  },
  Item_141230_Name = {
    Text = "新鮮的「獵物」"
  },
  Item_141231_Desc = {
    Text = "眾所週知，深淵裡的魚會隨便亂長，過於碩大是正常的，與人類相似……也是正常的。\n\n至少掉落{s1}個"
