  },
  Item_141233_Desc = {
    Text = "閉上眼睛，捂住耳朵，跟我一起默念，這是魚，這是魚。\n沒錯，只要在獵場裡的，都是魚。\n\n至少掉落{s1}個"
  },
  Item_141233_Name = {
    Text = "古老的「獵物」"
  },
  Item_141508_Desc = {
    Text = "讓裝備者陷入沉睡，醒來後強化狂氣爆發的戰術型命輪。"
  },
  Item_141508_Name = {
    Text = "夢遊仙境"
  },
  Item_141508_StoryDesc = {
    Text = "傳說中只要孩子在森林裡追著一隻野兔奔跑，就有機率掉進通往異世界的樹洞。\n莉莉光滑的小腳踩上鵝卵石的小徑。\n「莉莉喜歡這裡……地面上不會有玻璃碎渣，空氣中也沒有消毒水的氣味。」\n莉莉深吸了一口清新的空氣，掠過林間的風卷來奇異花香的氣息。\n頭頂的樹冠交織成彩色玻璃般的穹頂，碎落的陽光像是滿地跳動的寶石，瑰麗而迷幻的景致讓莉莉幾乎不知道應該往哪個方向看。\n「啊，剛才的兔子先生！」\n草叢中冒出一雙熟悉的灰色長耳朵，莉莉急忙追了過去。\n腳下的苔蘚每踩一步就綻開一朵細小的銀花，但莉莉也無暇顧及。她還有更重要的話要找兔子先生說。\n淌過流著蜂蜜色光芒的小溪，穿過會唱歌的蘆葦叢。\n氣喘吁吁的莉莉終於捉住了兔子先生絨球一樣的尾巴。\n「兔子先生，你願意和麗莎做朋友嗎？」\n「麗莎是我的朋友，可是其他人現在都很害怕她……如果是兔子先生的話，一定能和她成為朋友的！」\n兔子先生回頭的瞬間，漫天螢火升騰而起。\n「當然，@2是所有人的朋友。不過，現在，你該休息了。」\n於是，莉莉抱著已經成為朋友的兔子先生，爬到森林深處那棵高大的巨樹下。\n在飄散的螢火蟲溫暖的包圍中，莉莉倚著巨樹的根系，安靜地睡著了。\n「受試者：莉莉。臨床表徵：呼吸平穩，眼球轉速正常。第359次意識干涉實驗，成功。」\n那是如夢幻一般綺麗的奇幻世界。"
  },
  Item_141529_Desc = {
    Text = "解鎖後，完成「秘境遊記」全部任務可額外獲得以下獎勵"
  },
  Item_141529_Name = {
    Text = "秘境遊記"
  },
