  },
  Item_144346_Name = {
    Text = "以銀鑰之名：太歲"
  },
  Item_144346_StoryDesc = {
    Text = "太歲玩法活動"
  },
  Item_144378_Desc = {
    Text = "對敵我雙方造成混亂，並能延遲獲得大量狂氣收益的綜合型命輪。"
  },
  Item_144378_Name = {
    Text = "向上墜落"
  },
  Item_144378_StoryDesc = {
    Text = "漫長的駐守時光中，塔薇也曾踏入過一片土地。\n她悉心觀察每一個生物的行動，不露聲色地行走於人間的邊緣。\n\n某個平凡的日子，入夜時分，城郊的密集燈火吸引了她的目光。\n布景，歌舞，售賣點心的攤販，嬉笑打鬧的孩童，舉杯痛飲的閒人。那是生命的喘息，瞬間的閒暇。\n景象太過令人嚮往，她忍不住現出身形。\n\n「您好，請給我一支糖畫。」\n「好嘞，您稍等。想畫點什麼？」\n塔薇輕輕側頭。她只記得需要提供那些她偶然拾獲的無主貨幣，卻全然忘記了自己可以表露的期許。\n「如果您沒想好的話，不如我按照您的形象畫一支如何？您看起來就像仙女一樣美麗。」\n塔薇微笑著點頭，攤主吆喝一聲，舉起糖勺，開始落筆。\n\n嘀嗒。嘀嗒。\n落入石板的，卻不是蜜色的糖漿。\n而是雨，黑色的雨。\n黑色的黏液從目不可視的高空中滴落，將天空熔開一個觸目驚心的裂口。\n\n\n然後，塔薇開始向上墜落。\n那是世界在下沉。攤主的笑意在塔薇的記憶裡凝固成靜止的一幀，然後和萬物一起湮沒在黑色的汪洋裡，化為無數已逝星辰中微不足道的一顆，化為對她而言遙不可及的過往。\n這是她引發的震盪，也是她應當承受的懲戒。\n她遙望著，靜默不言。她只是向上墜落。\n這才是她應守的位置，那扇「超越時空」的銀扉。\n她將在此永恆俯瞰。"
  },
  Item_144379_Desc = {
    Text = "解鎖後，完成「窺引萬象」全部任務可額外獲得以下獎勵"
  },
  Item_144379_Name = {
    Text = "窺引萬象"
  },
  Item_144520_Name = {
    Text = "典藏郵票：阿格里帕"
  },
  Item_144521_Desc = {
    Text = "在「學期課題」中購買「核心課題」後可獲得。\n「彌薩格內部發行的限量郵票，請勿轉讓，請勿遺失，這是為了你的人身安全考量。」"
  },
  Item_144521_Name = {
    Text = "典藏郵票：希洛"
  },
  Item_144521_StoryDesc = {
    Text = "第36期學期課題"
  },
  Item_144522_Name = {
    Text = "典藏郵票：雷婭"
  },
  Item_144523_Name = {
    Text = "典藏郵票：尤烏哈希"
  },
  Item_144524_Name = {
    Text = "典藏郵票：菲茵特"
  },
  Item_144525_Name = {
    Text = "典藏郵票：血鏈·希洛"
  },
  Item_145273_Desc = {
    Text = "利維坦將為你的野心與冷血感到愉悅，親愛的參賽者。\n\n至少掉落1620個"
  },
  Item_145274_Desc = {
    Text = "利維坦將為你的野心與冷血感到愉悅，親愛的參賽者。\n\n至少掉落1848個"
  },
  Item_145275_Desc = {
    Text = "利維坦將為你的野心與冷血感到愉悅，親愛的參賽者。\n\n至少掉落1440個"
  },
  Item_145276_Desc = {
    Text = "利維坦將為你的野心與冷血感到愉悅，親愛的參賽者。"
  },
  Item_145277_Desc = {
    Text = "屬性為黑印掉落的命輪。"
  },
  Item_145277_Name = {
    Text = "不滅的飢骨"
  },
  Item_145277_StoryDesc = {
    Text = "在蘿坦此生最為痛苦與滿足的那天，她手中的利刃如風暴襲向眼前的神明。巨劍與利維坦如星球般宏偉的身軀一同，在這風暴中寸寸碎裂。\n將鮮血的王冠贈予那位騎士團的奴隸後，作為交換，蘿坦只提了一個要求：她需要一把新的武器。\n懷著對蘿坦的畏懼與崇敬，新國王命人取下利維坦的骨頭，為她鑄造了一對無與倫比的巨劍。在六國最優秀的鐵匠們日以繼夜的鑄造淬煉中，一頭死去神明的屍骨，在弒神者的手中重獲新生。\n一位值得被銘記的對手曾見證過這雙不滅的劍刃。他的巨錘劈碎了蘿坦的鎧甲與巨劍，裂紋如蛛網般在劍身蔓延，乳白的碎片飛濺在血色的空氣裡，如同她刺向利維坦的那天。他以為自己找到了破綻。然後，他看到蘿坦重新在他面前站起，那柄本應碎裂的巨劍刺穿他的胸膛，吮吸他的血肉。新的骨骼從碎裂處湧出，比先前更加尖銳，更加緻密。斷面拔節生長，如同荒野中瘋長的荊棘。他清晰地感知到，自己的生命正被那白骨鑄就的利刃咀嚼、吞嚥。\n原來，那曾經吞噬星天的巨獸從未死去。自契約簽訂的那一刻，祂便與她融合為一。每當蘿坦提起巨劍，劍身的骨棘便開始綻放，用它銳利的尖刺向對手發出殘忍的歡呼。\n它是她的武器。她是它的雙足。她與它，從始至終都陷於同一種渴望。她們不死不滅，永無饜足。\n從不停息的戰場，是她們唯一的歸宿。"
  },
  Item_145278_Desc = {
    Text = "利維坦將為你的野心與冷血感到愉悅，親愛的參賽者。\n\n至少掉落1512個"
