  Item_145970_Desc = {
    Text = "記錄此鑰令後，可在編隊時選擇鑰令技能：「並非謊言之物」。\n\n惡貫滿盈的毒蛇曾用它蠱惑伊甸園內純真無知的人類，滿腹嫉妒的王后曾用它誘騙雪白無辜的公主，徒有智慧的凡人也曾憑藉它贏下荒野獵手的賽跑。\n但此物並非謊言。\n它只是人心底裡那一點不能宣之於口的欲望。"
  },
  Item_145970_Name = {
    Text = "並非謊言之物"
  },
  Item_145970_StoryDesc = {
    Text = "惡貫滿盈的毒蛇曾用它蠱惑伊甸園內純真無知的人類，滿腹嫉妒的王后曾用它誘騙雪白無辜的公主，徒有智慧的凡人也曾憑藉它贏下荒野獵手的賽跑。\n但此物並非謊言。\n它只是人心底裡那一點不能宣之於口的欲望。"
  },
  Item_146353_Desc = {
    Text = "逸散在新月雪峰的情緒粒子，觸碰時彷彿能聽見詭計得逞的嬉笑聲。\n用於提升守密人在調查事件「山宴」中的共鳴。"
  },
  Item_146353_Name = {
    Text = "賜福之心"
  },
  Item_146538_Desc = {
    Text = "解鎖後，完成「終北紀行」全部任務可額外獲得以下獎勵"
  },
  Item_146538_Name = {
    Text = "終北紀行"
  },
  Item_146539_Desc = {
    Text = "後勤部向完成「調查行動」的守密人發放了特別許可，在每次完成調查行動後，守密人都可以為下一次的出發購置一批特別的珍貴銀芯製品。\n數量有限，願銀鑰指引我們。"
  },
  Item_146539_Name = {
    Text = "調查歷程特典·星辰篇Ⅵ"
