  Item_147549_Desc = {
    Text = "記錄此鑰令後，可在編隊時選擇鑰令技能：「臨時文本」。\n\n（待補充鑰令風味文案。）"
  },
  Item_147549_Name = {
    Text = "臨時文本"
  },
  Item_147549_StoryDesc = {
    Text = "（待補充鑰令風味文案。）"
  },
  Item_147580_Name = {
    Text = "卡拉布手冊"
  },
  Item_147581_Name = {Text = "八咫鏡"},
  Item_147598_Name = {
    Text = "圖魯王冠"
  },
  Item_148117_Desc = {
    Text = "打出可以獲得算力，留在手中積攢生命回覆和狂氣資源，並提供一次復活的綜合型命輪。"
  },
  Item_148117_Name = {
    Text = "魂靈同調"
  },
  Item_148117_StoryDesc = {
    Text = "空曠的實驗室內，各類精密的儀器均規整地擺放著，只有無數管線交錯，如同蜿蜒纏繞的蛇，伏在地面，吊在空中。\n思維的信號宛如一條無人可見的河流，但天才早已習慣於與之打交道。大腦是它們的源頭，再淌過機械的管線，最終匯聚在這具新造的軀殼中。\n意識被傳遞的同時，許多塵封的記憶也被久違地翻出，家人、彌薩格、未完成的實驗……恍惚間，天才想起許多年前，在她還未脫離最初的肉身桎梏時，曾有個無聊的學生，饒有興趣地圍著她轉來轉去，眼裡閃爍著名為好奇心的光芒。\n「您認為，人造的軀體能承載真正的魂靈嗎？」\n凡人總愛幻想一些遠超他們視野的事物，這是個庸俗的問題。但身為教師，她仍給出了幾句回應，縱然沒抬一下眼。\n「你的身體未嘗不是人造之物，心臟、四肢、五感這些器官的運行又和機械有何區別？」\n「好了，比起胡思亂想這些，不妨抽出時間，好好鍛鍊下你那生鏽的大腦，否則，你這具流通著血液的肉體只會更無用。」\n如今，發問之人早已被時間的砂礫掩埋，不復存在。唯有承載智慧的腦缸仍在思考，並永遠思考。\n世人口中所謂的魂靈不過是860億個神經元交錯而成的電化學活動，血肉也好，機械也罷，原材料的相異不會改變它們只是載體的本質。\n是啊，凡人無能為力，但身為天才的她能夠做到，且已經做到——唯有如此，才能解明世界的真理，抵達知識的頂端。\n視覺，不過是光線穿過眼球，最終於視網膜上聚焦成像。\n嗅覺，不過是氣味分子與受體結合，劃過神經的化學感知路徑。\n聽覺，不過是聲波經耳蝸換能，轉化為上傳至皮層的電信號。\n人偶身處之地太過昏暗，微弱的燈光搖曳，連影子也無法被映照。她雙目微閉，因為清楚哪怕睜開它們，映入眼簾的也不過是一成不變的畫面。\n房間被打掃得一塵不染，瓶罐中的藥液也被緊緊封存。機體不需要呼吸，更沒必要為了測試感官而去攝取這無味的空氣。\n唯有一聲冰冷的機械提示音，迴蕩在空曠的實驗室中：\n「意識同調完成，機體啟動確認。」\n足夠了。\n雖是無機質的聲音，但聽起來倒親切，彷彿錨定了物質世界的真實，又像隻是在單純提醒她，短暫的休憩結束，是時候投身於新一輪的研究中了。"
  },
  Item_148118_Desc = {
    Text = "解鎖後，完成「課餘時間」全部任務可額外獲得以下獎勵"
  },
  Item_148118_Name = {
    Text = "課餘時間"
  },
  Item_148403_Desc = {
    Text = "這是你與喚醒體「彼此為我」的證明。\n喚醒體同調率達到 Lv20級時獲得，將自動裝配展示於該喚醒體卡面。"
  },
  Item_148403_Name = {Text = "曜閃"},
  Item_148404_Desc = {
    Text = "同心的終極之證。你們眼中的彼此已非「他者」，彼此之間，只剩下兩種形體，以及同一個靈魂。"
  },
  Item_148404_Name = {
    Text = "同心之證"
  },
  Item_148479_Name = {
    Text = "阿拉克捏紡線"
  },
  Item_148480_Name = {Text = "金蘋果"},
  Item_148481_Name = {Text = "舊銀鑰"},
  Item_148483_Name = {Text = "金幣包"},
  Item_20469_Name = {
    Text = "孟菲斯儀式鏡"
  },
  Item_20470_Name = {
    Text = "日月輪盤"
  },
  Item_20481_Desc = {
    Text = "撲通，撲通。\n散落在無光之境中的小小心臟，是「祂們」最愛的食物。\n用以交換命輪和無垢之芯等物資。"
  },
  Item_20481_Name = {
    Text = "黑色貢物"
  },
  Item_20482_Desc = {
    Text = "金閃閃的徽章，上面篆刻象徵雷歐王國的薔薇。在地下市場能賣個不錯的好價錢。\n用以表彰在調查行動中取得優異成績的守密人，用以在交換商店中兌換物資。"
  },
  Item_20482_Name = {
    Text = "調查徽章"
  },
  Item_21764_Name = {
    Text = "雕塑習作"
  },
  Item_21775_Desc = {
    Text = "它們的肉體、靈識和記憶都被封裝於此，直到被喚醒的那一刻。\n可從中選擇1個「界域研習」中的以下喚醒體喚醒：\n諾締拉、寧菲亞、潘狄婭、艾爾瓦、珈倫；戈利亞、法洛思、凱刻斯、珊、希萊斯特；希洛、阿格里帕、尤烏哈希、雷婭、菲茵特；莉茲、汀克特、溫柯爾、詹金、卡茜亞。"
  },
  Item_21775_Name = {
    Text = "原質樂園"
  },
  Item_21799_Desc = {
    Text = "請提供交易帳戶及密碼。\n流通於王國地下市場的交易憑證，守密人可據此購入所需的稀有物資。"
  },
  Item_21799_Name = {
    Text = "密銀交易憑證"
  },
  Item_21898_Desc = {
    Text = "記載了珍稀命輪的神秘古籍。\n可從中選擇1個「輪轉之相」中的以下SSR命輪獲得：\n記憶螺旋、腐朽贈禮、欲海浮沉、堅韌意志、無聲歡宴；巨人之刃、於暴雨之中、傷痛之鰭、珊瑚女之死、引舵之帆；掙脫鎖鏈之日、蒼白後裔、血肉狂宴、饕餮寓言、吞噬搖籃曲；旋轉，旋轉、被縛的歌謠、無法完成的演算、迷失的道路、快樂魔法秀。"
  },
  Item_21898_Name = {
    Text = "輪轉之書"
  },
  Item_22164_Desc = {
    Text = "請遵照說明書使用，切勿過量。\n存放靈知製劑的補給箱，為執行任務的守密人提供援助。"
  },
  Item_22164_Name = {
    Text = "調查補給"
  },
  Item_22165_Desc = {
    Text = "沒有什麼是一支靈知製劑無法解決的。如果有，那就再來幾支。\n存放靈知製劑的補給箱，為執行任務的守密人提供援助。"
  },
  Item_22165_Name = {
    Text = "每週製劑禮盒"
  },
  Item_22166_Desc = {
    Text = "每週都能獲取的小小助力。\n存放特批藥劑的補給箱，為執行任務的守密人提供援助。"
  },
  Item_22166_Name = {
