  Item_22244_Desc = {
    Text = "繁衍吧，繁衍吧。讓流淌著母樹鮮血的靈魂遍及世界。\n隨機掉落再衍化密契套裝部件。"
  },
  Item_22717_Desc = {
    Text = "在「幻夢深潛」和「相位對弈」獲得的守密人經驗翻倍！（每日 240 上限不變）。"
