  Item_24073_Desc = {
    Text = "訶勒特代理院長特批的豐厚補給。\n封裝著珍稀材料的木盒，為執行密境課室的日常試訓與週常試訓任務的守密人提供援助。\n從以下素材中選擇一種：\n閃耀晶蝶*9\n高莖海百合*9\n原生蟲蛹*9\n隕星碎塊*9"
