  },
  Item_25126_Name = {Text = "雷婭"},
  Item_25136_Desc = {
    Text = "封裝著珍稀材料的禮袋，為執行密境課室的日常試訓與週常試訓任務的守密人提供額外援助。\n課題等級達到50級後，每提升1級即可獲得1份。\n領取時隨機獲得以下其中一個物品：\n「特批藥劑」×1(20%機率)\n「薔薇金券」×5000(80%機率)"
  },
  Item_25136_Name = {
    Text = "進階課題禮袋"
  },
  Item_25141_Desc = {
    Text = "在「學期課題」中購買「核心課題」後可獲得。\n「彌薩格學生間流傳著這樣一句話：只要有他在，就沒有人會受傷。」"
  },
  Item_25141_Name = {
    Text = "以銀鑰之名：奧吉爾"
  },
  Item_25141_StoryDesc = {
    Text = "第2期學期課題"
  },
  Item_25142_Desc = {
    Text = "在「學期課題」中購買「核心課題」後可獲得。\n「無論是奔赴卡達斯星球的背面，還是深入裂隙中心，她都相信你的判斷。」"
  },
  Item_25142_Name = {
    Text = "以銀鑰之名：拉蒙娜"
  },
  Item_25142_StoryDesc = {
    Text = "第2期學期課題"
  },
  Item_25192_Name = {Text = "校貓"},
  Item_25218_Desc = {
    Text = "它將改寫世界的規則。不可直視，不可接觸。\n產自彌薩格地底黑池的神秘靈核，能幫助喚醒體提升至難以想像的高度，喚醒體達到60級後可使用。"
  },
  Item_25218_Name = {
    Text = "原初靈核"
  },
  Item_25219_Desc = {
    Text = "它們散落在黑池中，渴望著神聖完整的偉大時刻。\n產自彌薩格地底的神秘碎片，能合成原初靈核。"
  },
  Item_25219_Name = {
    Text = "靈核碎片"
  },
  Item_34698_Desc = {
    Text = "裝飾華麗的木匣，內含初階升格材料。\n後勤處精心準備、悉心搭配的套裝，適合那些在短時間內需要一定資源的調查員和守密人。"
  },
  Item_34698_Name = {
    Text = "初階升格匣子"
  },
  Item_34699_Desc = {
    Text = "可以窺見命運碎片的螺旋視窗。用於兌換命輪。\n黃金、稀土、銀芯……與期望的命運相比，再昂貴的材料也變得微不足道。\n使用時可從中選擇1個「輪轉之相」、往期命輪活動喚醒和當期命輪活動喚醒中的SSR命輪。"
  },
  Item_34700_Desc = {
    Text = "裝飾華麗的木匣，內含中階升格材料。\n後勤處精心準備、悉心搭配的套裝，適合那些在短時間內需要一定資源的調查員和守密人。"
  },
  Item_34700_Name = {
    Text = "中階升格匣子"
  },
  Item_34701_Desc = {
    Text = "有著精緻繡花的束口袋，內含高階補給。\n拿好，它可能有點重。謹記：千萬不要讓它受到撞擊，包括掉到地上。"
  },
  Item_34701_Name = {
    Text = "高階技能補給"
  },
  Item_34702_Desc = {
    Text = "裝飾華麗的木匣，內含高階升格材料。\n後勤處精心準備、悉心搭配的套裝，適合那些在短時間內需要一定資源的調查員和守密人。"
  },
  Item_34702_Name = {
    Text = "高階升格匣子"
  },
  Item_34703_Desc = {
    Text = "由奇異的材質製成的特殊裝置，用於進行喚醒體與命輪的「回溯」。\n它將洗去靈魂的印記，抹除精神的瘡疤，它將歸還一切於原點，喚回最初的靈知。\n可以為喚醒體或常駐命輪開啟「回溯」功能。"
  },
  Item_34703_Name = {
    Text = "時間原點"
  },
  Item_34704_Desc = {
    Text = "有著精緻繡花的束口袋，內含初階補給。 小心，裡面的東西可能還保有活性。"
  },
  Item_34704_Name = {
    Text = "初階技能補給"
  },
  Item_34705_Desc = {
    Text = "有著精緻繡花的束口袋，內含中階補給。\n如果你發現你的袋子在無人的情況下悄悄蠕動，請儘快交還至後勤處。"
  },
  Item_34705_Name = {
    Text = "中階技能補給"
  },
  Item_34706_Desc = {
    Text = "與靈魂共鳴之物。用於喚醒特定喚醒體。\n或許是它的形狀，或許是它的材質本身——這個冰冷之物能夠穿透帷幕，將沉睡的精神拉入現實之中。\n使用時可從中選擇1個「界域研習」、往期角色活動喚醒和當期角色活動喚醒中的喚醒體。"
  },
  Item_34706_Name = {
    Text = "靈魂回溯之芯"
  },
  Item_34723_Desc = {
    Text = "在「故事的魔法」活動中通關「劇本迷思」或完成活動成就後獲得，用於在「魔法劇本商店」中進行交換的道具。\n靈感轉瞬即逝，如夜空中飛馳而過的流星。不同的是，你擁有將它永遠留下的方法。"
  },
  Item_34723_Name = {
    Text = "飄零的靈感"
  },
  Item_34724_Desc = {
    Text = "逸散在臨時片場中的情緒粒子，觸碰時彷彿聽見了孩子們愜意的笑。\n用於提升守密人在活動玩法「劇本迷思」和特遣紀錄「故事的魔法」中的共鳴。\n可在限時活動「故事的魔法」中完成成就獎勵獲取。"
  },
  Item_34724_Name = {
    Text = "演繹之心"
  },
  Item_34832_Desc = {
    Text = "在活動「故事的魔法」中完成成就獲得。\n「彌薩格喚醒體管理處提示：不要給莉莉喂太多東西吃！！就算是守密人也不准再投餵她了！」"
  },
  Item_34832_Name = {
    Text = "以銀鑰之名：莉莉"
  },
  Item_34832_StoryDesc = {
    Text = "莉莉玩法活動"
  },
  Item_34858_Desc = {
    Text = "屬性為死亡抵抗的命輪。"
  },
  Item_34858_StoryDesc = {
    Text = "故事中存有魔法，弗朗西斯曾這麼告訴莉莉。\n那時她會捧著故事書坐在窗邊，初夏的陽光將白大褂烤得微微發燙，散發出溫暖柔和的馨香。\n她語調輕緩，娓娓道來，但昨夜長時間精神專注於手術積累了太多疲勞，故事尚未抵達終點，弗朗西斯便沉沉睡去。\n莉莉從未因此責怪母親，因為母親倚靠窗沿的疲憊睡顏如此令人安心。\n\n如今膠片代替書本承載了故事與魔法，正如新的膠片取代因孩子們的不慎而曝光破損的膠片，正如新夥伴們的嬉鬧取代了過往溫暖和疼痛交雜的小憩時光。\n但那些被埋藏的回憶依然如曝光的膠片般，沉睡在某個不為人知的角落，縱使永不見天日，依然熠熠生輝。"
  },
  Item_34908_Desc = {
    Text = "芽孢又做錯了什麼呢，它們只是想有個家罷了。\n蟲蛹和它的芽孢鄰居。用於提升血肉界域喚醒體的技能等級。"
  },
  Item_34909_Desc = {
    Text = "他們相約一起殺戮，在海百合盛開的春天。\n尤因他海百合的化石。用於提升深海界域喚醒體的技能等級。"
  },
  Item_34910_Desc = {
    Text = "在某些平行宇宙裡，它擁有毀天滅地的力量。\n來自遙遠熱帶的完美礦晶，用於提升超維界域喚醒體的技能等級。"
  },
  Item_34911_Desc = {
    Text = "扇動的翅膀有助於產生龍捲風，或是花粉過敏。\n成群的水晶蝴蝶。用於提升混沌界域喚醒體的技能等級。"
  },
  Item_34911_Name = {
    Text = "混沌結晶"
  },
  Item_35140_Desc = {
    Text = "用於在「魔法劇本商店」中進行交換的道具。\n靈感轉瞬即逝，如夜空中飛馳而過的流星。不同的是，你擁有將它永遠留下的方法。\n至少掉落：\n飄零的靈感* {s1}\n有較低機率獲得額外的飄零的靈感。"
  },
  Item_35140_Name = {
    Text = "飄零的靈感"
  },
  Item_35141_Desc = {
    Text = "用於在「魔法劇本商店」中進行交換的道具。\n靈感轉瞬即逝，如夜空中飛馳而過的流星。不同的是，你擁有將它永遠留下的方法。\n至少掉落：\n飄零的靈感* {s1}\n有較低機率獲得額外的飄零的靈感。"
  },
  Item_35141_Name = {
    Text = "飄零的靈感"
  },
  Item_35142_Desc = {
    Text = "用於在「魔法劇本商店」中進行交換的道具。\n靈感轉瞬即逝，如夜空中飛馳而過的流星。不同的是，你擁有將它永遠留下的方法。\n至少掉落：\n飄零的靈感* {s1}\n有較低機率獲得額外的飄零的靈感。"
  },
  Item_35142_Name = {
    Text = "飄零的靈感"
  },
  Item_35143_Desc = {
