  Item_35711_Desc = {
    Text = "一次能親自決定前進方向的機會。\n限量特供的輪轉之書，希望能為執行任務的守密人保駕護航。"
  },
  Item_35711_Name = {
    Text = "特供輪轉之書"
  },
  Item_35712_Desc = {
    Text = "沒有人能百分之百保證，其中封裝的靈識都是自願被喚醒的。\n限量特供的原質樂園，希望能為執行任務的守密人保駕護航。"
  },
  Item_35712_Name = {
    Text = "特供原質樂園"
  },
  Item_35816_Desc = {
    Text = "在「學期課題」中購買「核心課題」後可獲得。\n「當前課題：如何提高守密人外勤任務安全係數。\n課題難度：☆☆☆☆☆」"
  },
  Item_35816_Name = {
    Text = "以銀鑰之名：朵爾"
  },
  Item_35816_StoryDesc = {
    Text = "第3期學期課題"
  },
  Item_35817_Desc = {
    Text = "在「學期課題」中購買「核心課題」後可獲得。\n「無趣！我要戰到血流成河！」"
  },
  Item_35817_Name = {
    Text = "以銀鑰之名：蘿坦"
  },
  Item_35817_StoryDesc = {
    Text = "第6期學期課題"
  },
  Item_36018_Desc = {
    Text = "在活動「群星正位」中完成成就獲得。\n「草莓果醬司康的惡魔，布朗尼公主，彌薩格食堂推車小蛋糕新的毀滅者——已經降臨於此！」"
  },
  Item_36018_Name = {
    Text = "以銀鑰之名：墨菲"
  },
  Item_36018_StoryDesc = {
    Text = "墨菲玩法活動"
  },
  Item_36782_Desc = {
    Text = "請提供交易帳戶及密碼。\n流通於王國地下市場的交易憑證，守密人可據此購入所需的稀有物資。"
  },
  Item_36782_Name = {
    Text = "密銀交易憑證"
  },
  Item_36801_Desc = {
    Text = "記錄此鑰令後，可在編隊時選擇鑰令技能：「奧瑞塔的寶藏」。\n\n玻璃缸。水族箱。宮殿。\n\n稱呼它為什麼都好，那都是奧瑞塔的朋友們棲居的、沒有融蝕和痛苦的小小樂園。"
  },
  Item_36801_Name = {
    Text = "奧瑞塔的寶藏"
  },
  Item_36801_StoryDesc = {
    Text = "玻璃缸。水族箱。宮殿。\n\n稱呼它為什麼都好，那都是奧瑞塔的朋友們棲居的、沒有融蝕和痛苦的小小樂園。"
  },
  Item_36813_Desc = {
    Text = "記錄此鑰令後，可在編隊時選擇鑰令技能：「咆哮的血與沙」。\n\n霞光如血，飛沙揚塵。\n\n無垠沙丘之上，天生的戰士毫不猶豫地咬開自己的手腕，將他的血還於天空和大地。"
  },
  Item_36813_Name = {
    Text = "咆哮的血與沙"
  },
  Item_36813_StoryDesc = {
    Text = "霞光如血，飛沙揚塵。\n\n無垠沙丘之上，天生的戰士毫不猶豫地咬開自己的手腕，將他的血還於天空和大地。"
  },
  Item_36814_Desc = {
    Text = "記錄此鑰令後，可在編隊時選擇鑰令技能：「最後的誓言」。\n\n騎士曾立誓，他會以這支槍守衛重要之人。此刻它貫穿了主人的胸膛，卻隻為將危險隔絕於外——這是騎士踐行的最後的誓言。"
  },
  Item_36814_Name = {
    Text = "最後的誓言"
  },
  Item_36814_StoryDesc = {
    Text = "騎士曾立誓，他會以這支槍守衛重要之人。此刻它貫穿了主人的胸膛，卻隻為將危險隔絕於外——這是騎士踐行的最後的誓言。"
  },
  Item_36815_Desc = {
    Text = "記錄此鑰令後，可在編隊時選擇鑰令技能：「短暫的永恆」。\n\n機械的人偶拒絕了新生之靈許諾的永恆，核心的電流灼燒她的靈魂。在無力支撐軀體之前，她還有最後一件必須完成的事情——"
  },
  Item_36815_Name = {
    Text = "短暫的永恆"
  },
  Item_36815_StoryDesc = {
    Text = "機械的人偶拒絕了新生之靈許諾的永恆，核心的電流灼燒她的靈魂。在無力支撐軀體之前，她還有最後一件必須完成的事情——"
  },
  Item_36847_Desc = {
    Text = "記錄此鑰令後，可在編隊時選擇鑰令技能：「蝕骨的擁抱」。\n\n血肉消溶於深海，骨骼硬化為珊瑚，她的目光熾熱，所擁抱之物是你，所雕刻之物亦是你。\n\n她答應你，要帶你一起回家。"
  },
  Item_36847_Name = {
    Text = "蝕骨的擁抱"
  },
  Item_36847_StoryDesc = {
    Text = "血肉消溶於深海，骨骼硬化為珊瑚，她的目光熾熱，所擁抱之物是你，所雕刻之物亦是你。\n\n她答應你，要帶你一起回家。"
  },
  Item_36848_Desc = {
    Text = "記錄此鑰令後，可在編隊時選擇鑰令技能：「湖畔回眸」。\n\n坎布裡安河谷的湖水波光粼粼，清澈見底。\n\n迷宮中的喧囂忽而遠去，享受此刻寧靜的只有你和重獲自由的少女。"
  },
  Item_36848_StoryDesc = {
    Text = "坎布裡安河谷的湖水波光粼粼，清澈見底。\n\n迷宮中的喧囂忽而遠去，享受此刻寧靜的只有你和重獲自由的少女。"
  },
  Item_36849_Desc = {
    Text = "記錄此鑰令後，可在編隊時選擇鑰令技能：「跨越回溯之扉」。\n\n少女已經數不清她經歷的輪回，記不明她改變的歷史。\n\n這是最後的機會，最後回溯，她的劍貫穿了塔薇的靈核，卻只來得及握著那個人的手，一同淪入黑池。"
  },
  Item_36849_StoryDesc = {
    Text = "少女已經數不清她經歷的輪回，記不明她改變的歷史。\n\n這是最後的機會，最後回溯，她的劍貫穿了塔薇的靈核，卻只來得及握著那個人的手，一同淪入黑池。"
  },
  Item_36850_Desc = {
    Text = "記錄此鑰令後，可在編隊時選擇鑰令技能：「腐爛盛筵」。\n\n歡宴已極，坎布利安的女王大笑著，遙隔狂歡的人群與飛濺的融蝕漿液向你舉杯致意。"
  },
  Item_36850_Name = {
    Text = "腐爛盛筵"
  },
  Item_36850_StoryDesc = {
    Text = "歡宴已極，坎布利安的女王大笑著，遙隔狂歡的人群與飛濺的融蝕漿液向你舉杯致意。"
  },
  Item_36857_Desc = {
    Text = "記錄此鑰令後，可在編隊時選擇鑰令技能：「神跡降臨」。\n\n治癒的神跡降臨於被瘋狂玷污的聖堂，以甘願獻身者、以無瑕的慈愛者的鮮血為代價。"
  },
  Item_36857_Name = {
    Text = "神跡降臨"
  },
  Item_36857_StoryDesc = {
    Text = "治癒的神跡降臨於被瘋狂玷污的聖堂，以甘願獻身者、以無瑕的慈愛者的鮮血為代價。"
  },
  Item_36858_Desc = {
    Text = "記錄此鑰令後，可在編隊時選擇鑰令技能：「巨人的霸道」。\n\n霸者之道，永不放棄，永不言敗。\n\n即便地平線已經吞噬光明，他也要用巨力扛起不熄的太陽。"
  },
  Item_36858_StoryDesc = {
    Text = "霸者之道，永不放棄，永不言敗。\n\n即便地平線已經吞噬光明，他也要用巨力扛起不熄的太陽。"
  },
  Item_36859_Desc = {
    Text = "記錄此鑰令後，可在編隊時選擇鑰令技能：「全部的她」。\n\n全部的24融為一體，化作星光消散。\n\n她的人格因分割而完整，她的軀體因裂殖而存活。\n\n這世間只有一個24，也是全部的她。"
  },
  Item_36859_StoryDesc = {
    Text = "全部的24融為一體，化作星光消散。\n\n她的人格因分割而完整，她的軀體因裂殖而存活。\n\n這世間只有一個24，也是全部的她。"
  },
  Item_36860_Desc = {
    Text = "記錄此鑰令後，可在編隊時選擇鑰令技能：「玫瑰的勝利」。\n\n雍容的玫瑰斬獲了她的完全勝利。\n\n她回歸了人群中眾星捧月的高貴玫瑰，唯有向你投來的目光宣告著與你在歌劇院經歷的秘密冒險。"
  },
  Item_36860_Name = {
    Text = "玫瑰的勝利"
  },
  Item_36860_StoryDesc = {
    Text = "雍容的玫瑰斬獲了她的完全勝利。\n\n她回歸了人群中眾星捧月的高貴玫瑰，唯有向你投來的目光宣告著與你在歌劇院經歷的秘密冒險。"
  },
  Item_36861_Desc = {
    Text = "記錄此鑰令後，可在編隊時選擇鑰令技能：「灰霧真容」。\n\n微風揚起她的長髮，灰霧之海的倒影在刹那間浮現，然後消弭於無形，在你面前的仍是優雅從容的她。但你知道，那不是你的幻覺。"
  },
  Item_36861_Name = {
    Text = "灰霧真容"
  },
  Item_36861_StoryDesc = {
    Text = "微風揚起她的長髮，灰霧之海的倒影在刹那間浮現，然後消弭於無形，在你面前的仍是優雅從容的她。但你知道，那不是你的幻覺。"
  },
  Item_36862_Desc = {
    Text = "記錄此鑰令後，可在編隊時選擇鑰令技能：「仲夏之夢」。\n\n那是短暫虛幻的一夕幻夢，輕盈而柔軟，未曾留存於膠片，卻流淌於每個拍攝者的記憶之中。"
  },
  Item_36862_Name = {
    Text = "仲夏之夢"
  },
  Item_36862_StoryDesc = {
    Text = "那是短暫虛幻的一夕幻夢，輕盈而柔軟，未曾留存於膠片，卻流淌於每個拍攝者的記憶之中。"
  },
  Item_36863_Desc = {
    Text = "觸摸它，然後投身一場新的冒險；\n擁抱它，然後沉入最荒誕的夢境。\n保存未提純銀芯的新裝置，用於解鎖特遣紀錄和意識潛遊。"
  },
  Item_36863_Name = {
    Text = "現實起點"
  },
  Item_36889_Desc = {
    Text = "逸散在寒武紀的情緒粒子，觸碰時彷彿聞到了紅酒和灰燼燃燒的氣息。\n用於提升守密人在活動玩法「湖中之城」中的共鳴。\n可在限時活動「燃燒的群宴」中完成成就獎勵獲取。"
  },
  Item_36889_Name = {
    Text = "享樂之心"
  },
  Item_38702_Desc = {
    Text = "用於在「暗淡之縛」中進行交換的道具。\n散落在伊薩拉烏風中的巨石殘骸。\n它們靜止不動，莊嚴地為逝去的都城哀悼。"
  },
  Item_38702_Name = {
    Text = "螺旋遺跡"
  },
  Item_38703_Desc = {
    Text = "用於在「遺跡之守」中進行交換的道具。\n 一圈又一圈碳酸鈣組成的夢。為您解開伊薩拉烏之書的秘密。"
  },
  Item_38703_Name = {
    Text = "圓葉菊石"
  },
  Item_38704_Desc = {
    Text = "用於在「脊刺之握」中進行交換的道具。\n脊刺的原材料之一。經由它打磨的脊刺刺入人類胸腔，便可主宰一切。\n意志與情感？不過是生物的脆弱編碼罷了。"
  },
  Item_38704_Name = {
    Text = "原生脛骨"
  },
  Item_39313_Desc = {
    Text = "在活動「燃燒的群宴」中商店兌換獲得。\n「臣服於我，匍匐於我！還是說，你想再嚐嚐脊柱被抽離的甜苦呢？」"
  },
  Item_39313_Name = {
    Text = "以銀鑰之名：旺達"
  },
  Item_39313_StoryDesc = {
    Text = "旺達玩法活動"
