  Item_41379_StoryDesc = {
    Text = "第一任王夫來自伊薩拉烏。\n他長著一對伊薩拉烏人特有的眼珠，淡淡的金色，在遠空漆黑的夜裡閃耀著微弱的光。\n但那光芒隨著伊薩拉烏的陷落而消失，旺達從漆黑的泥沼中撈起最後的載體，珍而重之地仔細收藏。\n她與第二、三任王夫相遇於弗蘭高地。\n那是一對貪婪的領主雙胞胎，旺達曾希望借助他們的力量，重建那失落的湖中之城。\n她受到了欺騙，因此，脊刺深深埋入了他們的骨髓。在麻痺中，旺達取出了那兩對卑賤而無禮的眼睛，而後留下它們，作為自己來過的痕跡。\n第四任王夫，旺達記得他叫「約翰」。\n他是個無趣的啞巴，但伺候得她足夠舒心。更讓她開心的是，「約翰」也有雙淡金色的眼睛，和她的幾乎一模一樣。\n\n「把王夫的眼睛剮出來吧。」\n「謹遵您的希望……但，王夫是做錯了什麼嗎？」\n旺達搖晃著杯中渾濁的水，感受毒素在舌尖徜徉。真是個蠢材，連下毒都做得如此粗劣。\n看著「約翰」爬滿融蝕的身體，她想起了還在遙遠星外時，目送著她離開了故鄉的一雙雙死寂之眸。\n和「約翰」此時的眼睛如出一轍。\n「……就說他，缺少幽默感吧。」"
  },
  Item_43605_Desc = {
    Text = "期間限定的手忙腳亂，為了收納這些無序增殖的凝晶，研究員加了好幾天的班。\n不定期迎來爆發的的擬態凝晶，限量供應，為執行任務的守密人提供援助。"
  },
  Item_43605_Name = {
    Text = "擬態爆發之夜"
  },
  Item_44174_Desc = {
    Text = "逸散在聖堂內的情緒粒子，觸碰時彷彿能聽到誰的禱告與低語。\n用於提升守密人在活動玩法「聖堂之路」和特遣紀錄「血的顏色」中的共鳴。\n可在限時活動「靈魂的牧人」中完成成就獎勵獲取。"
  },
  Item_44174_Name = {
    Text = "懺悔之心"
  },
  Item_44265_Desc = {
    Text = "在活動「靈魂的牧人」中通過「聖堂之路」、「市民的善意」和「成就獎勵」獲取，用於在「義賣現場」中購買商品。\n\n將你的愛心換成義賣券，將你的錢財換成他人的未來。\n互幫互助才是父神期許的道路。"
  },
  Item_44265_Name = {Text = "義賣券"},
  Item_44481_Desc = {
    Text = "在活動「靈魂的牧人」中完成成就獲得。\n「父神能看見每個人靈魂的輝光……當然也包括你的，守密人。」"
  },
  Item_44481_Name = {
    Text = "以銀鑰之名：薩爾瓦多"
  },
  Item_44481_StoryDesc = {
    Text = "薩爾瓦多玩法活動"
  },
  Item_44482_Desc = {
    Text = "在活動「雨鎮幽影」中完成成就獲得。\n「世界上可沒有自動解題機器哦，我可愛的小客人。想要解開謎題的話，為什麼不先問問你身邊的搭檔呢？」"
  },
  Item_44482_Name = {
    Text = "以銀鑰之名：達芙黛爾"
  },
  Item_44482_StoryDesc = {
    Text = "達芙黛爾玩法活動"
  },
  Item_44483_Desc = {
    Text = "在活動「神王復甦」中完成成就獲得。\n「放棄吧，下午四點以後，餘將不會閱讀任何一份奏章——就算是守密人呈上的，也不看。」"
  },
  Item_44483_Name = {
    Text = "以銀鑰之名：圖魯"
  },
  Item_44483_StoryDesc = {
    Text = "圖魯玩法活動"
  },
