  Item_44809_Desc = {
    Text = "外勤期間，可申請每日試訓代理計劃。\n出示代理憑證便可直接領取每日試訓獎勵。\n注意，請勿長期缺席試訓，以免遺忘戰鬥技巧。"
  },
  Item_44809_Name = {
    Text = "代理憑證"
  },
  Item_44832_Desc = {
    Text = "屬性為黑印掉落的命輪。"
  },
  Item_44832_Name = {Text = "鏡中人"},
  Item_44832_StoryDesc = {
    Text = "那位神秘的女士是在葬禮後找上她的。\n「可憐的孩子，」她說，「你本不用受這無妄之災。」\n「你不知道嗎？在他害死米莉後，湯普森找上了他。那個名為愛德華的渣滓本該在去年就死了，但一個人給予了他幫助。」\n「你說為什麼？喔，這我又如何能知道呢。或許，他們本就是蛇鼠一窩，或許……那位罪人自己也不知道自己所做的是罪。他是怎麼說的來著？對，寬恕。對罪人的寬恕，對他們犯下的罪行的寬恕。」\n「他相信人都應該有第二次機會，你怎麼看？我們應當再給愛德華一次機會嗎，在他先後害死米莉，害死你姐姐，你母親之後？」\n「沒錯，這種人不會改，永遠也不會。所以，你知道怎麼做吧？」\n沒錯，這種人不會改，想要終結這種人，這種罪惡，這樣的悲劇，只能……\n將他們的欲望暴露，讓他們醜態盡顯，看他們彼此廝殺、彼此爭鬥，把他們徹底淨化——\n迎來無罪的淨土。"
  },
  Item_44841_Name = {
    Text = "緞帶鈴鐺"
  },
