  Item_45297_Desc = {
    Text = "屬性為暴擊率的命輪。"
  },
  Item_45297_Name = {
    Text = "銀鱈魚的決心"
  },
  Item_45297_StoryDesc = {
    Text = "<Bold:銀鱈魚24>\n每次路過那家炸魚餐廳，我都忍不住想要尖叫。\n為什麼受傷的總是銀鱈魚呢？我們甚至不是真正的鱈魚！\n肉質緊實、味道鮮美難道也是我們的錯嗎？\n\n<Bold:貓咪24>\n吸溜吸溜……喵，喵喵（贊成）！\n\n<Bold:銀鱈魚24>\n在雷歐王國，每分鐘就有一條銀鱈魚死於非命，成為人類的盤中餐。\n是的，就在我們說話的間隙，已經有10只銀鱈魚壯烈犧牲了。\n整整10只！父神在上，你聽到它們的慘叫聲了嗎？\n\n<Bold:貓咪24>\n呃……喵？喵喵喵，喵喵（哪裡）？\n\n<Bold:銀鱈魚24>\n只是個比喻罷了，傻瓜。你雖然蠢了點，卻有一顆金子般的心，能夠戰勝貓的獸慾和短視。\n聽著，接下來我有個計劃，需要你和我一起實施……\n\n——節選自《大約翰炸魚餐廳爆炸事件·案卷綜述：證詞B-03》。由於該時期伯利恆精神病院人滿為患，嫌犯被拒收，在倫蒂尼恩塔內關押23天后釋放。"
  },
  Item_45298_Desc = {
    Text = "記錄此鑰令後，可在編隊時選擇鑰令技能：「春天的獻詩」。\n\n收下這首，春天獻給花園的詩吧\n在我們荒寂的生命裡，玫瑰正殷紅地棲居。"
  },
  Item_45298_Name = {
    Text = "春天的獻詩"
  },
  Item_45298_StoryDesc = {
    Text = "收下這首，春天獻給花園的詩吧\n在我們荒寂的生命裡，玫瑰正殷紅地棲居。"
  },
  Item_45299_Desc = {
    Text = "記錄此鑰令後，可在編隊時選擇鑰令技能：「黑天鵝的舞步」。\n\n盈步。跳剪。旋轉。在舞曲的高潮處，縱身躍入火焰。\n燃燒吧。燃燒，是舞蹈唯一的答案。"
  },
  Item_45299_Name = {
    Text = "黑天鵝的舞步"
  },
  Item_45299_StoryDesc = {
    Text = "盈步。跳剪。旋轉。在舞曲的高潮處，縱身躍入火焰。\n燃燒吧。燃燒，是舞蹈唯一的答案。"
  },
  Item_45300_Desc = {
    Text = "記錄此鑰令後，可在編隊時選擇鑰令技能：「海之祭」。\n\n利莫里亞的主祭，從不期待海洋的回應。\n\n她將一切獻予海洋，這與海洋無關。"
  },
  Item_45300_StoryDesc = {
    Text = "利莫里亞的主祭，從不期待海洋的回應。\n\n她將一切獻予海洋，這與海洋無關。"
  },
  Item_45301_Desc = {
    Text = "記錄此鑰令後，可在編隊時選擇鑰令技能：「一聲槍響」。\n\n「砰——」\n一聲劃破長空的槍鳴，貫穿陰謀幕後主使者的心臟。\n\n死亡不是生命的結束，只是謎題反轉的高點。"
  },
  Item_45301_Name = {
    Text = "一聲槍響"
  },
  Item_45301_StoryDesc = {
    Text = "「砰——」\n一聲劃破長空的槍鳴，貫穿陰謀幕後主使者的心臟。\n\n死亡不是生命的結束，只是謎題反轉的高點。"
  },
  Item_45302_Desc = {
    Text = "記錄此鑰令後，可在編隊時選擇鑰令技能：「群山的覺悟」。\n\n極寒冰川的群山吞噬了英武的戰士和癲狂的野獸，以潔白的積雪掩蓋故事的殘骸。\n但在來年開春之後，微弱的生機終將跨越風雪。群山早已做好覺悟。"
  },
  Item_45302_Name = {
    Text = "群山的覺悟"
  },
  Item_45302_StoryDesc = {
    Text = "極寒冰川的群山吞噬了英武的戰士和癲狂的野獸，以潔白的積雪掩蓋故事的殘骸。\n但在來年開春之後，微弱的生機終將跨越風雪。群山早已做好覺悟。"
  },
  Item_46606_Desc = {
    Text = "用於在「人格解析」中進行交換的道具。\n\n並非所有的記憶都忠誠可靠。\n告訴你一個秘密：β是個徹頭徹尾的騙子，它在撒謊。"
  },
  Item_46606_Name = {
    Text = "記憶拼圖α"
  },
  Item_46607_Desc = {
    Text = "用於在「人格解析」中進行交換的道具。\n\n真相：α和β都在撒謊。\n現在我冒著被徹底湮滅的風險告訴你這個@#%……&"
  },
  Item_46607_Name = {
    Text = "記憶拼圖γ"
  },
  Item_46608_Desc = {
    Text = "用於在「人格解析」中進行交換的道具。\n\n啊，妒忌！你是流言的母親。\n我對α的指控深表遺憾。據我所知，它才是那個撒謊的傢伙。"
  },
  Item_46608_Name = {
    Text = "記憶拼圖β"
  },
