  Item_47302_Name = {
    Text = "記憶拼圖β"
  },
  Item_47303_Desc = {
    Text = "用於在「人格解析」中進行交換的道具。\n\n並非所有的記憶都忠誠可靠。\n告訴你一個秘密：β是個徹頭徹尾的騙子，它在撒謊。\n\n至少掉落{s1}個"
  },
  Item_47303_Name = {
    Text = "記憶拼圖α"
  },
  Item_47304_Desc = {
    Text = "逸散在蠟像館的情緒粒子，觸碰時彷彿看見眼淚、紅色絲帶和霧中的倫蒂尼恩。\n用於提升守密人在活動玩法「記憶編碼」和特遣紀錄「寧靜的裂殖」中的共鳴。\n可在限時活動「多重療癒」中完成成就獎勵獲取。"
  },
  Item_47519_Desc = {
    Text = "屬性為暴擊傷害的命輪。"
  },
  Item_47519_Name = {
    Text = "深海的呼喚"
  },
  Item_47519_StoryDesc = {
    Text = "王座的幻夢中，王聆聽神明的啟示：\n利莫里亞的風暴將平息。利莫里亞的深淵將消逝。\n以夢境為庭，以星辰為燭。王將庇護他良善的子民，帶來神的國度。\n\n吾主之信徒，敞開你的心懷，接納吾主。\n在遙遠的黯淡深淵，古老的偉大靈魂沉眠，傾聽諸神的低語。\n祂的意志如星辰之網交織，祂在永恆的虛無中候汝入夢。\n\n風暴靜伏，水波不興；\n地震平息，大地安寧。\n災禍在祂的寧靜夢境中化為虛無，\n子民在祂的庇護下安然無恙。\n願我們的歌聲穿越深海，願祂賜予我們免受災難的神諭，\n領我們前往無盡的安寧與極樂之境。\n我們的信念與祂同在，直至星辰消亡，直至時間盡頭。\n"
  },
  Item_47520_Desc = {
    Text = "屬性為死亡抵抗的命輪。"
  },
  Item_47520_Name = {
    Text = "往昔的花與詩"
  },
  Item_47520_StoryDesc = {
    Text = "自從她的詩篇風靡西岱，好友便更加殷勤地為她送來鮮花。\n「用不了那麼多花，柯蕾特，這實在是太浪費了。」\n今天拿來的玫瑰與昨天、前天、大前天的堆在一起，舊的花朵甚至開始因過於擁擠而腐爛。\n「怎麼會浪費呢，我們從前說好的，用我的花換你的詩。」\n柯蕾特搖了搖頭，有些訕訕地望著她。\n是啊，用花換詩，這是她們的約定。她能感覺到，某些事情似乎變了，但她不願意再往下想。\n她繼續寫詩，不分晝夜地寫詩。從前她的詩會自然從筆端流淌而出，如今，她的筆竟然有些滯澀起來。\n好友送來鮮花時的眼神讓她越來越陌生，她看著滿屋匆匆爛掉的玫瑰，聞著那些凋零的腐臭，由衷感到惋惜與惆悵。\n可她從來沒有停下過手中的筆。\n「我會靠這塊土地上長出的花，給我們買衣服，買吃的。總有一天，就連上面那棟樓房裡的房子，我也要買下來！」\n「每個人都有自己生來就要做的事。我生來就是要為這個花園、為那間房子努力……而你，你生來就是要寫詩的。」\n「我相信你，奧爾拉！從今天開始，你的所有詩我都會幫你好好珍藏起來。以後，我就用我的花，來換你的詩吧！」\n花與詩，是她們給對方的承諾。\n她永遠不會停下手中的筆。"
  },
  Item_47521_Desc = {
    Text = "屬性為狂氣回充等級的命輪。"
  },
  Item_47521_Name = {
    Text = "灼熱的吻別"
  },
  Item_47521_StoryDesc = {
    Text = "沐浴黑血而重獲新生的少女，在沙漠縈繞千年的風沙之中，托舉起豐穰母樹神聖的血之種。\n\n「只要這顆種子存活於世，樹的血脈就不會斷絕。」\n\n自那之後又是千年，這顆種子隨著樹的後裔見證了榮辱興衰，體驗了流離失所，經歷了不知所蹤，消亡而後重生，直到滔滔河水化為黏稠的黑血，它也完成了最後一次傳承。\n那是個熾熱滾燙而糾纏不休的吻，飽含尚未滿足的渴望和未及啟齒的離愁別緒，與溫暖的心跳一起將新的傳承者重重包裹。\n那瑪瑙般的色彩、白玉般的光澤，將隨著生命的搏動一起跨越黑色的終末。\n然後新世界的第一顆樹種，將在她的祝福下拔地而起，化作覆蓋天地的巨木。"
  },
  Item_48014_Desc = {
    Text = "記錄此鑰令後，可在編隊時選擇鑰令技能：「腦中之音」。\n\n雙手交握的那一刻，你們從對方的眼裡看到了迷茫與困惑。\n殘缺的聲部在此交匯，皆因你們早已遺落了過往。\n沉默的樂章即將譜寫，皆因你們決心墜入未來。"
  },
  Item_48014_Name = {
    Text = "未至遺忘的黎明"
  },
  Item_48014_StoryDesc = {
    Text = "雙手交握的那一刻，你們從對方的眼裡看到了迷茫與困惑。\n殘缺的聲部在此交匯，皆因你們早已遺落了過往。\n沉默的樂章即將譜寫，皆因你們決心墜入未來。"
  },
  Item_48113_Desc = {
    Text = "不小心人格分裂了怎麼辦？別慌，彌薩格早有準備！\n用以保證守密人身心健康的良方，在「多重療癒」期間限時供應。"
  },
  Item_48113_Name = {
    Text = "解離急性療程"
  },
  Item_48114_Desc = {
    Text = "一個療程沒效果怎麼辦？那就再來一個療程！\n用以保證守密人身心健康的良方，在「多重療癒」期間限時供應。"
  },
  Item_48114_Name = {
    Text = "解離鞏固療程"
  },
  Item_48115_Desc = {
    Text = "永遠不要質疑父神、《幾何原本》和醫生的處方。\n用以保證守密人身心健康的良方，在「多重療癒」期間限時供應。"
  },
  Item_48115_Name = {
    Text = "解離康復療程"
  },
  Item_48594_Desc = {
    Text = "能夠使守密人的細胞活性增強，在「每日試訓」中獲取雙倍無垢之芯、銀芯和守密人經驗，並且「相位對弈」可使用所有卡牌。僅在本期課題有效。\n超量激活突觸活躍的副作用未知，限時限量，不可過度攝入。"
  },
  Item_48594_Name = {
    Text = "突觸活性酶片"
  },
  Item_48700_Desc = {
    Text = "用於在「欲孽滋生」中進行交換的道具。\n\n一枚小小的，圓圓的種子。\n終將萌發，扎根，成長為遮天蔽日的葳蕤大樹。"
  },
  Item_48700_Name = {
    Text = "豐穰種核"
  },
  Item_48828_Desc = {
    Text = "屬性為死亡抵抗的命輪。"
  },
  Item_48828_Name = {
    Text = "極夜與破曉"
  },
  Item_48828_StoryDesc = {
    Text = "他們在黑暗的河流中划行，蒼白，沉默，疲憊不堪。\n朦朧的霧氣伸長觸手，將他們拉入黑暗，徘徊在沒有盡頭的永夜中。\n\n後來，他們看到了一束光。\n那是來自遙遠岸邊的曦光，它忽明忽滅，卻足以照亮暗淡的靈魂。\n於是他們循著光，笨拙地劃出黑暗，來到破曉的黎明面前。\n也來到你們面前。\n\n或許這只是一次短暫的相逢，但他們用力揮舞雙手，竭力呼喊。\n所有人都沐浴在神聖的曦光下，所有人都在笑著。\n他們說——\n願每一個相聚的瞬間都如節日般珍貴。\n願真誠的心永不停止跳動。\n願銀鑰指引前行。"
  },
  Item_48924_Desc = {
    Text = "逸散在勒姆瓦希沙漠中的情緒粒子。觸碰時彷彿聽見了曖昧的低吟。\n用於提升守密人在調查事件「欲河」中的共鳴。"
  },
  Item_48924_Name = {
    Text = "愛憐之心"
  },
  Item_49204_Desc = {
    Text = "記錄此鑰令後，可在編隊時選擇鑰令技能：「唯一的種子」。\n\n她將唯一的種子，渡讓至你的口舌。\n血脈的力量，傳承的信仰，超越的勇氣，還有深沉的愛意……她將她的一切託付給你。"
  },
  Item_49204_Name = {
    Text = "唯一的種子"
  },
  Item_49204_StoryDesc = {
    Text = "她將唯一的種子，渡讓至你的口舌。\n血脈的力量，傳承的信仰，超越的勇氣，還有深沉的愛意……她將她的一切託付給你。"
  },
  Item_49263_Desc = {
    Text = "在「學期課題」中購買「核心課題」後可獲得。\n「吧唧吧唧……小蛋糕好吃……」"
  },
  Item_49263_Name = {
    Text = "以銀鑰之名：守密人"
  },
  Item_49263_StoryDesc = {
    Text = "第5期學期課題"
  },
  Item_49264_Desc = {
    Text = "在「學期課題」中購買「核心課題」後可獲得。\n根據守密人性別不同而不同"
  },
  Item_49264_Name = {
    Text = "以銀鑰之名：守密人"
  },
  Item_49264_StoryDesc = {
    Text = "第5期學期課題"
  },
  Item_49265_Desc = {
    Text = "在「學期課題」中購買「核心課題」後可獲得。\n「嘶……好像長蛀牙了？」"
  },
  Item_49265_Name = {
    Text = "以銀鑰之名：守密人"
  },
  Item_49265_StoryDesc = {
    Text = "第5期學期課題"
  },
  Item_49266_Name = {
    Text = "相位通訊：守密人·大事不妙"
  },
  Item_49271_Desc = {
    Text = "在「學期課題」中購買「核心課題」後可獲得。\n「不允許你們靠近守密人半步……！」"
  },
  Item_49271_Name = {
    Text = "以銀鑰之名：環行·拉蒙娜"
  },
  Item_49271_StoryDesc = {
    Text = "第5期學期課題"
  },
  Item_49318_Desc = {
    Text = "後勤部向完成「調查行動」的守密人發放了特別許可，在每次完成調查行動後，守密人都可以為下一次的出發購置一批特別的珍貴銀芯製品。\n數量有限，願銀鑰指引我們。"
  },
  Item_49318_Name = {
    Text = "調查歷程特典Ⅶ"
  },
  Item_49464_Desc = {
    Text = "「把五支羽毛筆綁在一起，就可以將密契抄寫速度提升至五倍。守密人也來試試吧！」\n某個可憐的喚醒體因使用小竅門逃避罰抄而被茜爾維婭的粉筆正中腦門。"
  },
  Item_49464_Name = {
    Text = "密契摘錄集"
  },
  Item_49465_Desc = {
    Text = "「注意關注聖河負載能力和自我調節限度，並探明含沙量異常的原因。」\n後勤部提供給守密人進行聖河地理勘測的特殊補給。"
  },
  Item_49465_Name = {
    Text = "水文監測支援"
  },
  Item_49466_Desc = {
    Text = "「秘密一定就在地下，在母樹根系覆蓋的最深處……那裡絕對藏著什麼不可告人的……」\n後勤部提供給守密人進行聖河地理勘測的特殊補給。"
  },
  Item_49466_Name = {
    Text = "地層鑽探支援"
  },
  Item_49467_Desc = {
    Text = "「自從A.F.225年後，我們就再未觀測到聖河源頭的所在。」\n後勤部提供給守密人進行聖河地理勘測的特殊補給。"
  },
  Item_49486_Desc = {
    Text = "在活動「欲海翻波」中完成成就獲得。\n「來吧，與我誕下子嗣，同享永恆的歡愉……」"
  },
  Item_49486_Name = {
    Text = "以銀鑰之名：泰旖絲"
  },
  Item_49486_StoryDesc = {
    Text = "泰旖絲玩法活動"
  },
