  },
  Item_51996_Name = {
    Text = "以銀鑰之名：莉茲"
  },
  Item_51996_StoryDesc = {
    Text = "第6期學期課題"
  },
  Item_52037_Desc = {
    Text = "用於在「靈髓祭壇」中進行交換的道具。\n獻上你的髓吧，祭祀之人。所有的期願，神國將應許。"
  },
  Item_52038_Desc = {
    Text = "用於在「猩血祭壇」中進行交換的道具。\n獻上你的血吧，祭祀之人。所有的罪孽，神國將責罰。"
  },
  Item_52039_Desc = {
    Text = "用於在「瑩淚祭壇」中進行交換的道具。\n獻上你的淚吧，祭祀之人。所有的苦難，神國將償還。"
  },
  Item_52039_Name = {
    Text = "祀者之淚"
  },
  Item_52069_Desc = {
    Text = "逸散在利莫里亞的情緒粒子，觸碰時彷彿能聽到誰的祈禱與哀泣。\n用於提升守密人在活動玩法「神國誕臨」中的共鳴。\n可在限時活動「沉淵之祀」中完成成就獎勵獲取。"
  },
  Item_52070_Desc = {
    Text = "在活動「沉淵之祀」中完成成就獲得。\n「祂的意志仍在深海之中沉眠……我等亦不能落於其後……」"
  },
  Item_52070_Name = {
    Text = "以銀鑰之名：彌利亞姆"
  },
  Item_52070_StoryDesc = {
    Text = "彌利亞姆玩法活動"
