    Text = "祀者之淚"
  },
  Item_52304_Desc = {
    Text = "「限定每週一次，過量供應可能會對健康造成不良影響，我們必須對你的安全負責哦。」\n醫務室裡，茜爾維婭困擾地捋了捋散落的髮梢。"
  },
  Item_52304_Name = {
    Text = "周常流明供給"
  },
  Item_52305_Desc = {
    Text = "那沉眠於至暗至深之處的王的誕生將扭曲整片神識之海。\n用以抵抗異夢侵蝕的儀式，在「沉淵之祀」期間限時供應。"
  },
  Item_52305_Name = {
    Text = "神國王誕密儀"
  },
  Item_52306_Desc = {
    Text = "深海氾濫的潮湧衝擊意識的邊界。\n用以抵抗異夢侵蝕的儀式，在「沉淵之祀」期間限時供應。"
  },
  Item_52306_Name = {
    Text = "潮蝕防衛密儀"
  },
  Item_52307_Desc = {
    Text = "異夢視界中的天災亦會通過精神共振干擾守密人的靈智。\n用以抵抗異夢侵蝕的儀式，在「沉淵之祀」期間限時供應。"
  },
  Item_52307_Name = {
    Text = "天災戒備密儀"
  },
  Item_53730_Desc = {
    Text = "「歡迎回家。」"
  },
  Item_53730_Name = {
    Text = "返校邀約"
  },
  Item_53746_Desc = {
    Text = "用於在「金紅慶典」中進行交換的道具。\n\n索蕾爾夫人收藏的羽扇。有人相信它能預測股票走勢。"
  },
  Item_53746_Name = {
    Text = "通靈鳥羽扇"
  },
  Item_53766_Desc = {
    Text = "在活動「與薔薇書」中完成成就獲得。\n「這就是權力的香味嗎？我甚感滿意。」"
  },
  Item_53766_Name = {
    Text = "以銀鑰之名：索蕾爾"
  },
  Item_53766_StoryDesc = {
    Text = "索蕾爾玩法活動"
  },
  Item_53767_Desc = {
    Text = "屬性為暴擊率的命輪。"
  },
  Item_53767_Name = {
    Text = "百萬蒙寵之眼"
  },
  Item_53767_StoryDesc = {
    Text = "祂伏行於無垠的混沌中，偶爾才對匍匐世間的眾生投去一縷瞥視。\n\n那些尚可入眼的，譬如索蕾爾，祂向他們提供難以被拒絕的「契約條款」。\n那些粗陋乏味的，祂褪去他們的肉身，留下一隻再也無法落淚的眼睛。\n這些眼睛又被喚作「蒙寵者」。\n\n它們在洞穴中忽明忽暗，既滿懷希望，又充滿絕望，等待祂的召喚。\n然而一千年過去，一萬年過去，蒙寵者繼續被遺忘在黑暗的角落。\n\n「那……你們一定是因為某種理由才被留下吧。你們的使命是什麼？」\n「我們在等待。」\n「等待什麼？」\n「等待……就只是等待而已。」\n「會感到痛苦嗎？」\n「恰恰相反。對大人的愛充盈我們全身。因為這是我們唯一能做的事。」\n「只有理解這一點，才能成為真正的信徒。」"
  },
  Item_53871_Desc = {
    Text = "用於在「金紅慶典」中進行交換的道具。\n\n索蕾爾夫人收藏的羽扇。有人相信它能預測股票走勢。\n\n至少掉落{s1}個"
