  },
  Item_54578_Desc = {
    Text = "獲得守密人經驗時，額外獲得20%的守密人經驗。多個效果時取最高值，不可疊加。\n\n據《源液的精神影響報告》，參與源液提取工作的個體，會在工作結束後表現出一定程度的精力、智力等方面的加強。提取時間越長，提取的源液量越多，效果越明顯。\n即使只是逸散的顆粒，源液蘊含的力量依舊不容小覷。"
  },
  Item_54578_Name = {
    Text = "至高禮讚·Ⅱ"
  },
  Item_54579_Desc = {
    Text = "極少數守密人才能擁有的身分標識。\n源液提取時，會有微小的顆粒四散飛舞。不知為何，它們格外青睞金屬物件，使守密人佩戴的身分標識染上柔和的銀白。\n據說這樣的印記具有特殊功效。"
  },
  Item_54579_Name = {
    Text = "銀白之矩"
  },
  Item_54579_StoryDesc = {
    Text = "累計儲值頭像框"
  },
