  Item_55305_Name = {
    Text = "惆悵的詩文"
  },
  Item_55471_Desc = {
    Text = "需要念誦詩文才會開啟的神秘匣子。\n向它描述花的夢，它會贈你一束薔薇。\n在「在春天凋零以前」期間限時供應。"
  },
  Item_55471_Name = {
    Text = "花與詩的夢"
  },
  Item_55472_Desc = {
    Text = "需要念誦詩文才會開啟的神秘匣子。\n當你的意象恰到好處，它會讓你看到真實。\n在「在春天凋零以前」期間限時供應。"
  },
  Item_55472_Name = {
    Text = "意與詩的夢"
  },
  Item_55473_Desc = {
    Text = "需要念誦詩文才會開啟的神秘匣子。\n向它描述你的過去，它會贈你一抹回憶。\n在「在春天凋零以前」期間限時供應。"
  },
  Item_55473_Name = {
    Text = "心與詩的夢"
  },
  Item_55891_Desc = {
    Text = "祂在長夢中賜予靈性豐沛之人神啟：禁忌的學識是虛榮者的詛咒，無知是贈予愚者的恩賜。\n在「神王復甦」期間限時供應。"
  },
  Item_55891_Name = {
    Text = "倦怠夢魘神像"
  },
  Item_55892_Desc = {
    Text = "祂在長夢中賜予靈性豐沛之人神啟：神明從未遺留旨意，禱告和祈願皆為徒勞。\n在「神王復甦」期間限時供應。"
  },
  Item_55892_Name = {
    Text = "慵懶夢魘神像"
  },
  Item_55893_Desc = {
    Text = "祂在長夢中賜予靈性豐沛之人神啟：祂自群星而來，祂的國度終將升起。\n在「神王復甦」期間限時供應。"
  },
  Item_55893_Name = {
    Text = "譫妄夢魘神像"
  },
  Item_55894_Desc = {
    Text = "不小心人格分裂了怎麼辦？別慌，彌薩格早有準備！\n用以保證守密人身心健康的良方，在「多重療癒」期間限時供應。"
  },
  Item_55894_Name = {
    Text = "解離急性療程"
  },
  Item_55895_Desc = {
    Text = "一個療程沒效果怎麼辦？那就再來一個療程！\n用以保證守密人身心健康的良方，在「多重療癒」期間限時供應。"
  },
  Item_55895_Name = {
    Text = "解離鞏固療程"
  },
  Item_55896_Desc = {
    Text = "永遠不要質疑父神、《幾何原本》和醫生的處方。\n用以保證守密人身心健康的良方，在「多重療癒」期間限時供應。"
  },
  Item_55896_Name = {
    Text = "解離康復療程"
  },
  Item_55897_Desc = {
    Text = "受苦難的靈魂啊，你將被嘉獎，仁愛的主教要代父神為你降下賜福。\n在「靈魂的牧人·復刻」期間限時供應。"
  },
  Item_55897_Name = {
    Text = "彌撒後的賜福"
  },
  Item_55898_Desc = {
    Text = "受苦難的靈魂啊，萬不可失去希望，仁愛的主教會為你向父神獻上禱告。\n在「靈魂的牧人·復刻」期間限時供應。"
  },
  Item_55898_Name = {
    Text = "彌撒中的祈禱"
  },
  Item_55899_Desc = {
    Text = "受苦難的靈魂啊，不需要迷茫，仁愛的主教會為你指引方向。\n在「靈魂的牧人·復刻」期間限時供應。"
  },
  Item_55899_Name = {
    Text = "彌撒前的指引"
  },
  Item_55900_Desc = {
    Text = "你聽到無數的宇宙中有無數聲呼喊，他們在呼喚你的姓名。\n你握緊雙手，大聲回應。\n在「萬象門扉」期間限時供應。"
  },
  Item_55900_Name = {
    Text = "回聲門扉"
  },
  Item_55901_Desc = {
    Text = "虛幻的門扉向你而來，無數個宇宙破碎又重啟。\n門扉的光芒閃爍，你知道它選擇了你，它將一切交給了你。\n在「萬象門扉」期間限時供應。"
  },
  Item_55901_Name = {
    Text = "命定門扉"
  },
  Item_55902_Desc = {
    Text = "你看見無數的宇宙中有無數的人們，他們都和你有關。\n無數雙手伸向你，他們前仆後繼，將你高高托舉。\n在「萬象門扉」期間限時供應。"
  },
  Item_55902_Name = {
    Text = "幻象門扉"
  },
  Item_55904_Desc = {
    Text = "交響樂曲的最終篇章，樂曲的主題在此定論，請欣賞充滿希望的凱旋頌歌。\n在「無形交響」期間限時供應。"
  },
  Item_55904_Name = {
    Text = "迴旋曲樂譜"
  },
  Item_55905_Desc = {
    Text = "在艾爾沃斯山頂新生的蒲公英的種子，從凍土中長出的小小野草散發著勃勃生機。\n在「雪山消融之時」期間限時供應。"
  },
  Item_55905_Name = {
    Text = "雪山蒲公英種子"
  },
  Item_55906_Desc = {
    Text = "在艾爾沃斯山頂新生的常青樹的種子，堅韌的樹苗終會越過風霜雨雪，長成參天的巨木。\n在「雪山消融之時」期間限時供應。"
  },
  Item_55906_Name = {
    Text = "雪山常青樹種子"
  },
  Item_55907_Desc = {
    Text = "在艾爾沃斯山頂新生的潔白花朵的種子，冰與雪作它的枝與葉，嚴寒也不能催折它的芬芳。\n在「雪山消融之時」期間限時供應。"
  },
  Item_55907_Name = {
    Text = "雪山銀霜花種子"
  },
  Item_55908_Desc = {
    Text = "交響樂曲的開篇，戲劇性的核心在此展現，請欣賞截然相反的主題彼此拉扯較量。\n在「無形交響」期間限時供應。"
  },
  Item_55908_Name = {
    Text = "奏鳴曲樂譜"
  },
  Item_55910_Desc = {
    Text = "戴上貝雷帽的一刻，偵探的眼神也銳利了起來，無人敢質疑你的專業身分。\n在「名偵探手冊」期間限時供應。"
  },
  Item_55910_Name = {
    Text = "偵探貝雷帽裝束"
  },
  Item_55911_Desc = {
    Text = "穿上風衣就會擁有背後音樂響起的氣場，讓風吹動你的衣襬，擺出你帥氣的推理姿勢吧！\n在「名偵探手冊」期間限時供應。"
  },
  Item_55911_Name = {
    Text = "偵探風衣裝束"
  },
  Item_55912_Desc = {
    Text = "刻板印象中的偵探必備飾品，請在沉思時使用，哪怕是空的也比叼棒棒糖帥氣。\n在「名偵探手冊」期間限時供應。"
  },
  Item_55912_Name = {
    Text = "偵探煙斗裝束"
  },
  Item_55914_Desc = {
    Text = "疼痛即是疼愛，在感受到女王的愛時，記得要大聲呼喊女王的尊名。\n在「燃燒的群宴」期間限時供應。"
  },
  Item_55914_Name = {
    Text = "鞭笞的寵愛"
  },
  Item_55915_Desc = {
    Text = "低下你的頭顱，匍匐於女王的腳下吧，你將成為女王光榮的座椅與腳踏。\n在「燃燒的群宴」期間限時供應。"
  },
  Item_55915_Name = {
    Text = "踐踏的寵愛"
  },
  Item_55916_Desc = {
    Text = "接受女王的考驗，展示你的忠誠吧，你只需要服從。\n當女王的臉上露出笑容，你會獲得她身邊榮耀的位置。\n在「燃燒的群宴」期間限時供應。"
  },
  Item_55916_Name = {
    Text = "命令的寵愛"
  },
  Item_55917_Desc = {
    Text = "從母樹上取下的形似孕婦的樹瘤，能夠感受到其中孕育般蓬勃而無窮的活力，仔細聽，那是母親的呼喚。\n在「欲海翻波·復刻」期間限時供應。"
  },
  Item_55917_Name = {
    Text = "慈母母樹畸瘤"
  },
  Item_55918_Desc = {
    Text = "從母樹上取下的形似少女的樹瘤，能夠感受到其中纖細而柔和的活力，仔細聽，那是青澀的邀請。\n在「欲海翻波·復刻」期間限時供應。"
  },
  Item_55918_Name = {
    Text = "少女母樹畸瘤"
  },
  Item_55919_Desc = {
    Text = "從母樹上取下的形似嬰兒的樹瘤，能夠感受到其中生命誕生般的活力，仔細聽，那是新生的啼哭。\n在「欲海翻波·復刻」期間限時供應。"
  },
  Item_55919_Name = {
    Text = "嬰孩母樹畸瘤"
  },
  Item_55920_Desc = {
    Text = "與某位淑女同款的陽傘，撐開時可以獲得淑女永不低頭的自信。\n在「群星正位」期間限時供應。"
  },
  Item_55920_Name = {
    Text = "淑女陽傘贈禮"
  },
  Item_55921_Desc = {
    Text = "交響樂曲抒情後的娛樂篇章，如同生命有力的脈搏，請欣賞靜觀與沉思後自由詼諧的趣味。\n在「無形交響」期間限時供應。"
  },
  Item_55921_Name = {
    Text = "小步舞曲樂譜"
  },
  Item_55922_Desc = {
    Text = "某位淑女送給你的下午茶會請柬，請來品嘗美味的甜點，與洋娃娃和小熊一起跳舞吧。\n在「群星正位」期間限時供應。"
  },
  Item_55922_Name = {
    Text = "淑女請柬贈禮"
  },
  Item_55923_Desc = {
    Text = "與某位淑女同款的洋裙，穿上後可以獲得淑女優雅高貴的氣質。\n在「群星正位」期間限時供應。"
  },
  Item_55923_Name = {
    Text = "淑女洋裙贈禮"
  },
  Item_56483_Desc = {
    Text = "代表著時代前沿技術的精密齒輪，可以代謝掉人偶老舊的部分。\n朵爾用於維修軀體的齒輪零件。用於在商店交換所需物資。"
  },
  Item_56484_Desc = {
    Text = "一枚平平無奇的籌碼，為你帶來跌宕起伏的人生。\n用於在「好運俱樂部」交換物資。"
  },
  Item_56484_Name = {
    Text = "決勝籌碼"
  },
  Item_56485_Desc = {
    Text = "原初的音符，於伊始之地，指引整支樂隊邁向最終的高潮。用於在「安眠宮殿」交換物資。"
  },
  Item_56485_Name = {
    Text = "高亢樂章"
  },
  Item_56486_Desc = {
    Text = "指針輪轉不歇，與無回者一同向前。\n在抵達終焉之刻，所有門扉將為你開啟，所有樂章將為你奏響。\n窮極之門前精密的指針，用於在「回聲」交換物資。"
  },
  Item_56486_Name = {
    Text = "終末指針"
  },
  Item_56487_Desc = {
    Text = "祂的靈識仍沉眠於深淵之中。\n深海中飄蕩的胚胎，用於在「聖胎孵化」交換物資。"
  },
  Item_56487_Name = {
    Text = "無識之胚"
  },
  Item_56488_Desc = {
    Text = "祂吞噬萬物，永無饜足。\n深海中飄蕩的胚胎，用於在「聖胎孵化」交換物資。"
  },
  Item_56488_Name = {
    Text = "無厭之胚"
  },
  Item_56489_Desc = {
    Text = "祂對此世無慾無求。\n深海中飄蕩的胚胎，用於在「聖胎孵化」交換物資。"
  },
  Item_56489_Name = {
    Text = "無慾之胚"
  },
  Item_56490_Desc = {
    Text = "冰雪為它鍍上幽藍，慶賀不屈的生命在此誕生。\n從艾爾沃斯山頂新生的花苞，用於在「吞食的野心」交換物資。"
  },
  Item_56490_Name = {
    Text = "寒凍花苞"
  },
  Item_56491_Desc = {
    Text = "月色為它鍍上銀白，慶賀不屈的生命在此誕生。\n從艾爾沃斯山頂新生的花苞，用於在「復仇的戰意」交換物資。"
  },
  Item_56491_Name = {
    Text = "銀霜花苞"
  },
  Item_56492_Desc = {
    Text = "日光為它鍍上橙黃，慶賀不屈的生命在此誕生。\n從艾爾沃斯山頂新生的花苞，用於在「重生的希冀」交換物資。"
  },
  Item_56493_Desc = {
    Text = "逸散在艾爾沃斯雪山中的情緒粒子。觸碰時彷彿聽見了野獸的撕咬與吞嚥聲。\n用於提升守密人在活動玩法「山巒巨口」和特遣紀錄「艾爾沃斯的歸人」中的共鳴。\n可在限時活動「雪山消融之時」中完成成就獎勵獲取。"
  },
  Item_56494_Desc = {
    Text = "逸散在窮極之扉內部的情緒粒子，觸碰時彷彿聽見每一個維度與時空的絮語。\n用於提升守密人在調查事件「長夢盡時」中的共鳴。"
  },
  Item_56494_Name = {
    Text = "窮極之心"
  },
  Item_56495_Desc = {
    Text = "逸散在彌薩格校園中的情緒粒子，觸碰時彷彿聽見了無數的嘶吼與嘆息。\n用於提升守密人在調查事件「終末交響曲」中的共鳴。"
  },
  Item_56495_Name = {
    Text = "堅韌之心"
  },
  Item_56635_Desc = {
    Text = "屬性為傷害強效的命輪。"
  },
  Item_56635_StoryDesc = {
    Text = "她站上山峰，舉起手中的黑刺。\n在漫天的風雪裡，她迎上了那座瘋狂的山脈，迎上了自己被拋棄、被背叛、被踐踏的命運。\n她終將勝利，冰雪終將消融，到那時，她將以一個嶄新的姿態，重現於世。她是這樣說的。\n艾爾沃斯是極寒之地，那裡的風雪終年不散。這是常識。就像再強大的戰士也無法與崇高的存在抗衡，就像再強大的人也無法戰勝自己的命運。\n可那雪山終究還是消融了，不是嗎？"
  },
  Item_56636_Desc = {
    Text = "記錄此鑰令後，可在編隊時選擇鑰令技能：「門扉的答案」。\n\n萬物的真相隱於門扉之後。\n她靜默於此，承受所有叩問，以無聲作為回應。\n她等候之人終會撰寫自己的答案。"
  },
  Item_56636_Name = {
    Text = "門扉的答案"
  },
  Item_56636_StoryDesc = {
    Text = "萬物的真相隱於門扉之後。\n她靜默於此，承受所有叩問，以無聲作為回應。\n她等候之人終會撰寫自己的答案。"
  },
  Item_56637_Desc = {
    Text = "屬性為狂氣回充等級的命輪。"
  },
  Item_56637_StoryDesc = {
    Text = "茫茫多的羊群徘徊在茫茫大的草原上。\n這世上有太多太多的羊，而羊生來就是需要牧者引領的。\n她一直是這世界的先知，手中握著知識的權杖。\n她一直是一個好牧人，始終決心將羊群引向正確的道路。\n她用那杖管教羔羊，她用那杖趕走豺狼。\n她高舉著牧羊人的手杖，因她總能提前看清前路。\n曾經她引領羊群走向豐沛的水源、走向鮮嫩的草場。\n現在她目睹了世界的真相，於是引領羊群走向終極的懷抱。\n向這邊走，不要回頭。\n她笑著揮舞智慧的手杖。\n於是羊們看不到前方的懸崖。\n一隻，兩隻。\n羊兒墜下，牧人歡唱。\n請跟隨著無私的牧羊人吧，她已為你指明瞭最真切的前路。\n不必害怕，即便行過死蔭的幽谷，她的杖依然與你同在。\n直到一同步入湮滅的深淵。\n"
  },
  Item_56638_Desc = {
    Text = "記錄此鑰令後，可在編隊時選擇鑰令技能：「第四樂章」。\n\n音符彙集成奔湧的星海，主題在恢弘的深空中舞蹈。\n 閉目聆聽吧。聆聽宇宙的落幕，聆聽宇宙的高潮。"
  },
  Item_56638_Name = {
    Text = "第四樂章"
  },
  Item_56638_StoryDesc = {
    Text = "音符彙集成奔湧的星海，主題在恢弘的深空中舞蹈。\n 閉目聆聽吧。聆聽宇宙的落幕，聆聽宇宙的高潮。"
  },
  Item_56639_Desc = {
    Text = "屬性為暴擊率的命輪。"
  },
  Item_56639_StoryDesc = {
    Text = "「還不夠完美，今晚再練十遍，你的天賦平平，想進入樂團就要更加勤奮，知道嗎？」\n「是，父親。」\n什麼樣的演奏才叫完美？\n他的雙手不停飛舞，不容許自己出現一個失誤。\n他斥責自己的雜念，鄙夷自己的平庸。\n無數音符環繞在眼前，每天，每天，他生活中的一切只有音樂。\n好在他每天都離完美的演奏距離更近了一些，他望著夢中道路盡頭的光芒，又彷彿永遠也無法觸及。\n渴求完美已經刻入他的靈魂，然而不是所有人都願意這樣。\n「為陛下、為世人呈現最完美的音樂，這難道不是樂團的職責嗎？」\n他望著一張張暗含不滿的臉，如同鄙視曾經的自己。\n父親，宮廷樂團也不過如此。\n他拋下了曾經仰望的目標，執拗地繼續走上追尋完美的路。\n他無法停下雙手去拉住他們的手，正如他無法停住曾經那個自己的手。\n每天，每天，他都在不停演奏著。\n音樂就是他的生命。\n除了音樂，他一無所有。"
  },
  Item_56640_Desc = {
    Text = "屬性為黑印掉落的命輪。"
  },
  Item_56640_Name = {
    Text = "命運輪盤賭"
  },
  Item_56640_StoryDesc = {
    Text = "人人都想戰勝命運，人人卻也畏懼命運。\n勇敢者發出戰鬥的怒吼，怯懦者發出順從的低吟，然而只有他發現了戰勝命運的秘密。\n那就是不斷邀請命運共赴賭局，催促命運開盤下一場。\n他從未畏懼過命運，因為他相信自己不會輸。\n他從不詢問要賭什麼，無論要擺上什麼籌碼他都毫不猶豫，包括自己的生命。\n憑藉一把輪盤賭的手槍，他嚇退了無數賭紅眼的手下敗將，成為了倫蒂尼恩臭名昭著的賭瘋子。\n真遺憾啊，沒有勢均力敵的對手是多麼寂寞。\n直到他遇到了那個男人。\n他打敗了無數凡人，終於坐上了命運的賭桌。\n很快他失去了自己的一切，又連本帶利地重獲了所有。\n直到重生為野獸時，他又在地上看到了那把終於射出最後一顆子彈的手槍。\n他將一顆子彈重新裝填，對著自己的頭再次按下了扳機。\n在一片寂靜中，他咧開了嘴。\n他還沒有輸，那麼總有一天他會贏到最後。\n他始終這樣相信著，即便要賭上所有。"
  },
  Item_56641_Desc = {
    Text = "屬性為銀鑰充能的命輪。"
  },
  Item_56641_StoryDesc = {
    Text = "為了等待「那個時刻」，少女沉睡於冰川之底。艾爾沃斯的千尺寒冰封凍了她的軀殼，卻未能全然封閉她的神識。\n那縷神識來自一個孩子，也來自一位母親。在祂女兒黑暗的子宮中，神明延續萬古長夢。\n二十五年的時光中，她思考過什麼，眷戀過什麼，期待過什麼嗎？\n時至今日，這些問題已經無人能夠回答。至於那位少女本人……她會否向身邊之人傾訴真心呢？就讓一切交給時間和未來吧。"
  },
  Item_56642_Desc = {
    Text = "屬性為銀鑰充能等級的命輪。"
  },
  Item_56642_Name = {
    Text = "真理之門"
  },
  Item_56642_StoryDesc = {
    Text = "她的名字即是智慧的化身。\n她知曉世上的一切知識，是彌薩格所有學者嚮往的終極。\n只要能聆聽隻言片語，便能獲得醍醐灌頂的開悟。\n但她說，自己只是一個守門人。\n那是一扇什麼樣的門？\n沒有人見過那扇門，學者們便將其稱為真理。\n她是真理的守門人，是守護著彌薩格的雅典娜。\n塔薇並沒有否定這樣的猜測，只是始終如一地注視著這裡，注視著這個世界。\n無言而悲憫。\n如果你有一天看到了那扇門，你會看到門上有一隻極其熟悉的眼睛。\n那目光沉靜而恆久。\n穿透了時間，穿透了你的靈魂。"
  },
  Item_56643_Desc = {
    Text = "記錄此鑰令後，可在編隊時選擇鑰令技能：「虛無瘟疫」。\n\n不要直視那雙瘋狂的眼睛，小心她已將你感染。"
  },
  Item_56643_Name = {
    Text = "虛無瘟疫"
  },
  Item_56643_StoryDesc = {
    Text = "虛無是真實帶來的瘟疫，它抹去所有顏色，要把一切塗染成灰。 \n不要直視那雙瘋狂的眼睛，小心她已將你感染。"
  },
