  Item_61149_Desc = {
    Text = "後勤部向完成「調查行動」的守密人發放了特別許可，在每次完成調查行動後，守密人都可以為下一次的出發購置一批特別的珍貴銀芯製品。\n數量有限，願銀鑰指引我們。"
  },
  Item_61149_Name = {
    Text = "調查歷程特典Ⅷ"
  },
  Item_61225_Desc = {
    Text = "用於在「脊刺之握」中進行交換的道具。\n脊刺的原材料之一。經由它打磨的脊刺刺入人類胸腔，便可主宰一切。\n意志與情感？不過是生物的脆弱編碼罷了。\n\n至少掉落{s1}個"
  },
  Item_61225_Name = {
    Text = "原生脛骨"
  },
  Item_61226_Desc = {
    Text = "用於在「暗淡之縛」中進行交換的道具。\n散落在伊薩拉烏風中的巨石殘骸。\n它們靜止不動，莊嚴地為逝去的都城哀悼。\n\n至少掉落{s1}個"
  },
