  Item_61296_Name = {
    Text = "圓葉菊石"
  },
  Item_61391_Desc = {
    Text = "屬性為銀鑰充能等級的命輪。"
  },
  Item_61391_Name = {
    Text = "純銀的初心"
  },
  Item_61391_StoryDesc = {
    Text = "那是一顆銀白、澄澈、纖塵不染的心。\n它由純銀製成，在機械結構的心臟中有序搏動。\n也曾被血肉侵蝕，也曾因污泥染垢。\n但在死亡的陰霾籠罩之時，它終究回歸了本初的形貌。"
  },
  Item_61941_Desc = {
    Text = "月色為它鍍上銀白，慶賀不屈的生命在此誕生。\n從艾爾沃斯山頂新生的花苞，用於在「復仇的戰意」交換物資。\n\n至少掉落{s1}個"
  },
  Item_61941_Name = {
    Text = "銀霜花苞"
  },
  Item_61942_Desc = {
    Text = "日光為它鍍上橙黃，慶賀不屈的生命在此誕生。\n從艾爾沃斯山頂新生的花苞，用於在「重生的希冀」交換物資。\n\n至少掉落{s1}個"
  },
  Item_61943_Desc = {
    Text = "冰雪為它鍍上幽藍，慶賀不屈的生命在此誕生。\n從艾爾沃斯山頂新生的花苞，用於在「吞食的野心」交換物資。\n\n至少掉落{s1}個"
  },
