  },
  Item_67086_Desc = {
    Text = "萬千世界中飄散的無法聆聽的夢囈，感知的瞬間將被原初的誕生佔據心靈。"
  },
  Item_67086_Name = {
    Text = "原初夢囈"
  },
  Item_67087_Desc = {
    Text = "萬千世界中飄散的無法聆聽的夢囈，感知的瞬間將被徹底的盲目佔據心靈。"
  },
  Item_67087_Name = {
    Text = "癡愚夢囈"
  },
  Item_67377_Desc = {
    Text = "對於守密人來說，無論是身份標識、抑或是銀芯通訊中表達情緒的造像，都與精神力同樣重要——無形者如是說道。\n收集一定數量後使用，可隨機獲得一個專屬的頭像、對戰表情，或往期課題和相位對弈賽季的頭像、對戰表情。"
  },
  Item_67377_Name = {
    Text = "無形者的禮券"
  },
  Item_67378_Desc = {
    Text = "狡黠，善變。你向無形者證明了你的價值。很快，祂將向你發來邀請，邀請你一同成為世間萬物的化身，無影無質的終極。\n收集一定數量後使用，可選擇一個「無形者的禮券」中的未獲得的頭像或對戰表情。"
  },
  Item_67378_Name = {
    Text = "無形者的請柬"
  },
  Item_68281_Desc = {
    Text = "後勤部向完成「調查行動」的守密人發放了特別許可，在每次完成調查行動後，守密人都可以為下一次的出發購置一批特別的珍貴銀芯製品。\n數量有限，願銀鑰指引我們。"
  },
  Item_68281_Name = {
    Text = "調查歷程特典Ⅸ"
  },
  Item_68341_Desc = {
    Text = "購買後，可按時領取所有預購獎勵"
  },
  Item_68341_Name = {
    Text = "超越星辰·限時預購"
  },
  Item_68419_Desc = {
    Text = "漫長時光下，這哀愁終會被熨平。\n神王情緒在覺知的維度留下的烙印，用於在「悲愁海淵」交換物資。"
  },
  Item_68419_Name = {
    Text = "悲愁緒思"
  },
  Item_68420_Desc = {
    Text = "無需慶祝，歡悅也為虛無。\n神王情緒在覺知的維度留下的烙印，用於在「歡悅海淵」交換物資。"
  },
  Item_68420_Name = {
    Text = "歡悅緒思"
  },
  Item_68421_Desc = {
    Text = "困倦襲來，祂將再次陷入永恆的沉睡。\n神王情緒在覺知的維度留下的烙印，用於在「憊倦海淵」交換物資。"
  },
  Item_68421_Name = {
    Text = "憊倦緒思"
  },
  Item_68682_Desc = {
    Text = "屬性為狂氣回充等級的命輪。"
  },
  Item_68682_StoryDesc = {
    Text = "在無盡的深淵中，青色王座屹立，\n天幕低垂，星辰顫抖，萬物沉默。\n\n古老而又神秘的存在已然湮沒，\n世世代代，眾生在夢中頌歌。\n幽暗的水域，塵封的秘密，\n你的低語如潮水湧來，淹沒心靈的溝壑。\n\n在那無邊的夢境，先知與狂徒同遊，\n追尋無形的靈魂，恐懼與敬畏交織。\n青藻纏繞的軌跡，宛如命運的編撰，\n將迷失者的心，逐漸引向那青色王座。\n啊，宇宙的荒謬與真理，\n在夢與現實交錯之處，永恆的輝光閃爍。"
  },
  Item_68683_Desc = {
    Text = "屬性為傷害強效的命輪。"
  },
  Item_68683_Name = {
    Text = "魔女寬簷帽"
  },
  Item_68683_StoryDesc = {
    Text = "魔女和寬簷帽子的因果，有時就像雞與蛋的關係，分不清是帽子成就了魔女，還是魔女成就了帽子。\n不過總之，達芙黛爾就擁有這樣一頂足夠優雅的寬簷帽。\n這頂帽子最初屬於曾經的店主，那時達芙黛爾的名字還不屬於達芙黛爾，她尚且只是一個剛剛被制服的、迷茫的幽魂，一頭懵懂的野獸。\n那個總是微笑著的女人帶著她，如同教育孩童般，耐心地、一點點地教給她成為一個「人」的方法，以及與人打交道的秘訣。\n海港之城商貿繁華，彙聚了彼時人類文化最豐富的結晶。交換商店所在的街道上林林總總的店鋪幾乎包羅萬象，而店主總能神奇地與所有店家老友般聊上天。\n「她真厲害。」那時的達芙黛爾心想，「但也沒什麼奇怪的，沒有人會不喜歡她。」\n店主喜歡逛街，於是那便是千年來一直扮演著一個個被她斬下頭顱的人類的達芙黛爾，第一次被要求給出自己的建議。\n「你覺得哪一頂好看？這一頂小禮帽，還是這頂寬簷帽？」\n女人對著鏡子，來回試戴著琳琅滿目的帽子們。原本對於達芙黛爾來說，這些不過是用來包裹身體、將自己裝點得更像人類的道具。\n但那一天，她看著店主頭上像一朵巨大花朵般的寬簷帽，腦海中忽然浮現出了女人戴著這樣的帽子，和自己在海邊沙灘上散步的樣子。\n「這頂。」她突然開口，「就這一頂。」\n店主有些訝異地回過頭，像是沒有想到她會如此明確地表示自己的喜好。\n「好啊，確實是一頂好帽子，既然是你為我選的，我一定會好好珍惜的。」\n不知道是不是為了鼓勵達芙黛爾，這頂帽子如店主承諾的那樣，成為了她頭上的常駐裝飾，直到最後從她逐漸滑落的手中親手交給達芙黛爾，與她微笑著的頭顱一起。\n「真是一頂好帽子，我一定會好好珍惜的。」\n靡麗盛開的紫黑花朵，終於綻放在了新主人的頭顱上。"
  },
  Item_68688_Desc = {
    Text = "屬性為銀鑰充能等級的命輪。"
  },
  Item_68688_Name = {
    Text = "本源圖魯SR(臨時文本)"
  },
  Item_68688_StoryDesc = {
    Text = "本源圖魯SR(臨時文本)"
  },
  Item_68689_Desc = {
    Text = "屬性為銀鑰充能等級的命輪。"
  },
  Item_68689_Name = {
    Text = "催眠靈擺"
  },
  Item_68689_StoryDesc = {
    Text = "獲得新生後的克萊門汀就像一隻懵懂的幼蟲，穿行於人間，穿行於不屬於她種族的繁華世界，感到迷茫，感到困惑。\n直到那帶來啟迪般的聲音響起——\n「請問，你是夏洛蒂醫生嗎？我來找、找夏洛蒂醫生做心理諮詢……」\n克萊門汀終於回過神。她不在乎夏洛蒂是誰，只是好奇來者口中的新名詞：「心理諮詢」。\n但她是個成熟的獵手，絕不會暴露自己的無知，因此她笑了起來，彷彿她就是夏洛蒂，就是來者口中的救贖。\n淚水、折磨、無助，無需撩撥，來者就已經榨出了靈魂深處的痛苦。\n離開前，對方一臉輕鬆地看向克萊門汀，感慨：「謝謝你願意傾聽這些。我感覺自己好多了。」\n然後，就是關門聲，以及克萊門汀因初次品嘗到甘美而響起的笑聲。\n這笑聲起初些微，猶如幼蟲的嗡鳴，隨後越來越大，仿若成蟲的嘶叫。\n而於這笑聲裡，名為克萊門汀的蟲族，也迅速成熟。\n隨後的一切，順理成章。她成為了心理醫師，帶著笑容與靈擺，深入一個個患者的內心。\n她依舊行走於人間，依舊不屬於這個繁華的世界，但卻不再迷茫和困惑。\n因為整個人間和世界，都是她的催眠獵場。"
  },
