  Item_68846_Name = {
    Text = "溫柯爾·警覺"
  },
  Item_68846_StoryDesc = {
    Text = "第12期相位對弈"
  },
  Item_68847_Desc = {
    Text = "「想起來了！這裡應該這樣修！」"
