  Item_68849_EmojiName = {Text = "可憐"},
  Item_68849_Name = {
    Text = "奧瑞塔·可憐"
  },
  Item_68849_StoryDesc = {
    Text = "第12期學期課題"
  },
  Item_68850_Desc = {
    Text = "「系統故障，阿巴阿巴……」"
