  Item_68850_Name = {
    Text = "艾瑞卡·癡呆"
  },
  Item_68850_StoryDesc = {
    Text = "第13期相位對弈"
  },
  Item_68851_Desc = {
    Text = "「徹底瘋狂！」"
  },
  Item_68851_Name = {
    Text = "戈利亞·大吼"
  },
  Item_68851_StoryDesc = {
    Text = "第12期學期課題"
  },
  Item_68852_Desc = {
    Text = "「素汁？什麼是素汁，我沒有素汁。」"
  },
  Item_68852_EmojiName = {
