  },
  Item_68852_Name = {
    Text = "詹金·素質消失"
  },
  Item_68852_StoryDesc = {
    Text = "第13期學期課題"
  },
  Item_68853_Desc = {
    Text = "「人類真是複雜的生物……」"
  },
  Item_68853_EmojiName = {Text = "滄桑"},
  Item_68853_Name = {
    Text = "達芙黛爾·滄桑"
  },
  Item_68853_StoryDesc = {
    Text = "第12期相位對弈"
  },
  Item_68854_Desc = {
    Text = "「我是一條沒人愛的魚……」"
  },
  Item_68854_EmojiName = {Text = "牆角"},
  Item_68854_Name = {
    Text = "凱刻斯·牆角"
  },
  Item_68854_StoryDesc = {
    Text = "第13期相位對弈"
  },
  Item_68855_Desc = {
    Text = "「原來是這樣，您說的有道理，我會好好想一想的。」"
  },
  Item_68855_EmojiName = {Text = "確實"},
  Item_68855_Name = {
    Text = "奧爾拉·確實"
  },
  Item_68855_StoryDesc = {
    Text = "第13期學期課題"
  },
  Item_68856_Desc = {
    Text = "「哇，主人好厲害！」"
  },
  Item_68856_StoryDesc = {
    Text = "第13期相位對弈"
  },
  Item_68857_Desc = {
    Text = "「再見了媽媽今晚我就要遠航！」"
  },
  Item_68857_StoryDesc = {
    Text = "第13期學期課題"
  },
  Item_68858_Desc = {
    Text = "「主君，一起去騎馬嗎？」"
  },
  Item_68858_EmojiName = {Text = "開心"},
  Item_68858_Name = {
    Text = "奧吉爾·開心"
  },
  Item_68858_StoryDesc = {
    Text = "第12期相位對弈"
  },
  Item_68859_Desc = {
    Text = "「感謝你的來訪。」"
  },
  Item_68859_EmojiName = {Text = "謝幕"},
  Item_68859_Name = {
    Text = "索蕾爾·謝幕"
  },
  Item_68859_StoryDesc = {
    Text = "第12期學期課題"
  },
  Item_69844_Desc = {
    Text = "某位位高權重之人的葬禮上演奏的彌撒曲，安慰已故的靈魂，並祈求它們得到安息。\n在「與薔薇書」期間限時供應。"
  },
  Item_69844_Name = {
    Text = "受祝安魂彌撒"
  },
  Item_69845_Desc = {
    Text = "某位位高權重之人的葬禮上演奏的彌撒曲，她的榮光與銘旌永在。\n在「與薔薇書」期間限時供應。"
  },
  Item_69845_Name = {
    Text = "銘旌讚美彌撒"
  },
  Item_69846_Desc = {
    Text = "某位位高權重之人的葬禮上演奏的彌撒曲，表達了生者對亡者的哀悼和緬懷，同時堅信死亡不是終結，而是通往永生的開始。\n在「與薔薇書」期間限時供應。"
  },
  Item_69846_Name = {
    Text = "聖祭悼亡彌撒"
  },
  Item_69851_Desc = {
    Text = "在艾爾沃斯山頂新生的蒲公英的種子，從凍土中長出的小小野草散發著勃勃生機。\n在「雪山消融之時·復刻」期間限時供應。"
  },
  Item_69851_Name = {
    Text = "雪山蒲公英種子"
  },
  Item_69852_Desc = {
    Text = "在艾爾沃斯山頂新生的常青樹的種子，堅韌的樹苗終會越過風霜雨雪，長成參天的巨木。\n在「雪山消融之時·復刻」期間限時供應。"
  },
  Item_69852_Name = {
    Text = "雪山常青樹種子"
  },
  Item_69853_Desc = {
    Text = "在艾爾沃斯山頂新生的潔白花朵的種子，冰與雪作它的枝與葉，嚴寒也不能催折它的芬芳。\n在「雪山消融之時·復刻」期間限時供應。"
  },
  Item_69853_Name = {
    Text = "雪山銀霜花種子"
  },
  Item_69854_Desc = {
    Text = "需要念誦詩文才會開啟的神秘匣子。\n向它描述花的夢，它會贈你一束薔薇。\n在「在春天凋零以前」期間限時供應。"
  },
  Item_69854_Name = {
    Text = "花與詩的夢"
  },
  Item_69855_Desc = {
    Text = "需要念誦詩文才會開啟的神秘匣子。\n當你的意象恰到好處，它會讓你看到真實。\n在「在春天凋零以前」期間限時供應。"
  },
  Item_69855_Name = {
    Text = "意與詩的夢"
  },
  Item_69856_Desc = {
    Text = "需要念誦詩文才會開啟的神秘匣子。\n向它描述你的過去，它會贈你一抹回憶。\n在「在春天凋零以前」期間限時供應。"
  },
  Item_69856_Name = {
    Text = "心與詩的夢"
  },
  Item_69860_Desc = {
    Text = "明明不在人偶身上，卻會自己轉動的齒輪套組，會在靠近之時傳出絮語一般的輕微摩擦聲。"
  },
  Item_69860_Name = {
    Text = "雙螺旋人偶零件"
  },
  Item_69861_Desc = {
    Text = "解憂小店之中售賣的禮盒，比百貨商場中時新的貨品還要精緻，需要用貨真價實的頭顱交換。\n在「雨鎮幽影」期間限時供應。"
  },
  Item_69861_Name = {
    Text = "百貨魔女禮盒"
  },
  Item_69862_Desc = {
    Text = "解憂小店之中售賣的禮盒，能找到來自世界各地的罕有奇珍，需要用新鮮完整的頭顱交換。\n在「雨鎮幽影」期間限時供應。"
  },
  Item_69862_Name = {
    Text = "奇物魔女禮盒"
  },
  Item_69863_Desc = {
    Text = "解憂小店之中售賣的禮盒，是從店主私人倉庫中拿出的秘密珍藏，充滿了聞所未聞的神奇物品，需要用值得收藏的美麗頭顱交換。\n在「雨鎮幽影」期間限時供應。"
  },
  Item_69863_Name = {
    Text = "秘藏魔女禮盒"
  },
  Item_69867_Desc = {
    Text = "某位淑女送給你的下午茶會請柬，請來品嘗美味的甜點，與洋娃娃和小熊一起跳舞吧。\n在「群星正位」期間限時供應。"
  },
  Item_69867_Name = {
    Text = "淑女請柬贈禮"
  },
  Item_69868_Desc = {
    Text = "與某位淑女同款的洋裙，穿上後可以獲得淑女優雅高貴的氣質。\n在「群星正位」期間限時供應。"
  },
  Item_69868_Name = {
    Text = "淑女洋裙贈禮"
  },
  Item_69869_Desc = {
    Text = "與某位淑女同款的陽傘，撐開時可以獲得淑女永不低頭的自信。\n在「群星正位」期間限時供應。"
  },
  Item_69869_Name = {
    Text = "淑女陽傘贈禮"
  },
  Item_69870_Desc = {
    Text = "一份畫有著名商業航線的海圖，可以指引往來的商人順利抵港。\n在「於暴雨中搖曳」期間限時供應。"
  },
  Item_69870_Name = {
    Text = "金色航線的指引"
  },
  Item_69871_Desc = {
    Text = "克萊門汀心靈診所的特製藥方，可以抑制長期復發的心靈障礙。在「埋於記憶之下」期間限時供應。"
  },
  Item_69871_Name = {
    Text = "不定性瘋狂處方"
  },
  Item_69872_Desc = {
    Text = "克萊門汀心靈診所的特製藥方，可以拯救永久陷入瘋狂深淵之人。在「埋於記憶之下」期間限時供應。"
  },
  Item_69872_Name = {
    Text = "永久瘋狂處方"
  },
  Item_69873_Desc = {
    Text = "克萊門汀心靈診所的特製藥方，可以治癒暫時性的心理創傷。在「埋於記憶之下」期間限時供應。"
  },
  Item_69873_Name = {
    Text = "臨時瘋狂處方"
  },
  Item_69874_Desc = {
    Text = "深海氾濫的潮湧衝擊意識的邊界。\n用以抵抗異夢侵蝕的儀式，在「沉淵之祀」期間限時供應。"
  },
  Item_69874_Name = {
    Text = "潮蝕防衛密儀"
  },
  Item_69875_Desc = {
    Text = "那沉眠於至暗至深之處的王的誕生將扭曲整片神識之海。\n用以抵抗異夢侵蝕的儀式，在「沉淵之祀」期間限時供應。"
  },
  Item_69875_Name = {
    Text = "神國王誕密儀"
  },
  Item_69876_Desc = {
    Text = "異夢視界中的天災亦會通過精神共振干擾守密人的靈智。\n用以抵抗異夢侵蝕的儀式，在「沉淵之祀」期間限時供應。"
  },
  Item_69876_Name = {
    Text = "天災戒備密儀"
  },
  Item_69877_Desc = {
    Text = "一份畫有隱秘航線的海圖，順著航路可以找到得以休憩的小島。\n在「於暴雨中搖曳」期間限時供應。"
  },
  Item_69877_Name = {
    Text = "蒼海中的庇護所"
  },
  Item_69885_Desc = {
    Text = "精緻細密的人偶部件，閃爍著科技和瘋狂的光芒。"
  },
  Item_69885_Name = {
    Text = "精製人偶零件"
  },
  Item_69889_Desc = {
    Text = "被咒文密封的青銅盒子，其中裝有呈貢上的物資。已經經過基礎的除靈儀式，不會對開啟者造成任何危險。\n那裡太窮了，即使是最好的貢品也只有這種程度。——凱蒂古拉"
  },
  Item_69889_Name = {
    Text = "青銅呈供的「禮物」"
  },
  Item_69890_Desc = {
    Text = "散發著深淵氣息的巨匣，其上繚繞著深紅色霧氣。裡面裝有巨量的物資，但開啟時請務必通知專業人員進行協同。\n不用那麼緊張，我已經把上面的危險清除了，只是保留了這種視覺效果，這樣你才知道它來自何處。——凱蒂古拉"
  },
  Item_69890_Name = {
    Text = "猩紅深淵的「禮物」"
  },
  Item_69891_Desc = {
    Text = "閃爍著金色光輝的容器，能看到液態黃金在容器邊緣不息的流轉，裡面裝有昂貴的供物。\n說實話，我覺得這個盒子比裡面的東西值錢，但凡物對你起到的幫助有限，對吧？——凱蒂古拉"
  },
  Item_69891_Name = {
    Text = "黃金流轉的「禮物」"
  },
  Item_69892_Desc = {
    Text = "永遠不要質疑父神、《幾何原本》和醫生的處方。\n用以保證守密人身心健康的良方，在「多重療癒」期間限時供應。"
  },
  Item_69892_Name = {
    Text = "解離康復療程"
  },
  Item_69893_Desc = {
    Text = "一個療程沒效果怎麼辦？那就再來一個療程！\n用以保證守密人身心健康的良方，在「多重療癒」期間限時供應。"
  },
  Item_69893_Name = {
    Text = "解離鞏固療程"
  },
  Item_69894_Desc = {
    Text = "不小心人格分裂了怎麼辦？別慌，彌薩格早有準備！\n用以保證守密人身心健康的良方，在「多重療癒」期間限時供應。"
  },
  Item_69894_Name = {
    Text = "解離急性療程"
  },
  Item_69895_Desc = {
    Text = "一份畫有古老航線的海圖，據說標記之處藏有傳說中的秘寶。\n在「於暴雨中搖曳」期間限時供應。"
  },
  Item_69895_Name = {
    Text = "藏於深海的秘寶"
  },
  Item_69896_Desc = {
    Text = "葬骸城王邸的宴會餐品，由食屍鬼之王親制的主菜，每個食客的夢寐之求。\n在「死靈的美學」期間限時供應。"
  },
  Item_69896_Name = {
    Text = "祭靈節主菜"
  },
  Item_69897_Desc = {
    Text = "葬骸城王邸的宴會餐品，所有湯品都是精選食材熬製而成。\n在「死靈的美學」期間限時供應。"
  },
  Item_69897_Name = {
    Text = "祭靈節湯品"
  },
  Item_69898_Desc = {
    Text = "葬骸城王邸的宴會餐品，即使是開胃菜也是用心之作。\n在「死靈的美學」期間限時供應。"
  },
  Item_69898_Name = {
    Text = "祭靈節前菜"
  },
  Item_69899_Desc = {
    Text = "故事的開端，魔法的銀芯膠片不翼而飛。這是女孩和主人的懸疑故事。\n在「故事的魔法」期間限時供應。"
  },
  Item_69899_Name = {
    Text = "懸疑故事膠片"
  },
  Item_69900_Desc = {
    Text = "故事的間奏，滑稽的業餘演員閃亮登場，這是女孩和怪盜的喜劇故事。\n在「故事的魔法」期間限時供應。"
  },
  Item_69900_Name = {
    Text = "喜劇故事膠片"
  },
  Item_69901_Desc = {
    Text = "故事的結局，同伴的夕陽剪影載入畫冊，這是女孩和鯨魚的奇幻故事。\n在「故事的魔法」期間限時供應。"
  },
  Item_69901_Name = {
    Text = "奇幻故事膠片"
  },
  Item_69902_Desc = {
    Text = "不知如何腐蝕殘缺的人偶部件，貌似生銹的金屬傷口中卻流出黑色的膿血。"
  },
  Item_69902_Name = {
    Text = "銹蝕人偶零件"
  },
  Item_69985_Desc = {
    Text = "窮極的門扉開啟，帶來更加接近原初的力量——無人不畏懼祂，無人不向往祂。\n產自彌薩格地底黑池的神秘靈核，受到門扉之後力量的精煉，更加接近原初的本質，能幫助喚醒體提升至難以想像的高度。"
  },
  Item_69985_Name = {
    Text = "精粹原初靈核"
  },
  Item_69986_Desc = {
    Text = "散落於黑池中的碎片，在窮極門扉的照耀中，等待著來自原初的力量誕臨的時刻。\n產自彌薩格地底的神秘碎片，受到門扉之後力量的精煉，能合成精粹原初靈核。"
  },
  Item_69986_Name = {
    Text = "精粹靈核碎片"
  },
