  Item_70292_Desc = {
    Text = "在「超越星辰·限時預購」中可獲得。\n「當群星抵達正確的位置，偉大的@1降臨於世。」"
  },
  Item_70292_StoryDesc = {
    Text = "V2.0版本預購活動"
  },
  Item_70919_Desc = {
    Text = "記錄此鑰令後，可在編隊時選擇鑰令技能：「群星的庇佑」。\n\n他選擇了那頂王冠，那頂王冠亦選擇了他。\n新王與古神的靈魂一瞬間共鳴，遮天蔽日的虛影在他身後顯現，為國家帶來永恆的安寧。"
  },
  Item_70919_StoryDesc = {
    Text = "他選擇了那頂王冠，那頂王冠亦選擇了他。\n新王與古神的靈魂一瞬間共鳴，遮天蔽日的虛影在他身後顯現，為國家帶來永恆的安寧。"
  },
  Item_71281_Desc = {
    Text = "受苦難的靈魂啊，萬不可失去希望，仁愛的主教會為你向父神獻上禱告。\n在「靈魂的牧人·復刻」期間限時供應。"
  },
  Item_71281_Name = {
    Text = "彌撒中的祈禱"
  },
  Item_71282_Desc = {
    Text = "受苦難的靈魂啊，你將被嘉獎，仁愛的主教要代父神為你降下賜福。\n在「靈魂的牧人·復刻」期間限時供應。"
  },
  Item_71282_Name = {
    Text = "彌撒後的賜福"
  },
  Item_71283_Desc = {
