  Item_72089_Desc = {
    Text = "”橡果代表著一場冒險的開始，我們需要更多的橡果！“——伊格娜蒂丝。由伊格娜蒂丝的魔力凝結而成的橡果，用於在「回合奇賞」交換物資。"
  },
  Item_72089_StoryDesc = {
    Text = "逆轉回合聯動"
  },
  Item_72095_Desc = {
    Text = "紀錄此鑰令後、可在「相位對弈」編隊時選擇鑰令技能：「酒館之門」。\n\n當一個世界落幕、另一個世界的序章便已開啟。故事會隨著美酒一同不斷被人們傳頌、然而時間會為萬事萬物書寫答案。"
  },
  Item_72095_Name = {
    Text = "酒館之門"
  },
  Item_72095_StoryDesc = {
    Text = "當一個世界落幕，另一個世界的序章便已開啟。故事會隨著美酒一同不斷被人們傳頌，然而時間會為萬事萬物書寫答案。"
  },
  Item_72824_Desc = {
    Text = "位於赫普蘭德大陸的一間小酒館，其中有著能夠連接不同世界的傳送門。\n酒館的主人伊格娜蒂絲創造了名為萬象牌的卡牌遊戲，用來傳頌曾經英雄們的故事。"
  },
  Item_72824_Name = {
    Text = "逆轉回合：萬象牌"
  },
  Item_72824_StoryDesc = {
    Text = "逆轉回合聯動"
  },
  Item_72834_Desc = {
    Text = "有機會通過「無形者的禮券」獲得。\n「哎呀，有人想嘗一嘗我新泡的蜘蛛藥茶嗎？」"
  },
  Item_72834_Name = {
    Text = "以銀鑰之名：茜爾維婭"
  },
  Item_72834_StoryDesc = {
    Text = "外觀珍藏券專屬"
  },
  Item_72835_Desc = {
    Text = "在活動「織者自縛」中完成成就獲得。\n「啊呀，不要打斷我的編織哦，沒有什麼比這更重要了……」"
  },
