  },
  Item_72947_StoryDesc = {
    Text = "第22期相位對弈"
  },
  Item_72948_Desc = {
    Text = "「等你睡著，你的東西就會變成我的。」"
  },
  Item_72948_StoryDesc = {
    Text = "第21期相位對弈"
  },
  Item_72949_Desc = {
    Text = "有機會通過「無形者的禮券」獲得。\n「咳，我真沒喝多少，你不用叫拉蒙娜。」"
  },
  Item_72949_Name = {
    Text = "以銀鑰之名：德克斯特"
  },
  Item_72949_StoryDesc = {
    Text = "外觀珍藏券專屬"
  },
  Item_72950_Desc = {
    Text = "「我堂堂迷宮之神、偉大的蒼白之物，為什麼要寫作業……」"
  },
  Item_72950_StoryDesc = {
    Text = "第22期相位對弈"
  },
  Item_72951_Desc = {
    Text = "在活動「墜臨的萬千耀光」中完成成就獲得。\n「太陽底下，皆是灰燼！」"
  },
  Item_72951_Name = {
    Text = "以銀鑰之名：凱蒂古拉"
  },
  Item_72951_StoryDesc = {
    Text = "凱蒂古拉玩法活動"
  },
  Item_72952_Desc = {
    Text = "「噓，這是我們之間的小秘密。」"
  },
  Item_72952_EmojiName = {Text = "噓"},
  Item_72952_Name = {
    Text = "索蕾爾·噓"
  },
