  },
  Item_72954_Desc = {
    Text = "「我嗎？我來打？」"
  },
  Item_72954_Name = {
    Text = "智慧彌薩格：守密人·我？"
  },
  Item_72954_StoryDesc = {
    Text = "外觀珍藏券專屬"
  },
  Item_72955_Desc = {
    Text = "「在嗎？要一起打牌嗎？」"
  },
  Item_72955_EmojiName = {Text = "在嗎"},
  Item_72955_Name = {
    Text = "和平的一天：守密人·在嗎"
  },
  Item_72955_StoryDesc = {
    Text = "第18期相位對弈"
  },
  Item_73463_Desc = {
    Text = "珈倫烤的小魚喵？……唔？！這股味道……怎麼跟宛兒做的那麼像喵……"
  },
  Item_73463_Name = {
    Text = "凱希·盯"
  },
  Item_73463_StoryDesc = {
    Text = "逆轉回合聯動活動"
  },
  Item_73464_Desc = {
    Text = "嗚……相位對弈好難玩……比最難演奏的曲子還要難！莉雅姐姐，新手卡組求推薦……"
  },
  Item_73464_Name = {
    Text = "貝蒂·哭泣"
  },
  Item_73464_StoryDesc = {
    Text = "逆轉回合聯動活動"
  },
  Item_73465_Desc = {
    Text = "嘿嘿，輪到我出牌啦！果然不管是相位對弈還是萬象牌，最重要的靈魂，還是最後逆轉局面的這個回合呀！"
  },
  Item_73465_Name = {
    Text = "伊格娜蒂絲·到我咯"
  },
  Item_73465_StoryDesc = {
    Text = "逆轉回合聯動活動"
  },
  Item_73466_Desc = {
    Text = "為了來自異世界的友誼，以及萬象酒館的諸位，乾杯！"
  },
  Item_73466_EmojiName = {Text = "乾杯"},
  Item_73466_Name = {Text = "乾杯"},
  Item_73466_StoryDesc = {
    Text = "逆轉回合聯動活動"
  },
  Item_73467_Desc = {
    Text = "維度波動方程？銀芯提取原理？那是什麼東西？不好意思……光輝女神好像沒有教導過我這個。"
  },
  Item_73467_StoryDesc = {
    Text = "逆轉回合聯動活動"
  },
  Item_73468_Desc = {
    Text = "儘管相位連接有些時候……不太穩定，但毋庸置疑，這是一場精彩的對局！結束後加個好友點個贊如何？"
  },
  Item_73468_EmojiName = {
    Text = "打得不錯"
  },
  Item_73468_Name = {
    Text = "打得不錯"
  },
  Item_73468_StoryDesc = {
    Text = "逆轉回合聯動活動"
  },
  Item_73469_Desc = {
    Text = "這卡在相位對弈裡怎麼是這個效果！不服不服，再來一把！下把我一定贏！"
  },
  Item_73469_EmojiName = {Text = "不服氣"},
  Item_73469_Name = {
    Text = "亞維斯·不服氣"
  },
  Item_73469_StoryDesc = {
    Text = "逆轉回合聯動活動"
  },
  Item_73471_Desc = {
    Text = "汪！我怎麼又變成這樣了！完蛋了汪！！老闆娘不會放過我的啊啊啊！隻…隻要找到銀芯帽子的話……"
  },
  Item_73471_EmojiName = {Text = "震驚"},
  Item_73471_Name = {
    Text = "萊特·震驚"
  },
  Item_73471_StoryDesc = {
    Text = "逆轉回合聯動活動"
  },
  Item_73472_Desc = {
    Text = "原來這個指令裝置的運作原理是這樣的，真是新奇啊，弗莉達也一定會感興趣的吧"
  },
  Item_73472_EmojiName = {
    Text = "豁然開朗"
  },
  Item_73472_Name = {
    Text = "杜蘭·豁然開朗"
  },
  Item_73472_StoryDesc = {
    Text = "逆轉回合聯動活動"
  },
  Item_73473_Desc = {
    Text = "既然老闆娘都這麼說了……嘿嘿嘿！那就請卡牌大師……不對，那就請守密人多多指教啦！"
  },
  Item_73473_EmojiName = {
    Text = "誒我也要上嗎"
  },
  Item_73473_Name = {
    Text = "莉雅·誒我也要上嗎"
  },
  Item_73473_StoryDesc = {
    Text = "逆轉回合聯動活動"
  },
  Item_73582_Desc = {
    Text = "屬性為銀鑰充能等級的命輪。"
  },
  Item_73582_StoryDesc = {
    Text = "一束放置太久而枯萎乾涸的花。\n永遠等不來它的主人。"
  },
  Item_74093_Desc = {
    Text = "遙遠群星於閃爍時留下的破碎夢境。感知其中的靈性，便能窺見肉眼無法觀測的未來。"
  },
  Item_74093_Name = {
    Text = "碎裂餘夢"
  },
  Item_74143_Desc = {
    Text = "遙遠群星於閃爍時留下的完整夢境。那些亙古的靈性，昭示著命定的未來——群星即將正位。"
  },
  Item_74143_Name = {
    Text = "群星餘夢"
  },
  Item_74200_Desc = {
    Text = "逸散在灰燼霧都的情緒粒子，觸碰時彷彿能聽到誰絕望無助的咆哮。\n用於提升守密人在調查事件「重臨霧都」中的共鳴。"
  },
  Item_74200_Name = {
    Text = "絕滅之心"
  },
  Item_75778_Desc = {
    Text = "乾枯而蒼白的野獸頭骨，偶爾會發出磨牙一般的咯噠聲，也許是你的錯覺吧。\n貌似可以贏得那位店主的喜愛。\n\n至少掉落{s1}個"
  },
  Item_75778_Name = {
    Text = "蒼白野獸頭骨"
  },
