  Item_76215_Desc = {
    Text = "解鎖後，完成「降臨紀行」全部任務可額外獲得以下獎勵"
  },
  Item_76215_Name = {
    Text = "降臨紀行"
  },
  Item_76216_Desc = {
    Text = "解鎖後，完成「異世紀行」全部任務可額外獲得以下獎勵"
  },
  Item_76216_Name = {
    Text = "異世紀行"
  },
  Item_76294_Desc = {
    Text = "後勤部向完成「調查行動」的守密人發放了特別許可，在每次完成調查行動後，守密人都可以為下一次的出發購置一批特別的珍貴銀芯製品。\n數量有限，願銀鑰指引我們。"
  },
  Item_76294_Name = {
    Text = "調查歷程特典·星辰篇Ⅰ"
  },
  Item_77858_Desc = {
    Text = "那是古老意志的失落靈識。 彌薩格通過神秘的儀式啟發喚醒體的靈識，受到啟發的喚醒體將永久增強精神能力。\n重複獲得黑法老時轉換獲得，用於啟動黑法老的啟靈。"
  },
  Item_77858_Name = {
    Text = "殘片·黑法老"
  },
  Item_77858_StoryDesc = {
    Text = "重複獲得黑法老時轉換獲得，用於啟動黑法老的啟靈。"
  },
  Item_77859_Desc = {
    Text = "平時能夠穩定的提高護盾的獲取並在超維回合中爆發性獲取狂氣，當戰機來臨時能夠為隊伍提供大量暴擊傷害。"
  },
  Item_77859_StoryDesc = {
    Text = "時至今日，卡斯托爾也無法說出自由真正的釋義。\n他常常覺得自己是雙子之中更愚笨的那個，從少年時便木訥地跟隨在波呂克斯身後，聽弟弟說著一個又一個天馬行空的奇思妙想。\n在枯燥而麻木的修行生活中，他以為擁有那一抹輕鬆的亮色已經是最幸福的事，直到於麗埃特下令對波呂克斯進行定期的改造儀式。\n無盡的痛苦盡數傾瀉在波呂克斯一人的頭上，卡斯托爾茫然無措地陪在弟弟的身旁，看著那張飛揚的面龐上笑容越來越稀少，而自己想不到任何能做的事。\n「你知道自由是什麼意思嗎？」深夜之中，波呂克斯捧著那本早被二人翻爛的手抄本，靜靜地問卡斯托爾。\n卡斯托爾搖了搖頭。\n「那麼，你想去看看外面的世界嗎？哥哥。」\n卡斯托爾悚然怔愣，他似乎明白了波呂克斯想要追求的東西，那些他從未見過的、只存在於乾癟的文字中、存在於自己想像之外的東西。\n他為這樣大逆不道、驚世駭俗的想法所深深震撼，他沉默著，或許過了很久，或許只過了幾個呼吸，他便毫無恐懼地點了點頭。\n即便那要對抗整個教會，即便那要獻出自己的生命。\n於是，一雙鳥兒飛出了從未走出的牢籠，可惜他們從未想過，自由的代價會是如此不可承受之重。\n獵人的槍聲響過，鳥兒便從空中墜落。\n卡斯托爾才剛剛嘗到自由的味道，便眼睜睜看著弟弟那飛往自由的翅膀被生生地拔掉。\n面對於麗埃特恐怖的怒火，面龐蒼白而顫抖的弟弟背著人群，向自己露出了不曾屈服的笑。\n「堅持下去，為了自由。」\n卡斯托爾不停回想著波呂克斯那句無聲的口型，直到他在昏沉的折磨中將那兩個信仰般的字咀嚼成烙印後，他才再次與波呂克斯相逢。而這時他愕然發現，那始終在前方引領著自己的人，已經無情地將這兩個字拋下了。"
  },
  Item_77862_Name = {
    Text = "夏塔克鳥"
  },
  Item_77865_Desc = {
    Text = "那是古老意志的失落靈識。 彌薩格通過神秘的儀式啟發喚醒體的靈識，受到啟發的喚醒體將永久增強精神能力。\n重複獲得皮克曼時轉換獲得，用於啟動皮克曼的啟靈。"
  },
  Item_77865_Name = {
    Text = "殘片·皮克曼"
  },
  Item_77865_StoryDesc = {
    Text = "重複獲得皮克曼時轉換獲得，用於啟動皮克曼的啟靈。"
  },
  Item_77866_Name = {
    Text = "亞弗戈蒙"
  },
  Item_77867_Name = {Text = "禿鷲"},
  Item_77868_Desc = {
    Text = "那是古老意志的失落靈識。 彌薩格通過神秘的儀式啟發喚醒體的靈識，受到啟發的喚醒體將永久增強精神能力。\n重複獲得禿鷲時轉換獲得，用於啟動禿鷲的啟靈。"
  },
