  Item_77877_Name = {
    Text = "寫實主義悖謬"
  },
  Item_77877_StoryDesc = {
    Text = "他看見教堂的尖塔如同蠟燭般融化，滴落在神父潔白的羽翼上。彩繪玻璃上的聖徒像以極快的速度腐爛成骷髏、又在瞬間倒退成為嬰孩。尖銳與圓柔的幾何體從信徒的口中頌念出，堆滿整個大廳。\n他看見火車站的空間反復摺疊成非歐幾里得空間，遠處的站臺近在咫尺，近處的檢票口遙不可及。大廳的鐘表逆時針旋轉，枯骨般的人群如同被看不見的線條提著倒退行走，濃稠的紫羅蘭般的煙霧從雲端飄進火車的煙口。\n他看見森林裡的「空」凝成實體，樹木、岩石、藤蔓只是「空」的邊界勾勒出的半透明的輪廓線。天鵝的羽毛是不斷變換的馬賽克色塊，它們遊過的地方，湖水凝固成半透明的彩色玻璃。情侶依偎的長椅下， 鮮豔的橙黃色的影子正試圖啃噬主人的腳踝。\n他看見歌劇廳的音符如雨點般砸向觀眾席，他看見墓地微微起伏，就像一隻呼吸著的巨怪的皮表……\n他看見了很多，很多。他將他所看見的告訴他的母親、老師、朋友，他將他看見的繪入畫裡。他想把他眼中的世界帶到人們面前，可他身邊的人越來越少，一個世界離他越來越遠。\n但這是為什麼呢？他只是將他所見到的東西記錄了下來。皮克曼怎麼想也想不明白。\n悲傷的皮克曼站在鏡子面前。他看見一隻食屍鬼衝他咧開長滿尖牙的嘴。\n「沒有什麼比看見目睹真實更加重要。瘋狂，混沌，貪婪……要去看看嗎，皮克曼？」\n明悟的皮克曼向他微笑著，跨入那面鏡子。\n他只想親眼目睹那最為極致的瘋狂的真實，將它們忠實地描繪在他的畫布之上。\n他不是人類，也不是食屍鬼。\n他只是寫實主義繪者皮克曼。"
  },
  Item_77879_Name = {
    Text = "波呂克斯"
  },
  Item_77882_Desc = {
    Text = "狂氣爆發造成更多護盾的同時提高團隊暴擊傷害，在擁有更多觸腕的隊伍中擁有更亮眼的表現。"
  },
  Item_77882_Name = {
    Text = "聖火中的指引"
  },
  Item_77882_StoryDesc = {
    Text = "「我們用凡俗的銅與鐵，丈量星辰的軌跡，但無盡的深淵有自己的算法，陰晴不定。」\n逐漸沉沒的遊輪裡，克珀珊特吟誦起《領航員挽歌》。\n她早已知曉自己的命運，也早已選擇自己的命運，因此對面死亡，她沒有恐懼，只有平靜——平靜地燃燒，平靜地完成最後一次的領航。\n但焚燒的火光太過熾熱，她看不見前路，發不出聲音，也無法揮舞旗幟，這樣殘缺的指引下，船隻是否能夠正確航行？\n她不知道，並因此產生出恐懼與憂慮。\n這時《領航員挽歌》給出了指引：「年輕的領航員啊，你終將被鹹水擁入懷中，化為引路的磷火。」\n引路的磷火？克珀珊特沉默。她確實聽聞過在水手間流傳的聖艾爾摩之火的故事，然而區區凡人之軀，如何化為照亮人世的聖火？\n但即便希望渺茫，克珀珊特也在內心中不斷祈求：祈求自己能夠履行職責，完成最後的指引工作。\n除了克珀珊特自己，沒有人能夠聽到這祈求，但這已經足夠了——\n黑暗中，銀芯以融蝕漿為養料，迸發出強烈的光芒，實現了她最後的心願。\n「潮汐黑冊將記載你的名諱，令咆哮的怒濤為你奏響永恆的安魂曲。」\n她最終如《領航員挽歌》所言，死亡於大海。\n但她又超越了《領航員挽歌》。\n那是人類領航員面對大海時的狂妄與勸誡，而如今，她已成為聖艾爾摩之火，永恆指引船隻。"
  },
