    Text = "蘭提戈斯"
  },
  Item_77893_Desc = {
    Text = "能夠增幅持有者造成的護盾，並能夠週期性的伴隨觸發「追擊」效果提供大量傷害強效，伴隨觸發「維度穿梭」效果獲得大量狂氣。"
  },
  Item_77893_Name = {
    Text = "永世編織之網"
  },
  Item_77893_StoryDesc = {
    Text = "阿拉克涅知道，自己正在做一件注定失敗的事。\n她輕輕轉動著紡輪，日復一日將人類的悲歡、王朝的興衰、星火般的詩與愛，織入那張橫跨時空的巨網。\n她做得極好，精準、剋制、溫柔。摒棄那些「錯誤的」，選擇那些「正確的」。\n一代代人展露新生的笑顏，無數文明在灰燼中寫下嶄新的歷史。而那些因編織而生的喜悅，因編織而起的倦怠，連同所有柔軟的情緒，早在永世苦役的磨蝕中悄然凋亡。她親手割捨了脆弱，只留下清醒的意志，只為確保每一次選擇都出於責任，而非軟弱。\n可最深的悲劇，並非苦役本身，而是她清楚地知道，無論她如何修補、編織，世界仍會走向那片寂靜的虛無。文明如脆弱的沙堡，潮水終至。她的努力，是一場沒有觀眾的演出，一次永無迴響的守望。\n「命運早已將我們定罪於永恆的孤獨，憑什麼要接受這殘忍的懲罰？」\n「撕裂它、破壞它……你就能從這苦役中逃脫……」\n她垂眸，將那些多餘的想法輕輕剪斷，繼續枯燥而專注地編織著、維繫著、痛哭著、忍受著……\n一切無謂的掙扎、一切無解的命運早已織在這張網中。\n而網的中心，她看到了自己。"
  },
