  Item_77900_Name = {
    Text = "蜜果的謊言"
  },
  Item_77900_StoryDesc = {
    Text = "倫蒂尼恩最隱秘的暗巷角落，有一個眾所周知的故事，被人們口口相傳。\n它絕不會出現在太太們下午茶間抖動的羽毛扇或蕾絲扇下，也絕不會被紳士們在共進晚餐後，用絲質手帕擦拭嘴角時漫不經心地提起。\n只有念誦著最晦澀古老咒語的巫師、進行著最詭譎曲折任務的遊俠，才有一點點可能知道這個秘辛。\n哎？你問那為什麼會是眾所周知的？\n唉呀，這就是這整個故事的關鍵！參與過的、傳頌著這個故事的所有人，都是那麼的偉大、慈愛，祂們內心沒有哪怕一點點的私欲，如果真的有，那一定也是希望在這個世間艱難存活著的每一個人，都能真正地脫離苦難，歸於雪白的無垢淨土。\n這世間的一切，都源於一顆紅彤彤、香噴噴、任何人看到都想一口咬下的蘋果。\n它的汁液極其豐沛，只需一口就能填飽所有難平的飢渴。\n它的香氣無比濃郁，只要聞一聞就能驅散所有難言的苦楚。\n它以平常蘋果的外表，混在所有的蘋果中，記錄著所有的善和惡，因和果，所有提到蘋果的神話傳說，都是它曾經的豐功偉績。\n最要緊的是，因它是如此無私、平等，加入信奉它的教派不需要任何洗禮，牢記蘋果神教的教義之一，真正的神明是不會拘泥於形式的！\n當你第一次聽到蘋果神教的名字，當你腦中第一次出現一顆飽滿的、鮮紅的、令人垂涎欲滴的蘋果，只要你相信它，你就可以成為蘋果神教的一員。\n它不會與任何其他教派互斥，真正的神明歡迎每一個願意擁抱它的孩子，只要你心中有屬於蘋果神教的一角，在歸於永恆的安寧後，如果前序教義沒有生效，你發現自己無法進入那些教義中的福地，「最終你會發現，這是必然的，但蘋果神教愛你，它不會就這一點進行爭辯。」，蘋果天堂會毫無芥蒂地接納你，讓長久與它相伴的白雪仙女，接引你進入那充滿蘋果香味的，永恆的甜蜜歸宿。\n「現在，這一切福音正在被無償傳播，僅需一枚雷歐坊，就能獲得一個毫無拘束的後備計劃，和一枚有可能是蘋果神教中被供奉的蘋果，*世間的每一枚蘋果都有可能是那枚蘋果，由於白雪仙女正在代行其意志，會有更高機率獲得，總之，請多吃蘋果。」\n…………\n「天啊，我們只是短暫地因為過度唆使和欺騙克扣了卡拉布一週的用度而已！」\n「這就是她那個小腦子琢磨出來的新玩意兒？？？！」"
  },
  Item_77901_Desc = {
    Text = "那是古老意志的失落靈識。 彌薩格通過神秘的儀式啟發喚醒體的靈識，受到啟發的喚醒體將永久增強精神能力。\n重複獲得夏塔克鳥時轉換獲得，用於啟動夏塔克鳥的啟靈。"
