  Item_78761_Desc = {
    Text = "獲得喚醒體「本源沉睡之主」後解鎖"
  },
  Item_78774_Desc = {
    Text = "能夠大幅增加持有者造成的銀鑰能量、狂氣爆發造成的傷害與護盾。伴隨觸腕姿態的切換，能夠獲取大量狂氣並增幅敵方承受的傷害。"
  },
  Item_78774_StoryDesc = {
    Text = "風雨交加的夜晚，神明的女兒孤獨地坐在舷窗下。\n冰冷的月光照在襁褓上，流淌黑色黏液的聖嬰在其中安睡。\n神明的女兒唱起一支搖籃曲。\n「睡吧，睡吧，海的小寶貝。」\n「你的搖籃是黑色的月亮。」\n「把群星吞入夢鄉。」\n歌聲亦是禱詞，深海的魚群隨之彙聚。\n整艘航船宛如巨型的祭壇，恰似她誕下聖嬰的那天。\n剖開自己的胸膛，摘除淋漓的骨肉，以生命報償養育的恩情與種族的宿命。\n她的犧牲沒有換來渴求的自由，死亡不是永恆的安眠，只是悲劇的開始。\n自那之後，她的安寧只來自夜晚。\n「睡吧，睡吧，海的小寶貝。」\n當這支搖籃曲結束的時候，偉大的神國會刺破海面，從波濤洶湧的汪洋中升起。\n懷抱著這樣虛妄的幻想，墨菲也輕輕地合上了眼睛。"
  },
  Item_78775_Desc = {
    Text = "在活動「神誕的祭禮」中完成成就獲得。\n「噢？這就是你獻上的貢品？真是簡陋，就不擔心神母的責罰嗎？」"
  },
  Item_78775_Name = {
    Text = "以銀鑰之名：誕妄·墨菲"
  },
  Item_78775_StoryDesc = {
    Text = "誕妄·墨菲玩法活動"
  },
  Item_78871_Desc = {
    Text = "屬性為傷害強效的命輪。"
  },
  Item_78871_StoryDesc = {
    Text = "從誕生起，雙子就不被允許隨意使用翅膀飛翔，他們背上生長的第二雙手臂更像是兩對展示聖子威儀的禮器，被時時刻刻規定著應有的姿態。\n小時候，波呂克斯是兩人之中最為愛護那雙翅膀的，每日梳理、塗抹精油，將那些羽毛養護得綢緞一般閃閃發亮。\n他總是趁著短暫的無人時刻，偷偷地撲騰起那雙羽翼初豐的翅膀，在卡斯托爾的驚駭中搖搖晃晃地離地，去觸碰那些繪著雕飾的穹頂。\n比起波呂克斯能使雙翼做出種種舞蹈般的靈活姿勢，卡斯托爾常常覺得自己的翅膀笨拙如兩塊木板。雙子每天就寢後的秘密時光裡，卡斯托爾就這樣靜靜地注視著波呂克斯於黑暗中跳躍、旋轉，於狹小的籠中模仿飛翔。\n「弟弟的翅膀真好看，不過我的話，可能一輩子也學不會飛翔了。」卡斯托爾想。\n於是在後來他們出逃的那一夜中，卡斯托爾第一次感受到晚風托舉著雙翼的涼爽與輕鬆。更加熟練的波呂克斯緊緊抓著飛得歪歪扭扭的哥哥，在高空開懷地大笑，飛出一條條俯衝、旋轉的弧線，就像一隻真正的、屬於天空的飛鳥。\n卡斯托爾偏過頭，看月光鍍在波呂克斯那雙纖長而有力的翅膀上，在羽毛間反射出令人目眩的青綠色光暈。\n「那一定是世界上最美的東西，無論面對什麼，我一定要保護波呂克斯，保護住那雙翅膀。」\n很快，艱難的野外生活讓波呂克斯的翅膀被野獸所傷，卡斯托爾心疼地拾起波呂克斯掉落的飛羽，將它收在了懷裡，默默發誓不會讓這種事發生第二次。但他不知道的是，日後這片孤單的羽毛將變成他最珍貴的東西，變成他最後留住的、關於那雙翅膀的遺物。"
  },
  Item_78872_Desc = {
    Text = "屬性為銀鑰充能等級的命輪。"
  },
