  },
  Item_78884_Desc = {
    Text = "屬性為暴擊率的命輪。"
  },
  Item_78884_Name = {
    Text = "聖子尊容"
  },
  Item_78884_StoryDesc = {
    Text = "「聖子是持燈者注視之人，生而受到祂的眷顧。」\n「聖子應傳播祂的旨意，將光明賜予虔誠的義人。」\n「聖子需保持靈魂的潔淨。」\n「聖子應戒除俗欲、虔誠修行，全心侍奉光明。」\n「聖子不可多言、不可妄語。」\n「聖子應遠離罪孽、遠離有罪之人，不可被污濁的靈魂污染。」\n「聖子……」\n從他有記憶開始，一條又一條戒律就如鎖鏈般束縛著他，將他捧上尊崇的高臺，又令他不可失儀、不可低頭、不可放縱喜怒。\n他被披上寬大而華麗的衣袍，簇擁在無數侍從之中，按照要求扮演那個神聖的代表，俯視著虔誠的信徒匍匐跪倒、小心親吻他的衣角。\n聖子本應如此，無人在意那副高傲而不變的面容下，究竟有怎樣的情緒與喜好。\n正如他習慣了那高傲的笑容，在無人之時亦不知自己真正想擺出怎樣的表情。\n「波呂克斯聖子，您該前往賜福儀式了。」低垂頭顱的侍女恭敬地安排著他一成不變的生活。\n他轉過身，昂起頭，露出那同樣一成不變的笑容，如同親手戴上一張神聖的面具。\n那些迷茫、空虛和寂寞，都被遮蓋在面具之下，如同從未存在。"
  },
  Item_78885_Desc = {
    Text = "屬性為暴擊傷害的命輪。"
  },
  Item_78885_Name = {
    Text = "迫近的太陽"
  },
  Item_78885_StoryDesc = {
    Text = "太陽每秒散發出超過300秭焦耳的能量，它們中的數十億分之一會以光和熱的形式，行駛超過147億米的路程，從太空向地球襲來。\n這些能量滿足了地球上所有生物的需求，讓這複雜、龐大、混亂的三域中的所有物種可以順利地進行繁衍，進化。\n\n「這是世界的真理，任何情況都不會改變。」\n他不斷這麼告誡自己，以此維持精神的穩定。\n「可為什麼……這麼熱，這麼亮。」\n因為那147億米外之物，正緩緩佔據他的眼瞳。\n光和熱從他瞳孔中散出，灼燒著每一寸華貴的軀體。\n「我理解了，我理解了，我理解為何光會在8分20秒之後，才會來到地球。」\n「因為我們無法支付，直面光輝的代價。」\n當他接受一切時，他開始放聲大笑。\n「原來我比伊卡洛斯，更加接近太陽。」"
  },
