  Item_80189_Name = {
    Text = "超值禮包空包"
  },
  Item_80191_Desc = {
    Text = "記錄此鑰令後，可在編隊時選擇鑰令技能：「特殊治療」。\n\n她曾治癒無數患者，引導他們走向新生，如今的一切，也只是一場心理治療罷了。\n唯一特殊的是，患者是她自己。"
  },
  Item_80191_Name = {
    Text = "特殊治療"
  },
  Item_80191_StoryDesc = {
    Text = "她曾治癒無數患者，引導他們走向新生，如今的一切，也只是一場心理治療罷了。\n唯一特殊的是，患者是她自己。"
  },
  Item_80192_Desc = {
    Text = "逸散在心靈療養院中的情緒粒子，碰觸時彷彿能聽到誰瀕臨崩潰的呢喃。\n用於提升守密人在調查事件「蛻變」中的共鳴。"
  },
  Item_80192_Name = {
    Text = "認知之心"
  },
  Item_80285_Desc = {
    Text = "解鎖後，完成「療養紀行」全部任務可額外獲得以下獎勵"
  },
  Item_80285_Name = {
    Text = "療養紀行"
  },
  Item_81021_Desc = {
    Text = "珈倫特製的清掃工具，無論什麼東西都能絲滑地清理乾淨。"
  },
  Item_81021_Name = {
    Text = "清掃工具"
  },
  Item_81069_Desc = {
    Text = "後勤部向完成「調查行動」的守密人發放了特別許可，在每次完成調查行動後，守密人都可以為下一次的出發購置一批特別的珍貴銀芯製品。\n數量有限，願銀鑰指引我們。"
  },
  Item_81069_Name = {
    Text = "調查歷程特典·星辰篇Ⅱ"
  },
