  Item_81756_Desc = {
    Text = "記錄此鑰令後，可在編隊時選擇鑰令技能：「不滅的雷光」\n\n燃燒，燃燒，燃燒。\n哪怕骨血已沸騰，哪怕皮肉已焦糊，也要榨乾身體裡的最後一滴血液，綻放光明。\n因為這黑暗中，我是唯一的指引。"
  },
  Item_81756_Name = {
    Text = "不滅的雷光"
  },
  Item_81756_StoryDesc = {
    Text = "燃燒，燃燒，燃燒。\n哪怕骨血已沸騰，哪怕皮肉已焦糊，也要榨乾身體裡的最後一滴血液，綻放光明。\n因為這黑暗中，我是唯一的指引。"
  },
