  Item_88872_Name = {
    Text = "數理之書"
  },
  Item_88873_Desc = {
    Text = "記錄此鑰令後，可在編隊時選擇鑰令技能：「錯位命運」。\n他們總在錯誤的時間與一瞬的希望擦肩而過。\n曾經那只稚嫩的手牽引著他，一同奔向自由的光芒。\n當他拼命揮動翅膀，再一次突破命運的監牢，可為何那只熟悉的手，此刻卻穿透了他的胸膛？"
  },
