    Text = "數理之書"
  },
  Item_89573_Desc = {
    Text = "屬性為狂氣回充等級的命輪。"
  },
  Item_89573_Name = {
    Text = "重生於湮土"
  },
  Item_89573_StoryDesc = {
    Text = "你踏上了一片杳無人煙的荒原。\n人類活動的痕跡消亡已久，靈魂枯槁的生靈在灰燼與塵霾中艱難跋涉。\n這裡的存活不值得歆羨，無人知曉旅程的終點，只在無盡循環的光景中徘徊、徘徊、徘徊。\n直到他們的腳步滯澀，重重栽倒在地，仰望著天空伸出呼喚之手——\n\n願我的跋涉終結之後，\n以屍骨為沃土、為滋養、為源泉，孱弱的新芽重新破土。"
  },
  Item_89651_Desc = {
    Text = "探索過程中爆發性獲取狂氣的命輪。"
  },
  Item_89651_Name = {Text = "開學日"},
  Item_89651_StoryDesc = {
    Text = "這是你來到彌薩格的一年後。 你仍然記得你從那場大爆炸中醒來後，第一次踏入這所學校的那一天。你被髮放了合身而規整的校服，擁有了獨屬於自己的宿舍，第一次參觀餐廳並吃光了兩摞餐盤。 所有輕鬆的時刻在這一天戛然而止，轉眼你就因過於貧瘠的知識和嬰兒般光滑的腦回路，被勒令就讀為期一年的預科班。 語言學習，體能特訓，銀芯能力測試，特種生物常識補充……在飽受折磨之後，你的成績好壞參半，你那不及格的雷歐通用語成績和一次性連結了三個喚醒體的壯舉讓你在校園中名動一時。 幸運的是，出於你特殊的能力與卓絕的天賦，你還是迅速達到了一位調查員的能力標準，不必再繼續延長預科的時長。至於你那些參差不齊的短板，就由那些逐漸默契的夥伴們替你補習與兜底。啊，這裡雖然盛產魔鬼，那也是一群可靠溫柔的魔鬼。 這裡常常多雲、落雨、少有晴天，無數被遺忘的和將被遺忘的人們始終堅守、犧牲、不斷前進。 在這樣諸事如常的一天，彌薩格迎來了又一年的開學日。 你對著鏡子整理好校服的衣領，撫平每一絲褶皺，而後推開了宿舍樓的大門。 「哈欠，終於來了，我都快睡著了。」 「你是在宿舍裡學習抱窩嗎？新生。」 你衝蘿坦訕笑一聲，對著那個足以引起你生理恐懼的粉色身影縮了縮脖子，躲到了一旁笑著的拉蒙娜和奧吉爾身後，五道影子在清晨的校園裡搖晃著拉長。 「走吧，搭檔。」 「從今天起，你就正式成為彌薩格的一員了。」"
  },
  Item_89652_Desc = {
    Text = "釋放鑰令後提高裝備者臨時暴擊率的命輪。"
  },
  Item_89652_Name = {
    Text = "搭檔特訓"
  },
  Item_89652_StoryDesc = {
    Text = "哪怕沒有前面一截人生的記憶，從你並不發達的肌肉也可以看出，你之前一定不是什麼熱愛運動或暴力的那類人。\n你實在想不通彌薩格對調查員定下的戰鬥標準為何如此之高、如此全面。\n難道調查員的重點不在於調查兩個字，不在於智慧的頭腦、縝密的邏輯與一點恰如其分的好運嗎？\n每次被拉蒙娜從宿舍的被窩中準時拖起，站在空蕩蕩的操場上面對一輪又一輪的攻擊時，你就格外想念朵爾教授那充滿諷刺的邏輯學課程。即使是成山的作業和最令人脫髮的試卷，也比戰鬥訓練中一次次被毆打和跌倒的痛苦要溫柔太多。\n第19次，你被那柄封堵了所有行動路線的刺劍逼得失去了平衡，向後一屁股栽倒在地，感到渾身骨頭即將散架。\n氣喘吁吁中，你頹然抹去額頭的汗水，說什麼也不肯再起來了。\n拉蒙娜沒有任何意外的神色，她挽出一個漂亮的劍花收起了劍，鞋跟清脆地踏響著向你走來。你兩眼一閉，決心抱頭承受所有的指責與批評。\n意外的是，沒有任何敲打或謾罵到來，三秒之後你睜開眼睛，只有一張淡淡的笑臉湊在你的面前。\n拉蒙娜微微彎下腰，一隻被潔白手套包裹的手掌向你伸來。\n「其實你已經很努力了，我知道。但我們要面對的永遠是未知的恐懼與危險，哪怕是我，也會有顧及不到的意外時刻。」\n「就當是為了讓我放心一點，再來一次吧，搭檔。」"
  },
  Item_89842_Desc = {
    Text = "一枚不知何時出現的紙券，觸碰時眼前浮現出神秘的幻象。可用於在「幻衣訂購」兌換一期簡約幻衣。"
  },
  Item_89842_Name = {
    Text = "簡約幻衣繪形券（一期）"
  },
  Item_89873_Desc = {
    Text = "每日常規補助"
  },
  Item_89873_Name = {
    Text = "每日常規補助"
  },
  Item_89952_Desc = {
    Text = "安靜的房間裡，二十四名房客開始了她們的茶會。\n\n「不知道詹金今天過得怎麼樣？」\n溫吞的24擔憂地望著窗外。\n「這是慶祝我們逃出來的日子，我們說好了，在這一天，我們只有自己。高興一點，24們，這可是一個派對！」熱情的24揮舞著雙手。\n「或許我們可以考慮一個安靜且有深度的方式……」大概沒有人在聽學者24說的話。\n「你們要跳一支舞嗎？我可以為你們奏樂！」小丑24奏響了喇叭。\n「來吧，今天的茶會是為你們準備的。」主人格24拉著兩個人的雙手，帶她們來到舞池。她早已習慣了這間屋子女主人的身分。「我們的痛苦都承擔在你們的身上……忘記那些困擾你們的東西吧，至少在今天。」\n「喵~」在影子24的撫摸下，貓咪24期待地搖著尾巴。\n抑鬱的24和躁狂的24互相望了一眼。她們共同擔下了這間屋子裡所有的苦難與困惑。她們是朝夕相伴的摯友。她們是此生不渝的仇敵。她們攜起對方的手，來到了房間中央的空地。所有的不安與悲傷都平息下來，她們歡笑、糾纏，她們齊聲歌唱，跳躍、旋轉。血與淚打濕衣衫與地板，音樂和舞步，在同一個腦海中響起。\n\n安靜的房間裡，二十四名房客屏住呼吸。\n她們享受著這一刻的平靜，隻為她們自己。"
  },
  Item_89952_Name = {
    Text = "雙相和鳴"
  },
  Item_89953_Desc = {
    Text = "叮咚、叮咚。那是生鏽的八音盒在歌唱，歌唱一首變了調的天鵝挽歌。\n悲傷的人偶在八音盒中不停旋轉，飛旋的熱淚投入青綠色的火焰，凝成一滴滴晶瑩的寶石雨。\n\n無數扭曲的面孔從火焰中浮現，貪婪地吞食那些淚滴，又痛苦地抓撓她的裙擺。\n“跳！繼續跳！永遠都不要停下來！”\n“你憑什麼還能跳舞？你有什麼資格！謀殺者！殺人狂！”\n\n那是莉茲在每一個深夜都不斷輪迴的噩夢，無數靈魂在她環狀的視野中張大嘴巴，哀嚎又歌唱。而她的腳尖繃直、臂膀僵硬，身體固定成最標準的舞姿——隨著齒輪的轉動不停旋轉、旋轉。\n\n如果你於夢醒時分與她相見，不要詢問她為何不願再起舞，她已將所有愛、恨與淚水盡數拋灑於夢中的火焰。\n\n她將愛投入那火，於是她放下了畢生所愛之事。\n她將恨投入那火，於是她絕口不提那些醃臢與罪孽。\n她的愛與恨糾纏焚毀，共同將她的靈魂染上無窮的、青色的愁怨。"
  },
  Item_89954_Desc = {
    Text = "可愛的房間，精美的傢俱，絨絨的毯子，華麗的裙擺，端莊的禮儀。淑女墨菲被慷慨地賜予他人望塵莫及的地位和垂涎以求的珍寶，卻始終生活如行屍走肉。\n\n某個無人知曉的夜裡，她悄悄躲在廢棄的衣櫃中，被蹈海者的魚人們搖搖晃晃地抬出教會，棄置在一片荒無人煙的郊野中。\n\n她推開衣櫃，曠野星光燦爛。\n她躍過雜物的小山，在山腳拾到一枚小球。\n\n當戈利亞帶著驚惶的魚人小隊找到遺失的聖女時，她仍坐在距離衣櫃不遠的地方，將手中的小球高高拋起，等小球滾落，再一次高高拋起——\n戈利亞半句話也沒有詢問，就將聖女重新押回了名為供奉的牢籠。\n所以她所作所為的目的，始終不曾言說，直至將匕首刺入胸膛的時刻，也一直埋藏在心底。\n\n——她想將球拋上又大又圓的月亮。\n——那樣的話，它就不必再落下了。"
  },
  Item_89955_Desc = {
    Text = "創生之父自星空而下，以血孕育生靈，以骨刻撰規則。\n萬物本應以父神之規行舉，以父神之意生息。\n然，光陰荏苒，神言破碎，父神之規難以貫徹，父神之意難以落下。\n萬物悲苦，劫難叢生。\n\n蒼白之主啊，吾將重啟濟世的神言，帶領眾生消弭悲苦。\n吾將消去萬物之苦，萬物之罪，萬物之悲，直至吾骨血耗盡，魂歸於天。\n\n第一聲神言響起，肉體之慾將遭到超脫。 \n至此，色慾消亡。\n\n第二聲神言響起，生靈不再沉溺歡愉。 \n至此，暴食消亡。\n\n第三聲神言響起，貪慾之魔口舌喑啞。 \n至此，貪婪消亡。\n\n第四聲神言響起，世間再無消極度日者。\n至此，怠惰消亡。\n\n第五聲神言響起，世人不再行那無理無依之舉。\n至此，憤怒消亡。\n\n第六聲神言響起，再無枉死之癡迷者。\n至此，嫉妒消亡。\n\n第七聲神言響起，眾生將敬尊萬物。\n至此，傲慢消亡。\n\n吾以父神之骨，代行父神之權。\n願父神之光，照耀萬物。\n願濟世之言……永留世間……"
  },
  Item_89955_Name = {
    Text = "濟世神言"
  },
  Item_89964_Desc = {
    Text = "記錄此鑰令後，可在編隊時選擇鑰令技能：「腦中之音」。\n\n雙手交握的那一刻，你們從對方的眼裡看到了迷茫與困惑。\n殘缺的聲部在此交匯，皆因你們早已遺落了過往。\n沉默的樂章即將譜寫，皆因你們決心墜入未來。"
  },
  Item_89964_Name = {
    Text = "塵封舊憶"
  },
  Item_89964_StoryDesc = {
    Text = "雙手交握的那一刻，你們從對方的眼裡看到了迷茫與困惑。\n殘缺的聲部在此交匯，皆因你們早已遺落了過往。\n沉默的樂章即將譜寫，皆因你們決心墜入未來。"
