  },
  Item_91121_Desc = {
    Text = "有多少人欽佩於她當年的決斷與勇氣，就有多少人豔羨於那樣重生的幸運。\n活躍的大腦之下，是無數個可替換的、不畏刀槍、永不衰老的肉體。永生的誘惑如永恆的禁果與光明的燈燭，吸引著那些掌握了富貴與權勢的人們。\n曾有一位彌薩格也無法拒絕的大人物以極其豐厚的籌碼作為交換，希望朵爾為他進行同樣的大腦移植手術以及喚醒流程。\n朵爾沒有拒絕，甚至並未諷刺他的無知，只是從百忙的實驗之中抽出了短暫的會面時間，為那位大人物進行了細緻的檢查。而後平靜地宣佈了令他勃然大怒的結論——他的大腦不具備重生的條件。\n在彌薩格的百般調和下，重病將死的大人物簽署了一系列免責協議，堅持要賭一賭那絲渺茫的希望。\n朵爾親自為他實施了手術，可惜的是，希望從未存在。在朵爾說出否定的判詞時，那顆開發程度不足的大腦就不可能恢復原本的靈性。\n不過看在那些誠意十足的報酬的份上，朵爾還是貼心地完成了售後服務：那顆保持了活性的大腦被放入腦缸，而後被裝載了恰好匹配其性能的裝置系統。\n於是朵爾的實驗室中，漸漸地多了一些符合飛翔的真菌審美的小助手，那些能夠短暫飛翔的小東西揮舞著靈活的螯足，執行著最簡單的任務，為科學的研究與進步貢獻力量。\n「I03，取一份新的蒸餾水。」\n「I05，更換掉上週的培養基。」\n「I01，幫我泡一杯咖啡。」\n看來無知的大腦也並非百無一用嘛。在咖啡氤氳的熱氣裡，朵爾微笑著想。"
  },
  Item_91121_Name = {
    Text = "靈性重生"
  },
  Item_91157_Desc = {
    Text = "胸前的銀鑰匙忽然亮起，似乎在與這個宇宙之外的某處遙相呼應，你知道這是兩個靈魂共鳴的證明。"
  },
  Item_91157_Name = {
    Text = "銀鑰輝光"
  },
  Item_91237_Desc = {
    Text = "一枚不知何時出現的紙券，觸碰時眼前浮現出神秘的幻象。可用於在「幻衣訂購」兌換二期簡約幻衣。"
  },
  Item_91237_Name = {
    Text = "簡約幻衣繪形券（二期）"
  },
  Item_91353_Desc = {
    Text = "後勤部向完成「調查行動」的守密人發放了特別許可，在每次完成調查行動後，守密人都可以為下一次的出發購置一批特別的珍貴銀芯製品。\n數量有限，願銀鑰指引我們。"
  },
  Item_91353_Name = {
    Text = "調查歷程特典·星辰篇III"
  },
  Item_91354_Desc = {
    Text = "解鎖後，完成「亡城紀行」全部任務可額外獲得以下獎勵"
  },
  Item_91354_Name = {
    Text = "亡城紀行"
  },
  Item_91397_Desc = {
    Text = "「真相只有一個。」"
  },
  Item_91397_EmojiName = {Text = "偵探"},
  Item_91397_Name = {
    Text = "萊克·偵探"
  },
  Item_91397_StoryDesc = {
    Text = "第19期學期課題"
  },
  Item_91435_Desc = {
    Text = "「輕輕敲醒沉睡的心靈……」"
  },
  Item_91435_StoryDesc = {
    Text = "第19期相位對弈"
  },
  Item_91730_Desc = {
    Text = "彌薩格餐廳供應的日常肉類套餐之一，分量小巧、皮脆肉嫩，是絕對不會出錯的選擇。\n在「偉大的征服」期間限時供應。"
  },
  Item_91730_Name = {
    Text = "香料烤雞套餐"
  },
  Item_91731_Desc = {
    Text = "彌薩格餐廳偶爾供應的肉類套餐之一，選取新鮮羔羊肉低溫烤制，香氣撲鼻、汁水充盈，深受學生歡迎，很快就會被一搶而空。\n在「偉大的征服」期間限時供應。"
  },
  Item_91732_Desc = {
    Text = "彌薩格餐廳節日特供的肉類套餐，擁有豪華的分量、誘人的蜜汁焦褐色與油脂充盈的肉汁，最能烘托節日的氣氛，帶給人滿滿的幸福感。\n在「偉大的征服」期間限時供應。"
  },
  Item_91764_Desc = {
    Text = "獲得幻衣「淬血榮冠」後解鎖。\n「我來，我見，我殺戮。」"
  },
  Item_91764_Name = {
    Text = "尤烏哈希·淬血榮冠"
  },
  Item_91765_Desc = {
    Text = "無論經歷過多少歲月，他都不會忘記那個時代，那個屬於角鬥士的榮耀時代。\n「尤烏哈希……」\n起初，重金買下他的奴隸主還需要向人們宣佈他的名字，但在他殺光所有對手，徒手掏出敵人的內臟，吸乾他們的血液後，整個鬥獸場為他沸騰。\n「嗜血者」「魔鬼」「鬥獸場的暴君」……\n人們對他的稱呼不停變化，與此同時，他的對手也在不停變強。\n孩子、老人、女人、男人、甚至是老虎獅子，都成為過他的對手，也紛紛被他打敗\n他對於敗者的哀嚎不感興趣，也更加不可能記住「你在為什麼戰鬥」這種無聊的臨終話語。\n他只是不停重複著一件簡單的事情：殺戮。\n只要他還活著，還站在鬥獸場，他就是這裡的無冕之王。\n而這樣簡單的事情，為他帶來了一切。\n人們呼喚他的名字，掀起的聲浪足以震動羅馬最大的鬥獸場。但他嗤之以鼻。\n人們為他一擲千金，拋灑的金幣足以鋪平鬥獸場滿是砂礫與血的地面。但他不屑一顧。\n那些聲音、那些錢財、那些喜歡與崇拜，在他看來都是令人生厭的噁心東西，唯有溫熱的血是可碰觸的，唯有殺戮是真實的。\n因為他渴望的，永遠都是一件簡單的事情：\n我來，我見，我殺戮。"
  },
  Item_91765_Name = {
    Text = "淬血榮冠"
  },
  Item_91766_Desc = {
    Text = "黑暗而無盡的迷宮裡，終於又迎來了新人，這令總是暴躁不滿的蒼白之主久違地露出了笑容。 \n「選擇吧，是和我簽訂契約，然後成為我的子嗣。 還是餓死在迷宮裡，然後成為我的子嗣。」 \n誤闖入迷宮的新人瞪大了眼睛，表情在迷茫、困惑、恐懼中快速切換，然後拔腿就逃。就和無數「前輩」一樣。 \n「啊，竟然選擇了逃跑~ 哈哈，跑吧跑吧，用盡全力奔跑吧——反正你永遠也逃不出我的迷宮。」 \n之後，就是重複了千百次，但對阿格里帕而言仍舊充滿樂趣的過程：奔跑、力竭、跌倒，被黑暗與恐懼籠罩的人求救、喊叫、絕望，最後從精神到肉體，都被徹底擊碎。 \n當這些可憐人類的大腦被絕望攪拌為漿糊時，就是她這個迷宮之主出場的時刻。無需她多言，可憐可悲的人就向她伸出了求救的手。 \n「救救我……無論是誰都好，救救我……」 \n阿格里帕憐憫又殘忍地望著對方，微笑。 \n「我當然會救你。就像你的前輩們一樣……成為我的子嗣吧。」 \n「是的，只要簽訂契約，所有掙扎和痛苦就結束了。」 \n失去理智、可憐可悲的人本能地點點頭，於是在黑暗而無盡的迷宮裡，蒼白之主再次露出了笑容。 \n契約已經完成，接下來要做的就是等待——等待子嗣的成長與誕育。"
  },
  Item_91766_Name = {
    Text = "蒼白契約"
  },
  Item_91767_Desc = {
    Text = "獲得幻衣「蒼白契約」後解鎖。\n「簽訂契約，然後成為我的子嗣~」"
  },
  Item_91767_Name = {
    Text = "阿格里帕·蒼白契約"
  },
  Item_94417_Desc = {
    Text = "無論經歷過多少歲月，他都不會忘記那個時代，那個屬於角鬥士的榮耀時代。\n「尤烏哈希……」\n起初，重金買下他的奴隸主還需要向人們宣佈他的名字，但在他殺光所有對手，徒手掏出敵人的內臟，吸乾他們的血液後，整個鬥獸場為他沸騰。\n「嗜血者」「魔鬼」「鬥獸場的暴君」……\n人們對他的稱呼不停變化，與此同時，他的對手也在不停變強。\n孩子、老人、女人、男人、甚至是老虎獅子，都成為過他的對手，也紛紛被他打敗\n他對於敗者的哀嚎不感興趣，也更加不可能記住「你在為什麼戰鬥」這種無聊的臨終話語。\n他只是不停重複著一件簡單的事情：殺戮。\n只要他還活著，還站在鬥獸場，他就是這裡的無冕之王。\n而這樣簡單的事情，為他帶來了一切。\n人們呼喚他的名字，掀起的聲浪足以震動羅馬最大的鬥獸場。但他嗤之以鼻。\n人們為他一擲千金，拋灑的金幣足以鋪平鬥獸場滿是砂礫與血的地面。但他不屑一顧。\n那些聲音、那些錢財、那些喜歡與崇拜，在他看來都是令人生厭的噁心東西，唯有溫熱的血是可碰觸的，唯有殺戮是真實的。\n因為他渴望的，永遠都是一件簡單的事情：\n我來，我見，我殺戮。"
  },
  Item_94417_Name = {
    Text = "淬血榮冠"
  },
  Item_94418_Desc = {
    Text = "黑暗而無盡的迷宮裡，終於又迎來了新人，這令總是暴躁不滿的蒼白之主久違地露出了笑容。 \n「選擇吧，是和我簽訂契約，然後成為我的子嗣。 還是餓死在迷宮裡，然後成為我的子嗣。」 \n誤闖入迷宮的新人瞪大了眼睛，表情在迷茫、困惑、恐懼中快速切換，然後拔腿就逃。就和無數「前輩」一樣。 \n「啊，竟然選擇了逃跑~ 哈哈，跑吧跑吧，用盡全力奔跑吧——反正你永遠也逃不出我的迷宮。」 \n之後，就是重複了千百次，但對阿格里帕而言仍舊充滿樂趣的過程：奔跑、力竭、跌倒，被黑暗與恐懼籠罩的人求救、喊叫、絕望，最後從精神到肉體，都被徹底擊碎。 \n當這些可憐人類的大腦被絕望攪拌為漿糊時，就是她這個迷宮之主出場的時刻。無需她多言，可憐可悲的人就向她伸出了求救的手。 \n「救救我……無論是誰都好，救救我……」 \n阿格里帕憐憫又殘忍地望著對方，微笑。 \n「我當然會救你。就像你的前輩們一樣……成為我的子嗣吧。」 \n「是的，只要簽訂契約，所有掙扎和痛苦就結束了。」 \n失去理智、可憐可悲的人本能地點點頭，於是在黑暗而無盡的迷宮裡，蒼白之主再次露出了笑容。 \n契約已經完成，接下來要做的就是等待——等待子嗣的成長與誕育。"
  },
  Item_94418_Name = {
    Text = "蒼白契約"
  },
  Item_94440_Desc = {
    Text = "獲得喚醒體「茉夏」後解鎖"
  },
  Item_94441_Desc = {
    Text = "那是古老意志的失落靈識。 彌薩格通過神秘的儀式啟發喚醒體的靈識，受到啟發的喚醒體將永久增強精神能力。\n重複獲得茉夏時轉換獲得，用於啟動茉夏的啟靈。"
  },
  Item_94441_Name = {
    Text = "殘片·茉夏"
  },
  Item_94441_StoryDesc = {
    Text = "重複獲得茉夏時轉換獲得，用於啟動茉夏的啟靈。"
  },
  Item_94442_Desc = {
    Text = "獲得喚醒體「本源奧吉爾」後解鎖"
  },
  Item_94442_Name = {
    Text = "本源奧吉爾"
  },
  Item_94443_Desc = {
    Text = "屬性為死亡抵抗的命輪。"
  },
  Item_94443_Name = {
    Text = "理智明燈"
  },
  Item_94443_StoryDesc = {
    Text = "「以理智為明燈，就能驅散人生的迷霧。」\n曾幾何時，茉夏曾經聽過這樣的話。\n或許是某次梭羅公司的技術人員在調試驅霧燈時脫口而出的感慨？又或許是某次去菲林根餐廳時某個路人的調侃？\n茉夏已經忘記了，她能夠清晰想起的，就是聽到這句話時，自己臉上的慣用社交微笑，和藏在這笑容之後的嘲諷。\n「明燈？哈，什麼老掉牙的古董，現在人們都用手電筒。」\n她並非不知道這只是一種比喻，她只是不屑於理解。\n因為總有一天，她會死亡。而死亡之後，什麼理智，什麼迷霧，都不存在了——她會徹底從這個世界解脫。\n這是合理且必然的推測。她需要做的，只是享受這個「必然」到來前的過程。\n但從沒有人告訴過她，「必然」也會遭遇「意外」。\n相似的迷霧，相似的困境，可這裡沒有驅霧燈，沒有調查團，沒有任何她熟悉的東西。她的斧子能夠斬斷世間的怪物，卻斬不斷自身的孤獨與困惑化為的迷霧。\n她可以回去嗎？她會回去嗎？到底什麼時候可以回去……\n一個又一個問題自她的內心浮起，像是無形的深水，慢慢吞噬她的心靈。此時此刻，她心中唯一的，全部的想法，就是——\n保持理智。\n不要發瘋！不要發瘋！不要發瘋！\n無論是面對那個世界的迷霧，這個世界的迷霧，還是自己內心的迷霧。\n為了，再次回去。"
  },
  Item_94445_Desc = {
    Text = "那是古老意志的失落靈識。 彌薩格通過神秘的儀式啟發喚醒體的靈識，受到啟發的喚醒體將永久增強精神能力。\n重複獲得本源奧吉爾時轉換獲得，用於啟動本源奧吉爾的啟靈。"
  },
  Item_94445_Name = {
    Text = "殘片·本源奧吉爾"
  },
  Item_94445_StoryDesc = {
    Text = "重複獲得本源奧吉爾時轉換獲得，用於啟動本源奧吉爾的啟靈。"
  },
  Item_94446_Name = {
    Text = "負誓·奧吉爾"
  },
  Item_94447_Desc = {
    Text = "屬性為暴擊率的命輪。"
  },
  Item_94447_Name = {
    Text = "往日如影隨形"
  },
  Item_94447_StoryDesc = {
    Text = "不知名的瘟疫吞噬了城鎮與村莊，嗜戰的人們在動盪中盡情殺戮，鐵與血的交響沸騰癲狂。\n出於恐懼，或利用恐懼。\n恐懼是無形的敵人，古老的敵人，致命的敵人。\n他是一個不合格的騎士，他敗給了恐懼。\n\n然而曾鄭重許下的誓言仍然迴蕩耳畔，一年又一日，穿過早已虛無的故鄉。\n「我將仁慈地對待弱者，我將勇敢地面對強敵。」\n黑夜藏匿了行兇者的腳印，尖叫和哭泣的洪流淹沒街巷，人群如同驚慌失措的羊群。\n「我將毫無保留地對抗惡人，我將為不能戰鬥者而戰。」\n槍尖染血，銀盾鏽蝕，影子饜足地微笑，群鴉盤旋頂空，瞳仁中有魔鬼的閃光。\n「我將幫助那些需要我幫助的人。」\n「是他，他來了。」人們低聲囁嚅，恐懼扭曲了他們的臉龐，「空心的怪物，復仇的鬼魂，自死亡的深潭歸來，要將他的敵人拖入怨恨的黑沼。」\n是他。他並未忘記，他從未忘記。\n\n為何要堅持？倘若萬物終將消亡，哪怕是榮耀與信仰。\n為何要退縮？既然無論命運如何嘲弄，人都唯有屈膝順從。\n難道只為忠於忠誠，獻於奉獻？\n公國最後的騎士徒勞發問，靈魂同殘軀一樣荒蕪，恐懼的餘污肆意流淌，匯聚成毀滅的汪洋。\n可空蕩蕩的胸腔依舊緘默不語，失落的答案還不知去向。"
  },
  Item_94448_Desc = {
    Text = "能夠提高裝備者「狂氣爆發」和「追擊」造成的基礎傷害，並伴隨打擊卡的使用，持續提高裝備者打擊造成的傷害。"
  },
  Item_94448_Name = {
    Text = "狂戮至世界盡頭"
  },
  Item_94448_StoryDesc = {
    Text = "「當一個世界走向末日時，會發生怎樣的樂子？」\n茉夏不知道，但她期待著。\n這種期待和之前都不同，這次可不是什麼打幾個古物的小樂子，是以一個世界為衡量尺度的研究和調查。而這研究與調查中，最重要也最核心的，是一個人——\n彌薩格守密人。\n「我會拯救這個世界……」\n「這個世界，一定不會走向崩毀的命運……」\n那個心懷理想，身負一個世界興亡的人這樣做出承諾。作為回應，茉夏知道自己應該露出感動的表情，這是人類社會約定俗成的社交禮儀。\n但她不想再偽裝了，或者說，在觀看過守密人直面@4，以自身為代價拯救一個世界後，她覺得沒有必要對經歷過宇宙恐怖的人做出偽裝。\n「偽裝」是人類社會的遊戲規則，體面卻無聊，而宇宙……宇宙真實且直白——\n要麼生存，要麼毀滅。\n所以，她對守密人的回答也真實且直白。\n「我不在乎這個世界是否會得到拯救，或者毀滅……比起這些，我更好奇你。」\n我好奇你是否能夠踐行理想，還是會摧折在追求理想的道路中。\n也好奇這個世界是會回應你的願望，還是不可避免的走向毀滅。\n無論是哪一種，都會是盛大且不可多得的樂子。\n我會始終期待著那一天……\n用我的眼睛，我的斧頭，等待著。"
  },
  Item_94449_Desc = {
    Text = "能夠增幅裝備者「狂氣爆發」造成的護盾和力量，在使用「防禦」時提供更多護盾和力量。"
  },
  Item_94449_Name = {
    Text = "而雛菊仍然盛開"
  },
  Item_94449_StoryDesc = {
    Text = "「把花環戴好，這就是你的授勛禮了，親愛的小騎士。」\n雛菊開遍原野時，總有怠惰的兵士借著護衛的名頭，拉著少年在此遊蕩。\n亞奎丹公國最常見的花編做的飾品，被輕輕地放在金色的髮上。\n「閣下，也許……我們該訓練了？」\n少年這樣說著，卻乖巧地將潔白的花環戴正。\n這小巧的植物，總是沐浴於光明之中，在少年的國度，亦是希望的象徵。\n\n再度睜開雙眼時，那些明麗的畫面已不復存在。\n戰馬在嘶鳴，敵人不屑地一擁而上，在千軍萬馬中，他只有孤身一人。\n然後，刺耳的喧嘩聲戛然而止——\n黑色的潮水湧入他的靈魂。\n隨之響起的是長槍貫穿皮肉的撕裂聲，鮮血的湧動聲，敵人的哀嚎聲。\n那些面孔上的輕蔑蕩然無存，取而代之的是鋪天蓋地的畏懼與退縮。\n而少年只是機械地抬手，刺穿，拔出，再舉起。\n直到最後一名士兵倒下。\n煙塵隱沒了無數面孔，征伐者與被征伐者的殘骸堆積在地，再無分別。\n\n影子纏上他的脊背，嗤笑著：「繼續呀。落下你的槍，再多一次。」\n「守護者與毀滅者之間，本就只有一線之隔。如今，你已做出了選擇。」\n\n黑暗遮蔽了天空，血浸透了大地。\n他看向遠方的郊野——只是短短一夜，那裡便永遠失去了往日的色彩。\n風吹起少年的衣角，也掠過那片僥倖存留的草地。\n在無聲的夜色中，在惡魔也不知道的角落裡，一抹難察的純白仍留在他的眼底。\n那是這個國度的最後一朵雛菊，在無人在意之地默默生長。\n儘管沾染了赤色，花莖彎折，卻仍未倒下。"
  },
  Item_94559_Desc = {
    Text = "記錄此鑰令後，可在編隊時選擇鑰令技能：「獵食決心」。\n\n這裡是彌薩格曾允諾戰士們的應許之地，那罐子中儲著蜜，那櫃子中藏著肉。\n沒有什麼能阻擋勇敢的戰士，他們終將拿回自己應得之物。"
  },
  Item_94559_Name = {
    Text = "獵食決心"
  },
  Item_94559_StoryDesc = {
    Text = "這裡是彌薩格曾允諾戰士們的應許之地，那罐子中儲著蜜，那櫃子中藏著肉。\n沒有什麼能阻擋勇敢的戰士，他們終將拿回自己應得之物。"
  },
