  },
  Item_9528_Name = {Text = "鎖頭"},
  Item_9529_Desc = {
    Text = "提高持有者造成的護盾與治療效果，並增強持有者反擊獲取能力的命輪。"
  },
  Item_9529_Name = {
    Text = "傷痛之鰭"
  },
  Item_9529_StoryDesc = {
    Text = "（以下回答節選自克萊門汀的診療手冊，僅供參考）\n\n1. 凱刻斯。\n2. 16，17……？天知道。\n人死了以後還會管這些沒用的幹嘛？\n3. 一個破漁村，你不可能在任何地圖上查到它的名字。\n4. 我不想說。\n5. 怪胎。醜八怪。蠢豬。傻@1……這些比較常見。\n6. 閃閃發光的黃金鯰魚臉，簡稱鯰魚臉。\n7. 下雨天。\n8. 我不知道。下雨的時候，我會在沙灘上走來走去……\n有幾年了吧，就看看遠方，不幹別的。\n9. 我說了我#¥%不知道@1滾！！\n-------\n14. 唔……或許是奧恩叔叔曾告訴我，他會在下雨的時候，駕駛一艘大帆船來接我「回家」……\n15. 是的，他履行了自己的諾言……\n我在海底漂了好幾天，又渴又餓，全身都在痛……\n然後我看見奧恩叔叔和他的白色大帆船。\n他整個人，哦不，準確來說，是他的骨頭掛在帆船的桅杆上——他也蛻變失敗了。\n然後我用盡最後的力氣漂了過去，坐在桅杆上陪著他。\n16. 我們說好要一起回家的。"
  },
  Item_9530_Desc = {
    Text = "提高持有者生命回復能力，釋放狂氣爆發能夠獲取一定的延遲治療。"
  },
  Item_9530_StoryDesc = {
    Text = "卡修利亞民間流傳著沉沒文明的傳說。\n\n相傳遠在歷史記錄前，星辰的異常移位使一個史前文明沉入了海底，而卡修利亞人就是那個文明的後裔。\n除了經商、漁業外，卡修利亞人出海的一大目的就是尋找失落的先祖文明。\n他們相信，在特定星位下出生的女孩會與先祖文明有感應，她們能指引沉沒文明的方位，也能從風浪中庇佑船隊。\n\n希萊斯特就是這樣被選中的。\n她被捆縛在高懸白帆的桅杆上，看著下方的人類忙忙碌碌。\n她既不關心，也不好奇。\n\n希萊斯特能從海風、海鳥的動向中感知海上的天氣，偶爾也能探知來自遙遠沉睡之地的氣息。\n她天生就是屬於大海，屬於航船的吧——希萊斯特時常這麼想，被禁錮的事實似乎在她的心裡沒有起任何波瀾。\n有時候她會離開桅杆，追尋海空中飛翔的白鳥，那時行船就會緊緊地追著她不放。\n人們相信少女是航行順利的象徵，受祝福的船只能夠平安返航，帶來鉅額的財富與先進的文明。\n而她對此一無所知。"
  },
  Item_9531_Desc = {
    Text = "屬性為暴擊傷害的命輪。"
  },
