  Item_95517_Desc = {
    Text = "記載了這個宇宙中無數命運縮影的神秘古籍。\n可從中免費獲得1個「忘卻篇」中的隨機限定命輪。"
  },
  Item_95517_Name = {
    Text = "宿命定格·忘卻篇"
  },
  Item_95518_Desc = {
    Text = "記載了書寫於血肉皮膚的密語的神秘古籍。\n可從中選擇1個「忘卻篇」中的「血肉」界域中的限定命輪免費獲得。"
  },
  Item_95518_Name = {
    Text = "血肉密語·忘卻篇"
  },
  Item_95519_Desc = {
    Text = "於你熟悉的世界中，定向到深海界域進行喚醒的原質捕獲技術。 \n可從中選擇1個「忘卻篇」中的「深海」界域限定喚醒體免費喚醒。"
  },
  Item_95519_Name = {
    Text = "深海迷影·忘卻篇"
  },
  Item_9551_Desc = {
    Text = "翅膀只負責提供美麗，價值五片什。\n閃耀的水晶蝴蝶。身體大部分已被結晶化。\n用於提升混沌界域喚醒體的技能等級。"
  },
  Item_9551_Name = {
    Text = "閃耀晶蝶"
  },
  Item_9552_Desc = {
    Text = "主屬性從暴擊率、暴擊傷害、銀鑰充能等級和狂氣回充等級中隨機獲得1個。"
  },
  Item_9552_Name = {
    Text = "標準密契SSR"
  },
  Item_9553_Desc = {
    Text = "用於呼喚「環行・拉蒙娜」回頭的道具，使用後可解鎖「拉蒙娜」的本源形態。\n\n你不會成為她新的夢魘，只因你不會離她而去。"
  },
  Item_9553_Name = {
    Text = "遺失的振響"
  },
  Item_95548_Desc = {
    Text = "記錄此鑰令後，可在編隊時選擇鑰令技能：「不落的太陽」。\n\n即使虛假的黑日已遮蔽天空，真正的太陽也永遠不會熄滅。\n此刻短暫的日落，是為了迸發出更加熾熱的烈陽。\n現在，燃燒著琥珀色火焰的太陽二度升起，再也不會落下了。"
  },
  Item_95548_Name = {
    Text = "不落的太陽"
  },
  Item_95548_StoryDesc = {
    Text = "即使虛假的黑日已遮蔽天空，真正的太陽也永遠不會熄滅。\n此刻短暫的日落，是為了迸發出更加熾熱的烈陽。\n現在，燃燒著琥珀色火焰的太陽二度升起，再也不會落下了。"
  },
  Item_9554_Desc = {
    Text = "主屬性從界域精通、狂氣回充等級、黑印掉落和銀鑰充能中隨機獲得1個。"
  },
  Item_9554_Name = {
    Text = "猩紅之悸Ⅳ"
  },
  Item_9554_StoryDesc = {
    Text = "傳說中最初的魔像創造者，以血液滋養魔像。"
  },
  Item_9555_Desc = {
    Text = "是的，萬物皆可淬製。你的本能、你的理智，甚至你的心……到頭來你會發現，你和他們其實也沒什麼不同。\n用以升格深海界域喚醒體的材料。"
  },
  Item_9555_Name = {
    Text = "淬製心靈"
  },
  Item_9556_Desc = {
    Text = "經驗達到一定值時，守密人等級提升。可在調查關卡、幕間演習等玩法中消耗靈啡肽獲得。"
  },
  Item_9556_Name = {Text = "經驗"},
  Item_9557_Desc = {
    Text = "那是古老意志的失落靈識。 彌薩格通過神秘的儀式啟發喚醒體的靈識，受到啟發的喚醒體將永久增強精神能力。\n重複獲得阿格里帕時轉換獲得，用於啟動阿格里帕的啟靈。"
  },
  Item_9557_Name = {
    Text = "殘片·阿格里帕"
  },
  Item_9557_StoryDesc = {
    Text = "重複獲得阿格里帕時轉換獲得，用於啟動阿格里帕的啟靈。"
  },
  Item_9558_Desc = {
    Text = "逸散在無垠海中的情緒粒子，觸碰時彷彿聽見了「交給我」的訣語。\n用於提升守密人在調查事件「倒錯的群星」中的共鳴。\n可在「倒錯的群星」關卡首通獎勵中獲取。"
  },
  Item_95592_Desc = {
    Text = "裝滿了大量珍稀凝晶的盒子，不知道消耗了研究員的多少頭髮，無序的細胞充滿了混亂、以及富有的美，可以使喚醒體迅速精進自己的力量。\n在「死靈的美學」期間限時供應。"
  },
  Item_95592_Name = {
    Text = "擬態支援匣"
  },
  Item_95593_Desc = {
    Text = "所有力量的奧秘凝聚在這些紅色的晶石之中，打開這個匣子的那一刻，你能感受到彌薩格對你傾注的信任與決心，校方相信傾盡全部的資源一定能培養出一位優秀的守密人。\n在「死靈的美學」期間限時供應。"
  },
  Item_95593_Name = {
    Text = "賢石支援匣"
  },
  Item_95594_Desc = {
    Text = "彌薩格為格外上進的調查員準備的訓練支援物資，配合大量的艱苦練習，可以快速磨練出一支強大的喚醒體隊伍。\n在「死靈的美學」期間限時供應。"
  },
  Item_95594_Name = {
    Text = "特訓支援匣"
  },
  Item_9559_Desc = {
    Text = "為了人類存續。\n被保存在畫框裡的記憶。用以升格血肉界域喚醒體的材料。"
  },
  Item_9559_Name = {
    Text = "記憶副本"
  },
  Item_9560_Desc = {
    Text = "歷史會重演，宇宙可能除外。\n記載了神秘文字的文書，用以升格混沌界域喚醒體的材料。"
  },
  Item_9560_Name = {
    Text = "純白文書"
  },
  Item_9561_Desc = {
    Text = "僅策劃試驗用SR武器"
  },
  Item_9561_Name = {
    Text = "試作長劍（幸運）開發用"
  },
  Item_9562_Desc = {
    Text = "購買後獲得隨機部位的SSR品質密契：遠方的歡宴"
  },
  Item_9562_Name = {
    Text = "密契匣：遠方的歡宴"
  },
  Item_9563_Desc = {
    Text = "給予我們未可知曉的靈知。\n源自菲林詩社的特殊膠片，能轉寫人的靈知。\n用以升格超維界域喚醒體的材料。"
  },
  Item_9563_Name = {
    Text = "靈知範本"
  },
  Item_9564_Desc = {
    Text = "主屬性從界域精通、黑印掉落、死亡抵抗和傷害強效中隨機獲得1個。"
  },
  Item_9564_Name = {
    Text = "環形詩篇Ⅵ"
  },
  Item_9564_StoryDesc = {
    Text = "漂浮在環形時間的罅隙裡。"
  },
  Item_9565_Desc = {
    Text = "主屬性從暴擊率、暴擊傷害、界域精通和黑印掉落中隨機獲得1個。"
  },
  Item_9565_Name = {
    Text = "無垢啟示錄Ⅱ"
  },
  Item_9565_StoryDesc = {
    Text = "那是永恆無垢的真實一瞥。"
  },
