  Item_9568_Desc = {
    Text = "她只追求某種絕對意義上的純粹之美，將轉瞬即逝的刹那銘刻為永恆。\n·施加延時護盾，同時造成傷害\n·施加護盾，獲取觸腕"
  },
  Item_95690_Desc = {
    Text = "那是古老意志的失落靈識。 彌薩格通過神秘的儀式啟發喚醒體的靈識，受到啟發的喚醒體將永久增強精神能力。\n重複獲得杜勒賽因時轉換獲得，用於啟動杜勒賽因的啟靈。"
