  },
  Item_95691_Desc = {
    Text = "記錄此鑰令後，可在編隊時選擇鑰令技能：「殘忍的致意」。\n\n滿月已升至中天，食屍鬼之王向你致意。\n今夜，我們以仇敵的頭顱啜飲仇恨。\n今夜，我們以愛人的肋骨丈量永恆。"
