  Item_95699_Desc = {
    Text = "能夠增幅持有者造成的基礎傷害，並隨探索進程持續增加持有者的狂氣爆發傷害與暴擊率，食用胚胎時週期性額外獲取狂氣。"
  },
  Item_95699_StoryDesc = {
    Text = "不必害怕死亡。那只是肉體將靈魂交還給夜色的過程，如潮水退去，歸於幽深的安寧。徹底地消散於融蝕，淪為無人知曉、毫無意義的存在才是真正的恐怖。\n她死得並不安詳。\n枯槁的身軀早已僵冷，血液與融蝕液混合，凝結如暗紅色的玻璃。可她年輕的靈魂仍在喉嚨深處顫抖，那一絲未曾消散的意識，如煙霧滯留在骨縫間。像一隻脆弱的、折翼的美麗蝴蝶。\n杜勒賽因靜靜地走入房間，腳步未驚動塵埃。他在她身旁跪下，視線輕柔地略過她緊閉的眼、未展的指節，以及不安晃動的靈魂。\n「我還活著嗎？」\n「這黑暗會把我吞掉嗎？」\n他不言語，只是伸出手，將她皸裂的手指一根根展開，像是為一朵顫抖的花瓣撫平摺痕。沒有憐憫、也沒有責備，只有平和而寧靜的耐心，像是世間最公正、最莊嚴的神明，賦予她安詳的權利。刹那間，她彷彿抵達了永恆的寧靜。\n於是純淨的芳香在他們交握的手中逸散，他俯身，滿足而莊重地在她的指背落下一吻。那吻落下的瞬間，死亡的最後一道回聲一點點拉長，直到融為飄在空中的一道清風，如暴風后的湖泊，全然寂靜。沒有疑問，沒有怨恨，沒有恐懼。她終於歸屬死亡本身。\n「我會記住你。」\n他直起身，凝視她如今徹底歸於寧靜的模樣。恍惚中，尖牙刺入皮膚，他聽到了賽琳涅的聲音。\n「我相信你，兄長。」\n她是幸運的，在杜勒賽因的記憶中，她將獲得永恆的安息。"
  },
  Item_9569_Desc = {
