  Item_9573_Name = {
    Text = "入藥之夢Ⅴ"
  },
  Item_9573_StoryDesc = {
    Text = "一千年前，五分鐘等於四十盎司細沙。"
  },
  Item_9574_Desc = {
    Text = "「燒瓶要清洗如新，桌子要打磨到反光，天平每三日就要重新校準。」\n·為隊伍提供狂氣\n·為隊伍回復大量生命"
  },
  Item_9574_Name = {Text = "朵爾"},
  Item_9575_Desc = {
    Text = "這下沒人敢用它來占卜吉兇了吧。\n被融蝕漿覆蓋的紫色水晶，用於提升超維界域喚醒體的技能等級。"
