  },
  Item_9588_StoryDesc = {
    Text = "@1年6月5日\n阿爾比諾從融蝕裂隙中帶回來了一些稀有的銀芯。真有他的。\n改良了一下提純的方法。\n這次通入了足量二氧化碳和氯氣，低溫蒸發、結晶……\n一些機械的步驟，沒什麼好記錄的。\n\n@1年6月6日\n切除實驗體024的內臟及肢幹。\n這是阿爾比諾從診所裡帶回來的素材，已生成13個融蝕孔洞，最大直徑8mm。\n切割OS-106號融蝕怪物贅生物。\n根據各項測試資料的比對，它與024之間的共鳴相性最高。\n唯一的問題……那些觸腕有些過於「活潑」了。\n我想很長時間內我都不願意再吃章魚了。\n希望最後的結果別令我失望。\n\n@1年6月6日\n嫁接實驗成功，實驗體各項生命體征消失。\n這是常有的情況，只需要確保嫁接部位沒有擴散感染。\n送入觀察室觀察一週，接下來就不是我的工作了。\n今天在「內部期刊」上讀到兩篇抨擊活人喚醒體實驗的檄文。\n不用說，署名一看就是我在彌薩格的老朋友們。\n真可笑啊，這些老古板但凡肯挪動一下他們肥大的屁股，去實驗室稍微走走，就會知道我的結論是無可撼動的。\n024的實驗將成為一次絕佳的反擊。\n\n@1年6月22日\n兩星期過去了，024的各項體征依然不穩定——或者這麼說吧，她體內的人格正在以細胞有絲分裂的速度瘋狂增殖。\n實驗以一種匪夷所思的方式宣告失敗。\n把024送去蠟像館吧，我不需要它每天守著我，好讓我時刻回想起自己的愚蠢與輕率。"
  },
  Item_9589_Desc = {
    Text = "提高持有者施加的中毒層數，伴隨著鑰令的釋放獲得更多的狂氣。"
  },
  Item_9589_Name = {
    Text = "腐朽贈禮"
  },
  Item_9589_StoryDesc = {
    Text = "「人們於潮來時誕生，於潮退時死亡」\n這是在寧菲亞的家鄉一直流傳的傳說。\n\n塞瓦達的鄉民不懼死亡，在他們看來，生命的萌芽與凋零就像潮起潮落，都是自然的一部分。\n他們熱愛藍天、大海、成群翻飛的海鷗，還有迎著朝陽盛開的馬蹄蓮。\n他們厭惡蒸汽、鐵軌，以及一切人工干涉痕跡太重的事物——對生命的干涉也包含在列。\n人為地斬斷自己的生命，在塞瓦達人看來是不可接受的。\n\n寧非亞並不是一個典型的賽瓦達人。\n比如說，她總是被沉船的氛圍所吸引。\n一艘死去的沉船是無數生命的家園：魚、水草、各種貝類……\n在這裡，生與死以一種神秘、聖潔的方式交織在一起。\n寧菲亞滿懷平靜靠近沉船，彷彿邁入一座無比莊嚴的大教堂。\n\n在父親帶她外出旅行散心的歲月中，寧菲亞曾看過一部五幕劇。\n關於那部劇的內容，寧菲亞早已模糊，似乎講了一位古代帝王的一生。\n他生前戎馬倥傯，征戰南北，卻死於可恥的陰謀。\n她記得裡面的一句臺詞：\n<Italic:懦夫在未死以前，就已經死過好多次；勇士一生只死一次。>\n\n多年以後，當寧菲亞步入冰冷的海水，卻因對生的眷念而痛苦不已時，腦中便飄過那句話：\n「勇士一生只死一次……」\n於是她擦乾眼淚，最後一次向父母道別，這才向心中的沉船繼續行進。\n她將成為自己的勇士。"
  },
