  Item_9615_Name = {
    Text = "根源沉澱"
  },
  Item_9616_Desc = {
    Text = "屬性為銀鑰充能等級的命輪。"
  },
  Item_9616_StoryDesc = {
    Text = "A. F.@1年@1月@1日\n\n08：00\n\n對編號為107至133的部件進行組裝。\n\nC類型部件就差這一點了，完成後將作為自動人偶「嘀嗒人」的能源核心投入使用。\n\n我本想親自組裝的，但@2說，負責人要學會信任自己的工作夥伴。\n\n真好意思說，明明她才是那個檢查部件檢查到半夜的人。\n\n-------\n\nA. F.@1年@1月@1日\n\n00：21\n\n電機MF311000組裝完畢，齒輪吻合，管道通暢，目前各項機能正常。即將進行最後修正。\n\n13：07\n\n接入特殊能源S，電機MF311000運轉良好，與EA307850號人造軀體適配良好，人造軀體正常運轉。\n\n@2很樂觀，她覺得我們這次能比之前走得更遠。我提醒她不要忘記第五次喚醒嘗試時發生了什麼，她就堵著耳朵說聽不見。那次要不是我反應快，能源核心自燃的火焰會把她的頭髮都燒光。\n\n真該讓她嚐嚐光頭的滋味，說不定這樣她還能學會謹慎。\n\n-------\n\nA. F.@1年@1月@1日\n\n14：55\n\n最終準備完畢，能源準備完畢，束縛裝置已開啟，束縛狀態：良。軀幹將在喚醒完成後進行安裝。\n\n15：00\n\n開始「嘀嗒人」第13次啟動嘗試。\n\n15：05\n\n軀幹EA307853運轉正常，電機MF311000運轉正常。「嘀嗒人」頸部關節活動正常，「嘀嗒人」頭部部件運轉正常。\n\n15：15\n\n「嘀嗒人」成功執行眨眼、視線跟隨、張嘴指令。電機存在發熱現象，但仍在可接受範圍內。\n\n即將進行四肢部件安裝，上天保佑我們這次順利。\n\n18：07\n\n執行行走指令時，電機核心熔解，線路燒毀。特殊能源S完好無損。\n\n@2對這個特殊能源很保護，即使是我都禁止觸碰。我想我可以理解，那確實是一個神秘的物件，看上去就像是普通的金屬銀，也不像有能量儲存的能力的樣子，卻真的能給自動人偶供能，而且那樣高的溫度也沒有對其造成損壞，實在是不可思議。\n\n如果這個東西能夠批量生產，或者大量開採……\n\n或許我該找一天再問問她，也不知道她在這個人偶上還要花多少時間。哪一天她自己變成一個人偶，我都不會感到意外。"
  },
