    Text = "逸散在幽靈船中的情緒粒子，觸碰時彷彿聽見了「沒辦法」的沉吟。\n用於提升守密人在調查事件「風暴之眼」中的共鳴。\n可在「風暴之眼」關卡首通獎勵中獲取。"
