  Item_9623_Name = {
    Text = "旋轉，旋轉"
  },
  Item_9623_StoryDesc = {
    Text = "巨大的舞臺上，一個少女正在舞蹈。\n她頭髮緊緊地梳成一個髮髻，頭上點綴著潔白的羽毛和小巧的王冠，純白的舞裙隨著她的動作展開，在哀婉的提琴聲中轉了一圈又一圈。\n手臂舒展，足尖點地，白天鵝低垂長頸，向王子訴說自己的悲傷與哀愁。\n年幼的莉茲微張著嘴，看著台上輕盈優雅的少女，那是她的堂姐，在她出生以前就到她家裡來，在她祖母手下接受嚴格的訓練。平日裡總是樸素而且安靜的堂姐從未如今天這般鮮活，她就像一隻即將振翅而去的天鵝，而她，他們，劇院裡的所有人，都傾倒在她的陰影之下。\n她的心跳越來越快，越來越快——多麼令人羡慕！她也想成為那只天鵝，在永恆的舞臺上長久地留下屬於自己的倒影。她知道自己做得到，難道祖母不曾在她不注意的時候稱讚過她的腿又長又直嗎？難道她那做了多年首席的表姐不曾說過，她極有舞蹈天賦嗎？沒錯，只要她開始，只要她穿上足尖鞋，人們一定會從遙遠的城市前來觀看演出，她將是本世紀最偉大的舞者，芭蕾藝術的璀璨明星！\n那時的她還不知道，等待自己的，只有熾熱的火焰。"
  },
  Item_9624_Desc = {
    Text = "高傲、任性、自我中心……許多與她接觸過的人，都會對她的個性留下如此評價。\n·犧牲生命上限，獲取護盾與算力。\n·施加護盾，增強觸腕之力"
  },
  Item_9625_Desc = {
    Text = "持續而穩定的狂氣與銀鑰獲取，適合依賴狂氣爆發的銀鑰角色。"
  },
  Item_9625_Name = {
    Text = "阿庫特之春"
  },
  Item_9625_StoryDesc = {
    Text = "在災厄憑空消失，危機宣告暫時解除後，彌薩格特別行動隊帶著「意外收穫」離開了阿庫特。\n德克斯特小姐最後回頭看了一眼爆炸中心的巨坑，不知名植物的嫩芽竟不知何時悄然破了土。\n她鬆了一口氣，心情愉悅。\n阿庫特林地將會迎來它的春天。\n楊柳會在下一個春天到來時抽條，鈴蘭會在下一個雨季後悄然綻放，所有的生命都將迎來新生。\n而他們對抗未知的旅途，也將踏上新的起點。\n"
  },
