  },
  Item_9631_StoryDesc = {
    Text = "傳說中最初的魔像創造者，以雙手殺死魔像。"
  },
  Item_9632_Desc = {
    Text = "給予我們未可知曉的精神。\n源自菲林詩社的特殊膠片，能轉寫人的精神。\n用以升格超維界域喚醒體的材料。"
  },
  Item_9632_Name = {
    Text = "精神範本"
  },
  Item_96331_Desc = {
    Text = "在「學期課題」中購買「核心課題」後可獲得。\n「無論何時前往黑池，你看到她的臉上都是那一副詭異的笑容，你常常懷疑是不是融蝕已經毀掉了她大腦的運動皮層，或是杏仁體表達情緒的部分只剩下了這固定的一種。」"
  },
  Item_96331_Name = {
    Text = "永不褪色的昨天：熔燬·朵爾"
  },
  Item_96331_StoryDesc = {
    Text = "第20期學期課題"
  },
  Item_96332_Desc = {
    Text = "在「學期課題」中購買「核心課題」後可獲得。\n「長達36小時的實驗室工作令那顆天才大腦的疲憊透過人偶的軀體散發而出，你彷彿看到那無機的面龐上出現了虛幻的黑眼圈。一個保命的常識：在這種時候絕對不要挑戰她的理性，絕對。」"
  },
  Item_96332_Name = {
    Text = "永不褪色的昨天：朵爾"
  },
  Item_96332_StoryDesc = {
    Text = "第20期學期課題"
  },
  Item_9633_Desc = {
