  Item_9636_Name = {
    Text = "埋骨地絮語Ⅲ"
  },
  Item_9636_StoryDesc = {
    Text = "我唾棄你的墳墓。"
  },
  Item_9639_Desc = {
    Text = "是的，萬物皆可淬製。你的本能、你的理智，甚至你的心……到頭來你會發現，你和他們其實也沒什麼不同。\n用以升格深海界域喚醒體的材料。"
