  },
  Item_9653_Desc = {
    Text = "記錄此鑰令後，可在編隊時選擇鑰令技能：「鼠鼠的智慧」。\n\n小老鼠和它的主人有著許多的共同點：\n狡黠、勇敢、跑得快……\n他們自由地穿梭在東區錯落的房屋間隙，以天空為被，以屋頂為席。\n他們在城市的角落茁壯生長。"
  },
