  Item_9666_Name = {
    Text = "光合祭禮Ⅳ"
  },
  Item_9666_StoryDesc = {
    Text = "科學是光譜分析，藝術是光合作用。"
  },
  Item_9667_Desc = {
    Text = "觸發死亡抵抗後爆發性提高生存，在血肉界域中還能額外獲取胚胎融合。"
  },
  Item_9667_Name = {
    Text = "吞噬搖籃曲"
  },
  Item_9667_StoryDesc = {
    Text = "她被稱作伴隨著死亡出生的詛咒之子，不被祝福的女兒。\n屬於她和妹妹的「襁褓」剛剛破裂，絢爛的光便從縫隙中流出，在地上扎根。一瞬間，綠草枯萎，鮮花灰敗，連遠方的大樹，湖中的遊魚，都被她吸取了生機，成為一個個無魂的軀殼。\n她的族人大驚失色，趕忙將所有其他襁褓轉移。她努力破開襁褓，像雛鳥破開蛋殼，伸出的手卻被厭惡地躲開，目之所及的是一張張嫌惡的臉。\n只有她妹妹，那晚於她降生，又早於她成熟的妹妹，永遠會抱著她。為她用靈鳥一般的歌喉唱出一首又一首搖籃曲。\n睡吧，睡吧，我親愛的姐姐；\n睡吧，睡吧，好夢終將降臨。\n\n她不該存在的，如果她不存在，她那流光溢彩的妹妹就不會被染上罪惡的陰影。\n我可憐的妹妹啊，她總是想，你承擔了本不該承擔的生存的代價。\n我可憐的妹妹啊，她總是想，只要姐姐能夠做到，就一定為你竭盡全力。\n睡吧，睡吧，我親愛的妹妹；\n睡吧，睡吧，在夢裡我也愛你。"
  },
  Item_9668_Desc = {
    Text = "歷史會重演，宇宙可能除外。\n記載了神秘文字的秘篇，用以升格混沌界域喚醒體的材料。"
  },
  Item_9668_Name = {
    Text = "純白秘篇"
  },
  Item_9669_Desc = {
    Text = "為了人類存續。\n被保存在畫框裡的意識。用以升格血肉界域喚醒體的材料。"
  },
  Item_9669_Name = {
    Text = "意識副本"
  },
  Item_9670_Name = {Text = "鑰匙"},
  Item_9671_Desc = {
    Text = "芽孢又做錯了什麼呢，它們只是想有個家罷了。\n蟲蛹和它的芽孢鄰居。用於提升血肉界域喚醒體的技能等級。"
  },
  Item_9672_Desc = {
