  Item_9673_Desc = {
    Text = "那是古老意志的失落靈識。 彌薩格通過神秘的儀式啟發喚醒體的靈識，受到啟發的喚醒體將永久增強精神能力。\n重複獲得潘狄婭時轉換獲得，用於啟動潘狄婭的啟靈。"
  },
  Item_9673_Name = {
    Text = "殘片·潘狄婭"
  },
  Item_9673_StoryDesc = {
    Text = "重複獲得潘狄婭時轉換獲得，用於啟動潘狄婭的啟靈。"
  },
  Item_9674_Desc = {
    Text = "她是戴罪者的恐懼與渴望，是垂死者的甘霖與毒酒，帶來甜蜜的痛苦與浪漫的瘋狂。\n·偷取敵方力量\n·敵方攻勢越猛烈，造成傷害次數越多"
  },
  Item_9674_Name = {Text = "潘狄婭"},
  Item_9675_Desc = {
    Text = "數億年前，它們在溫暖的海洋中稱霸一方。\n高莖海百合的化石。用於提升深海界域喚醒體的技能等級。"
  },
  Item_9675_Name = {
    Text = "高莖海百合"
  },
  Item_9676_Desc = {
    Text = "一百二十分之一的奇蹟。\n暗紅色的寶石碎屑，可用於合成賢者之石。"
  },
  Item_9676_Name = {
    Text = "賢石碎屑"
  },
  Item_9677_Desc = {
    Text = "大幅提高持有者的反擊堆疊能力，伴隨著持有者的卡牌進入超維空間能夠額外獲取大量狂氣。"
  },
  Item_9677_StoryDesc = {
    Text = "關於旺達的確切來歷，坎布裡安的鄉民眾說紛紜。\n\n有人說，他親眼見到旺達坐著一塊巨大的石頭墜入湖畔。\n有人說，她是來自勒姆瓦希的女法老，他曾在木乃伊身上見過一模一樣的脊刺。\n還有人說，她是來自弗蘭高地的女公爵，在連續克死四任丈夫後，繼承了鉅額的財產。\n……\n\n傳言如風般散去，鄉民們繼續耕作、紡織、推磨。\n在那些困苦的年月裡，沉重的稅賦是高懸頭頂的利刃，斬斷一切橫生的枝節與綺念。\n只是……每每路過女王棲息的湖區，叢林掩映中傳來的樂音還是輕易勾住了大家的心。\n那是不該出現在這裡的旋律。\n它太愉悅、太慵懶，以至於顯得邪惡，宛若惡魔低語。\n\n「來吧，拋開這一切。」\n「慈悲的王端坐於湖中央，祂靜待盲眼僕從的侍奉……」\n\n於是，在一個無風的夜晚，疲憊的鄉民放下農具，決定滿足一下偷跑的好奇心。\n他繞過樹林，穿過小橋，道路兩旁鮮花盛開，他連看都不看一眼。\n他看到綠色的湖泊。\n它與低垂的星空相連，邊沿聳立著一座古老的城堡。\n\n頭戴荊棘的女王端坐於湖中央，耐心地等待前來朝聖的子民。\n她伸出手，享受著來自凡人的親吻與膜拜。\n烏雲散去，明月升起。\n女王將脊刺刺入他的背脊。\n麻痺的液體沿著血管蔓延，他跪在地上，被砍掉四肢，被剜掉雙眼。\n\n至此，來自大地的沉重引力再也無法將他吸附，他所有的詩與夢都只繫於那位女王。\n他終於迎來自己的命運。"
  },
