  Item_9687_Name = {Text = "藥膏"},
  Item_9688_Desc = {
    Text = "套裝：\n海歸線Ⅰ\n海歸線Ⅱ\n海歸線Ⅲ\n海歸線Ⅳ\n海歸線Ⅴ\n海歸線Ⅵ"
  },
  Item_9688_Name = {Text = "海歸線"},
  Item_9689_Desc = {
    Text = "提高持有者造成的護盾和傷害，額外洗入的打擊和防禦帶來更多可能。"
  },
  Item_9689_Name = {
    Text = "堅韌意志"
  },
  Item_9689_StoryDesc = {
    Text = "「撤退，撤退！」\n「往@3撤！動作快！」\n「救命，救救我！不要丟下我！」\n「別管他了，趕緊撤退——艾爾瓦！」\n手持銃刃的士兵一個健步衝了出去，炮火在她身側炸響，士兵的廝殺聲，慘叫聲，急促的戰爭號角響成一片。血液染黑了泥土，散發著連硝煙的氣味都無法蓋過的濃重腥味，倒在地上的士兵們眼神空洞，不論是哪個顏色的軍服，都在此刻變成了刺眼的紅。\n艾爾瓦咬著牙，頂著一個又一個向她攻來的人向前。她能看見了，那個呼救的年輕人，他被按在地上，雙手同時用力努力格擋住來自一名高大敵軍的匕首。\n爆裂的槍鳴與劇烈的疼痛同時造訪，不遠處的敵人緩緩倒下，艾爾瓦立刻回身揮刀，忍著腿部的疼痛向前用力撞去，趁著敵人失去平衡的瞬間一把貫穿了對方的胸膛，同時按下扳機。\n子彈打入軀體濺起血肉，她隨意抹了一把臉，回頭想要確認年輕人的安全，卻發現對方已經不知何時離開了。\n她低頭看去，一把刀從她的左膝上方貫穿了她的腿，溫熱的血液汨汨流淌。\n她從披風上撕下一條布綁在腿根勉強限制血流，將銃刃當做臨時拐杖一瘸一拐地跟上部隊。"
  },
  Item_9690_Desc = {
    Text = "無人會用淚水尊敬你，無人會用哭泣埋葬你，只因在生前你已名揚羅馬。\n·不停戰鬥，直至死亡\n·生命愈低，瘋狂愈深"
  },
  Item_9690_Name = {
    Text = "尤烏哈希"
  },
  Item_9691_Desc = {
    Text = "屬性為狂氣回充等級的命輪。"
  },
  Item_9691_Name = {
    Text = "勳爵手杖"
  },
  Item_9691_StoryDesc = {
    Text = "關於德克斯特勳爵的手杖，彌薩格校園內流傳著許多猜想。\n\n「毫無疑問，勳爵的手杖和他的笑容一樣藏有秘密。\n究竟是鑲有銀芯能夠調動喚醒體之力，還是暗藏火藥可以隨時化身槍械呢？\n就讓德克斯特勳爵為我們揭秘一下吧！」\n\n邊念邊速記下開場白後，漢娜將相機對準了德克斯特勳爵，期待著來自持有者本人的下文。\n\n「它嗎？沒什麼特殊的，只是德克斯特家族訂製的日用手杖罷了。\n我的這柄上所用的寶石，甚至不如我兄長的珍貴。\n如果一定要說它有什麼特殊之處的話……\n它曾經沾上我父母和兄弟的鮮血，這算不算？」"
  },
  Item_9692_Desc = {
    Text = "屬性為界域精通的命輪。"
  },
  Item_9692_Name = {
    Text = "資訊就是生命"
  },
  Item_9692_StoryDesc = {
    Text = "倫蒂尼恩的地下世界流傳著這樣一個故事。\n\n繁忙的碼頭上、僻靜的巷道中、嘈雜的酒館內……\n你不知道何時、在哪裡能找到那個拿著相機，戴著眼鏡，穿著制服的少女，但只要找到她，就能買到任何你想要的資訊，而代價只有一個——\n\n提供一個僅有你知道的秘密。\n\n有人用吧檯邊聽到的酒後真言換來了競爭對手的致命弱點。\n有人用自己的弱點換來了情人閉口不談的過去。\n少女握有無數情報，唯有一個是用何等秘密都無法換來的。\n\n「關於我的事情？抱歉啊，這可是非賣品哦。」"
  },
  Item_9693_Desc = {
    Text = "屬性為狂氣回充等級的命輪。"
  },
  Item_9693_Name = {
    Text = "心之壁壘"
  },
  Item_9693_StoryDesc = {
    Text = "彌薩格校園中最不能招惹的人，如果朵爾自居第二，那麼第一名非茜爾維婭女士莫屬。\n\n身為彌薩格唯一的心理醫生，這位神秘的女士不僅要負責安撫任務中受驚的調查員，疏導喚醒體躁動的情緒也是她的職責。\n非但不畏懼喚醒體，還能在精神上與他們分庭抗禮——這究竟是怎樣的一位強者呢？\n\n懷著對未知的好奇，缺失了幾分敬畏之心的新生於深夜溜進了茜爾維婭女士的診療室。\n\n然後，他們就失去了意識。\n次日清晨在校園廣場上醒來時，他們頭疼欲裂，內心卻是前所未有的明朗。\n有人撿起了從他們口袋裡飄落的信箋：\n\n「如果需要心理諮詢，請提前向艾瑞卡小姐申請哦——\n茜爾維婭」"
  },
  Item_9694_Desc = {
    Text = "這下沒人敢用它來占卜吉兇了吧。\n被融蝕漿覆蓋的紫色水晶，用於提升超維界域喚醒體的技能等級。"
  },
  Item_9694_Name = {
    Text = "殘破礦晶"
  },
  Item_9695_Desc = {
    Text = "屬性為暴擊率的命輪。"
  },
  Item_9695_Name = {
    Text = "遺忘之手"
  },
  Item_9695_StoryDesc = {
    Text = "手在黑暗中四處亂轉，尋找自己的主人。\n\n在那個血腥的夜晚，它被從主人身上殘酷剝離。\n此時此刻，帶走它的罪魁禍首在它四周流淌，發出奇特的嗡鳴。\n \n「放棄吧，和我們離開。蠟像師會將你徹底遺忘。」\n\n手不為所動，它撥動著自己引以為豪的、修長的手指。\n\n「主人不會忘記我。\n我是他藝術實現的唯一途徑——\n你們不明白我對他而言意味著什麼。」\n\n「就像人會遺忘愛人，遺忘時間，但不會遺忘自己。」\n\n黑暗中傳來同情的笑聲。\n「恰恰相反，人最先遺忘的總是自己。\n不過沒關係——」\n\n時間會解釋一切，手遲早會明白這個道理：\n沒有什麼是不能被遺忘的。\n它們流淌了一個又一個世紀，人間的故事在它們身邊發生，第二天就被遺忘。\n而它們依舊在不停地流淌。"
  },
  Item_9696_Desc = {
    Text = "僅策劃試驗用SSR武器"
  },
  Item_9696_Name = {
    Text = "試作鐳射炮（爆傷）開發用"
  },
  Item_9697_Desc = {
    Text = "屬性為黑印掉落的命輪。"
  },
  Item_9697_StoryDesc = {
    Text = "塔薇沉睡於黑池之底。\n\n那裡終年無聲無光，只有一片令人絕望的黑暗。\n從未有客人造訪過這裡，從未有聲音抵達過這裡。\n這裡是毀滅無法企及之地——\n\n因為災厄已經降臨。\n\n身為時序的司掌者，她目睹過太多慘痛的終局。\n身為規則中的一員，她也無力阻止黑夜的降臨。\n既然如此，只能蟄伏於不存在之地，以不存在之姿等候堪稱「變數」之人到來。\n\n那個人終將到來。"
  },
