  },
  Item_9703_Name = {Text = "隕日"},
  Item_9703_StoryDesc = {
    Text = "A.F. 314，冬日的一個深夜，爆炸聲響徹阿庫特林地。\n大地震顫，林地亮如白晝。伴隨著生命的尖嘯與自然的哭嚎，村鎮被夷為平地。\n據參與了「阿庫特災厄調查」的喚醒系預科生德克斯特所言，那一夜沖天的火光中，閃耀著黑與銀的色彩。"
  },
