  Item_9704_StoryDesc = {
    Text = "時間的弦根根繃斷，流動的琴鍵紛紛碎裂。\n祂們立於現實之外，以現實為材縫補殘缺，讓永不謝幕的樂章再度奏響高天之上。\n至於那片刻夢醒時落的淚流向了何方，無人得知。"
