  },
  Item_9723_Name = {
    Text = "四月禮讚Ⅱ"
  },
  Item_97242_Desc = {
    Text = "在葬骸城，沒有人懼怕死亡的到來。\n在死亡到來前的每一天，人們都將它當做生命的最後一天度過，歡歌、舞蹈、宴飲作樂，這座死亡之城遠比任何生者想像的更加熱鬧。\n當一朵紫色的勿忘我靜靜飄落在窗前時，接到這封來信的人會欣然沐浴、梳妝、穿上自己最愛的衣袍，而後將它別在鬢邊，與城中的人們一一告別，最終牽起至愛親朋的手。\n那是來自葬骸之主的祝福，亦是他的承諾。他祝福他們將與愛的人從此融為一體，沒有誰會將誰拋棄遺忘；他承諾這份相聚的期限，是直至他消散於世間前的永恆。\n在塵世中那片墓地的附近，在那些尋求解脫的人之間，同樣流傳著這樣一個傳說。\n當你不幸受盡了這世界的折磨，將要走到生命的盡頭時，你會在靜謐的黎明看到一縷令靈魂感到安寧的霧。\n如果你尋著那縷霧的指引走向荒野，走向無人知曉的世界邊緣，你會看到一片在無數墓碑之中綻放的紫色花海。\n那霧的盡頭會佇立著一個俊美的、花朵幻化一般的青年，他彷彿已等待了你的一生那樣久，如今只是按照某種命運約定的落款，要將你接引至再無苦痛的寧靜夢鄉。\n他會接納你的一切，撫慰你的一切，為你帶來最後的救贖。\n他會站在那片花海之中，溫柔地向你伸出掌心：「你願意和我跳一支舞嗎？」"
  },
  Item_9724_Desc = {
    Text = "主屬性從界域精通、黑印掉落、死亡抵抗和傷害強效中隨機獲得1個。"
