  Item_97349_StoryDesc = {
    Text = "第27期相位對弈"
  },
  Item_9734_Desc = {
    Text = "伴隨著「打擊」的使用能夠持續生成護盾，造成更多護盾庇護隊友的同時額外施加更多中毒。"
  },
  Item_9734_StoryDesc = {
    Text = "「記憶是什麼？」\n「是你遺忘的東西。」\n\n莉莉有一個健忘的媽媽。\n她會忘記叫莉莉一起吃飯，會忘記給莉莉喂藥，甚至還會忘記莉莉的名字。\n「該怎麼辦呢？」\n莉莉坐在病床上，故作深沉地歎了一口氣。\n這樣的媽媽可真不省心啊。\n\n後來，莉莉將自己的名字寫在一個木牌上，每天掛在胸前。\n這樣總該記住她了吧？\n一開始，媽媽還能笑著說她多此一舉，那只是長期勞累導致的併發症。\n\n漸漸地，她開始困惑、不耐：\n「莉莉……莉莉是什麼？」\n琥珀色的雙眼注視著莉莉，帶著一絲隱隱的審慎。\n原來，當文字的意義也被遺忘，這般依靠語言暫時維繫的和睦終將一去不返。\n\n莉莉抱住媽媽。\n母女倆的心跳聲只隔著短短几英寸，她卻感到孤獨極了。\n\n那天以後，莉莉將木牌收起，不再向媽媽撒嬌，也不再提醒她自己已經餓了好多天。\n她是行將就木的病患，麻木地等待死神的宣判。\n她是隔岸觀火的看客，遠遠地看著自己被注射、被麻醉、被擺弄成任何媽媽希望她成為的樣子。\n母女間那些愉快的話語、柔軟的擁抱……\n那些閃爍著夢幻泡泡的愉快回憶，都被莉莉小心翼翼地鎖在心裡。\n只有在某些疲憊的夜晚，她才捨得將它們拿出來，輕輕舔舐。"
  },
