  },
  Item_97369_StoryDesc = {
    Text = "第26期相位對弈"
  },
  Item_9736_Desc = {
    Text = "釋放狂氣爆發後能夠回復狂氣並獲得鑰能，適合能夠抽取大量卡牌的喚醒體。"
  },
  Item_9736_Name = {
    Text = "快樂魔法秀"
  },
  Item_9736_StoryDesc = {
    Text = "「我的成名作嗎？嗯——這麼好奇呀，好吧好吧，畢竟是VVIP的要求。不過，普通的講述未免太不符合我魔術大師的名號了，讓我用一場盛大的表演來向你展示吧！\n來來來，請在貴賓席落座，充滿金錢與背叛的懸疑快樂魔法回憶秀，即將開演！」\n-------\n一聲響指，燈光亮起，卡茜亞的魔術帽懸浮在半空，黃色的開口一開一合，竟然傳出了卡茜亞的聲音。\n「沒有很久以前，在一個不怎麼遙遠的地方，有一個馬戲團，馬戲團裡有兔子、有小丑、有獅子、有大象——」\n隨著帽子的抖動，從裡面掉落一隻兔子，一個小丑，一頭獅子，一頭大象。伴奏的鼓點愈發急促，伴隨禮炮炸響的砰砰聲，穿著華麗戲服的卡茜亞從帽子裡鑽了出來，並反手將帽子戴在了自己頭上。\n「最重要的是，有一位天賦異稟，才華過人的魔術師學徒！」\n-------\n學徒的成長伴隨著掌聲，甚至成功吸引了一位穿著華麗的投資人。奇怪的是，自從投資人與他們一同旅行後，兔子、小丑、獅子、大象……很多人和動物都一個接一個地不見了蹤影。舞台上空了大半，學徒卻彷彿亦無所覺，她重複著原本的生活，直到投資人將一杯酒遞到她的面前。\n學徒喝下酒水，暈了過去，舞台隨之一黑，微弱的嘆息從黑暗中飄出。\n「那是我第一次明白遺憾。」\n-------\n「但是，遺憾怎麼夠？我還想要知道資助人先生哭的時候是什麼感覺，觀眾笑的時候是什麼感覺，我想知道更多，更多。這時候——\n我睜開了眼睛。」\n紙製禮花在空中炸開，碎片飄飄揚揚，卡茜亞突然出現在舞台中央，她敲了敲帽簷，禮帽張開嘴，吐出一片炫目的光。\n「我睜開了眼睛，然後發現，所有情感都是光，都可以收納到我的魔術帽中。\n現在請放輕鬆，我親愛的貴賓，接下來的環節一點也不會疼，只會讓你有一點麻木，感到生活有一點無趣……」"
  },
  Item_97370_Desc = {
    Text = "「喜歡我愛的小皮鞭嗎？」"
  },
  Item_97370_EmojiName = {
    Text = "比心·潘迪婭"
