    Text = "呆呆檔案照：索蕾爾"
  },
  Item_97413_StoryDesc = {
    Text = "第24期學期課題"
  },
  Item_97414_Desc = {
    Text = "「誒？如此直白的表達嗎？對我來說還是有點太難為情了……」"
  },
  Item_97414_EmojiName = {
    Text = "比心·奧爾拉"
  },
  Item_97414_Name = {
    Text = "奧爾拉·比心"
  },
  Item_97415_Desc = {
    Text = "在「學期課題」中購買「核心課題」後可獲得。\n「有人曾看見艾爾瓦為了照顧失去母親的幼犬，整整一個月默默起夜、不得安眠。身為軍人，她的忠誠屬於集體，卻被曾經的同伴殘忍拋棄。最終受傷的獸找到了重新接納她的族群，如果你有幸被她劃歸到身後，你會發現那個堅硬的外表下，埋藏著最溫柔的心。」"
  },
  Item_97415_Name = {
    Text = "永不褪色的昨天：艾爾瓦"
  },
  Item_97415_StoryDesc = {
    Text = "第21期學期課題"
  },
  Item_97416_Desc = {
    Text = "「當然，我由衷感激著你，我最忠實的觀眾。」"
  },
  Item_97416_EmojiName = {
    Text = "比心·莉茲"
  },
  Item_97416_Name = {
    Text = "莉茲·比心"
  },
  Item_97417_Desc = {
    Text = "「烤魚，好吃。」"
  },
  Item_97417_EmojiName = {Text = "摸魚"},
  Item_97417_Name = {
    Text = "希洛·摸魚"
  },
  Item_97417_StoryDesc = {
    Text = "第21期相位對弈"
  },
  Item_97418_Desc = {
    Text = "在「學期課題」中購買「核心課題」後可獲得。\n「奇怪，我來這裡做什麼……啊！想起來了！是來找傳說中的材料的！」"
  },
  Item_97418_Name = {
    Text = "永不褪色的昨天：諾締拉"
  },
  Item_97418_StoryDesc = {
    Text = "第24期學期課題"
  },
  Item_97419_Desc = {
    Text = "「如果這，就是承受血脈必經的宿命……」"
  },
  Item_97419_EmojiName = {
    Text = "宿命的哀歎"
  },
  Item_97419_Name = {
    Text = "凱刻斯·宿命的哀歎"
  },
  Item_97419_StoryDesc = {
    Text = "第25期相位對弈"
  },
  Item_9741_Desc = {
    Text = "屬性為暴擊傷害的命輪。"
  },
  Item_9741_Name = {Text = "臨界點"},
  Item_9741_StoryDesc = {
    Text = "在貴族夫人憐憫又嫌惡地用手帕捂住鼻子，差遣僕人將不要的珠寶給她時，她想：\n多好啊，濟貧院的孩子們能吃上一餐肉了。\n\n在她將自己的餐食都分給孩子們，自己則因為長時間饑餓而暈倒在走廊後，她說：\n沒事的，別叫醫生，診金可值好幾個麵包呢。\n\n在好心的藝術家帶著相熟的醫生前來拜訪，並向她提出長期合作時，她想：\n必須讓他們先在我身上試試，不然我可不放心讓孩子們來接受他們的這個什麼治療。\n\n莎拉什麼都可以忍受，唯一不能忍受的便是所做的一切，最終卻導致了悲劇的結局。"
  },
  Item_97420_Desc = {
    Text = "「……是要這樣比嗎？」"
  },
  Item_97420_Name = {
    Text = "卡斯托爾·比拇指"
  },
  Item_97420_StoryDesc = {
    Text = "第26期相位對弈"
  },
  Item_97421_Desc = {
    Text = "臨時文本"
  },
  Item_97421_Name = {
    Text = "以銀鑰之名：聖嬰"
  },
  Item_97421_StoryDesc = {
    Text = "聖嬰玩法活動"
  },
  Item_97422_Desc = {
    Text = "在「學期課題」中購買「核心課題」後可獲得。\n「搭檔……希望你不介意我這個稱呼，你還記得我們第一次相遇的時候麼？啊……對，我是指……和拉蒙娜相遇的時候。」"
  },
  Item_97422_Name = {
    Text = "永不褪色的昨天：環行·拉蒙娜"
  },
  Item_97422_StoryDesc = {
    Text = "第23期學期課題"
  },
  Item_9742_Desc = {
    Text = "主屬性從暴擊率、暴擊傷害、銀鑰充能等級和狂氣回充等級中隨機獲得1個。"
  },
  Item_9742_StoryDesc = {
    Text = "必然的，偶然的。有限的，無限的。"
  },
  Item_9743_Desc = {
    Text = "芽孢又做錯了什麼呢，它們只是想有個家罷了。\n蟲蛹和它的芽孢鄰居。用於提升血肉界域喚醒體的技能等級。"
  },
  Item_9744_Name = {Text = "腸子"},
  Item_9745_Desc = {
    Text = "她總圍著那台修不好的摩托打轉：擰一下這裡的螺絲，修一下那裡的管道……\n·施加可觀的護盾\n·以反擊施以傷害"
  },
  Item_9745_Name = {Text = "諾締拉"},
  Item_9746_Desc = {
    Text = "巨刃的獠牙曾斬下過無數敵人、同族的頭顱，亦斬下過他自己的。\n·施加力量，發動重擊\n·力量對他有額外提升"
  },
  Item_9746_Name = {Text = "戈利亞"},
  Item_9747_Desc = {
    Text = "主屬性從暴擊率、暴擊傷害、死亡抵抗和傷害強效中隨機獲得1個。"
  },
  Item_9747_Name = {
    Text = "環形詩篇Ⅲ"
  },
  Item_9747_StoryDesc = {
    Text = "漂浮在環形時間的罅隙裡。"
  },
  Item_9748_Name = {
    Text = "蠟像先生"
  },
  Item_9749_Desc = {
    Text = "主屬性從界域精通、黑印掉落、死亡抵抗和傷害強效中隨機獲得1個。"
  },
  Item_9749_Name = {
    Text = "埋骨地絮語Ⅵ"
  },
  Item_9749_StoryDesc = {
    Text = "我唾棄你的墳墓。"
  },
  Item_9750_Desc = {
    Text = "那是古老意志的失落靈識。 彌薩格通過神秘的儀式啟發喚醒體的靈識，受到啟發的喚醒體將永久增強精神能力。\n重複獲得艾瑞卡時轉換獲得，用於啟動艾瑞卡的啟靈。"
  },
  Item_9750_Name = {
    Text = "殘片·艾瑞卡"
  },
  Item_9750_StoryDesc = {
    Text = "重複獲得艾瑞卡時轉換獲得，用於啟動艾瑞卡的啟靈。"
  },
  Item_9752_Desc = {
    Text = "主屬性從界域精通、黑印掉落、死亡抵抗和傷害強效中隨機獲得1個。"
  },
  Item_9752_StoryDesc = {
    Text = "必然的，偶然的。有限的，無限的。"
  },
