  Item_9760_Name = {
    Text = "光合祭禮Ⅵ"
  },
  Item_9760_StoryDesc = {
    Text = "科學是光譜分析，藝術是光合作用。"
  },
  Item_97610_Desc = {
    Text = "她逃離不了那場夢境，她已經決定不再醒來，讓她繼續安睡吧，她將給你應得的報償。\n\n至少掉落{s1}個"
