  Item_97612_Desc = {
    Text = "她逃離不了那場夢境，她已經決定不再醒來，讓她繼續安睡吧，她將給你應得的報償。\n\n至少掉落{s1}個"
  },
  Item_97612_Name = {
    Text = "捕夢香熏"
  },
  Item_97613_Desc = {
    Text = "她逃離不了那場夢境，她已經決定不再醒來，讓她繼續安睡吧，她將給你應得的報償。\n\n至少掉落{s1}個"
  },
  Item_97613_Name = {
    Text = "捕夢香熏"
  },
  Item_9761_Desc = {
    Text = "套裝：\n有機形態Ⅰ\n有機形態Ⅱ\n有機形態Ⅲ\n有機形態Ⅳ\n有機形態Ⅴ\n有機形態Ⅵ"
  },
  Item_9761_Name = {
    Text = "有機形態"
  },
  Item_9762_Desc = {
    Text = "由彌薩格大學創始人研究出的，能夠提升喚醒體能力的製劑。由銀芯與秘藥調配而成，呈現出一種奇異的色澤。\n可以為喚醒體提供10000經驗值。"
  },
  Item_9762_Name = {
    Text = "靈知製劑Ⅲ"
  },
  Item_9763_Name = {
    Text = "蠟像群組"
  },
  Item_9764_Desc = {
    Text = "屬性為死亡抵抗的命輪。"
  },
  Item_9764_Name = {
    Text = "伏於夜色"
  },
  Item_9764_StoryDesc = {
    Text = "巨獸潛伏於夜色之中。\n\n小屋之內，痛失愛女的哀哭聲在每個午夜衝破白日的隱忍與壓抑，毫無掩飾地劇烈迸發。\n從啜泣到哀嚎，最後訴說著那個已經不屬於巨獸的名字，以痛楚的呼喚聲貫穿巨獸那顆與人類一般無二的心臟。\n\n回家吧，麗莎。\n噢，我的麗莎。\n巨獸無聲，潛伏於夜色之中。蜷縮身形，沉沉睡去。\n終有一日，她要回去，回到那個名為「家」的地方。"
  },
  Item_9765_Desc = {
    Text = "那是古老意志的失落靈識。 彌薩格通過神秘的儀式啟發喚醒體的靈識，受到啟發的喚醒體將永久增強精神能力。\n重複獲得莉莉時轉換獲得，用於啟動莉莉的啟靈。"
  },
  Item_9765_Name = {
    Text = "殘片·莉莉"
  },
  Item_9765_StoryDesc = {
    Text = "重複獲得莉莉時轉換獲得，用於啟動莉莉的啟靈。"
  },
  Item_9766_Desc = {
    Text = "那是古老意志的失落靈識。 彌薩格通過神秘的儀式啟發喚醒體的靈識，受到啟發的喚醒體將永久增強精神能力。\n重複獲得希洛時轉換獲得，用於啟動希洛的啟靈。"
  },
  Item_9766_Name = {
    Text = "殘片·希洛"
  },
  Item_9766_StoryDesc = {
    Text = "重複獲得希洛時轉換獲得，用於啟動希洛的啟靈。"
  },
  Item_9767_Desc = {
    Text = "「繁衍」與「存續」才是泰旖絲的追求——無論這可笑的論調之下是否另有隱情。\n·提供隊友狂氣\n·模仿友方技能"
  },
  Item_9767_Name = {Text = "泰旖絲"},
  Item_9768_Desc = {
    Text = "給予我們未可知曉的靈知。\n源自菲林詩社的特殊膠片，能轉寫人的靈知。\n用以升格超維界域喚醒體的材料。"
  },
  Item_9768_Name = {
    Text = "靈知範本"
  },
  Item_9769_Desc = {
    Text = "扇動的翅膀有助於產生龍捲風，或是花粉過敏。\n成群的水晶蝴蝶。用於提升混沌界域喚醒體的技能等級。"
  },
  Item_9769_Name = {
    Text = "混沌結晶"
  },
  Item_9770_Desc = {
    Text = "它並非工藝品，而是蝴蝶撞上煉金術師後的悲慘結局。\n平凡的水晶蝴蝶。用於提升混沌界域喚醒體的技能等級。"
  },
  Item_9771_Desc = {
    Text = "花語：離我遠點。\n低莖海百合的化石。用於提升深海界域喚醒體的技能等級。"
  },
  Item_9771_Name = {
    Text = "低莖海百合"
  },
  Item_9772_Name = {
    Text = "特殊融蝕痕"
  },
  Item_97737_Desc = {
    Text = "記錄此鑰令後，可在編隊時選擇鑰令技能：「定格的仲夏留念」。\n\n現實的狂歡終有結束的一日，但銘刻於靈魂的記憶永無止息。\n無論多少次，當回憶這定格的一刻時，思念都會漲潮。"
  },
  Item_97737_StoryDesc = {
    Text = "現實的狂歡終有結束的一日，但銘刻於靈魂的記憶永無止息。\n無論多少次，當回憶這定格的一刻時，思念都會漲潮。"
  },
  Item_9773_Desc = {
    Text = "液態是它的表像，它是萬物的基石，是一切的構成。\n封裝在玻璃瓶內的特殊物質，據說其擁有干涉命運的力量。\n可以用於提升命輪的等級。"
  },
  Item_9773_Name = {
    Text = "混亂乙太（已廢棄）"
  },
  Item_9774_Desc = {
    Text = "主屬性從暴擊率、暴擊傷害、銀鑰充能等級和狂氣回充等級中隨機獲得1個。"
  },
  Item_9774_StoryDesc = {
    Text = "嗷嗚，嗷嗚。"
  },
  Item_9775_Desc = {
    Text = "翅膀只負責提供美麗，價值五片什。\n閃耀的水晶蝴蝶。身體大部分已被結晶化。\n用於提升混沌界域喚醒體的技能等級。"
