  Item_9780_Desc = {
    Text = "縱使胚胎誕生之刻即是消亡之時，她亦當甘之如飴。\n閃耀著虔誠之心的神秘擺件。用以提升喚醒體技能等級。"
  },
  Item_9780_Name = {
    Text = "虔誠聖心"
  },
  Item_9781_Desc = {
    Text = "掉落自名為刻耳柏洛斯的高維生物。以人類當前文明發展程度，尚無法解析其成分。\n神秘的紫色晶體。用以提升喚醒體技能等級。"
  },
  Item_9781_Name = {
    Text = "維度凝晶"
  },
  Item_9782_Desc = {
    Text = "一截樹的遺骨，時至今日，或可象徵亞蘭文明的殘骸。\n豐穰母樹折斷的枝椏。用於提升喚醒體技能等級。"
  },
  Item_9782_Name = {
    Text = "母樹遺骸"
  },
  Item_9783_Desc = {
    Text = "天生佩戴王冠之人，難以理解競逐者的熱衷。\n沉重的冠冕。用以提升喚醒體技能等級。"
  },
  Item_9783_Name = {
    Text = "聖胎冠冕"
  },
  Item_9784_Desc = {
    Text = "在那無數道原初的目光下，你們負傷，殞命。你們將以守密人之名，前赴後繼。\n無上意志遺留下的眼瞳，用於提升喚醒體技能等級。"
  },
  Item_9785_Desc = {
    Text = "象徵著不祥的捕夢網，傳說能夠鏈接通向永恆的大門。\n提燈教會用來捕捉神明夢中囈語的工具。用於提升喚醒體技能等級。"
  },
  Item_9785_Name = {
    Text = "夢囈捕手"
  },
  Item_9786_Desc = {
    Text = "屬性為銀鑰充能等級的命輪。"
  },
  Item_9786_Name = {
    Text = "冬夜追憶"
  },
  Item_9786_StoryDesc = {
    Text = "陰沉的雲籠罩在倫蒂尼恩上空，隔絕了月光。午夜的鐘聲已經敲響，高聳的煙囪仍在噴出高溫的黑煙與水汽。雪花沾了風中的塵埃，還未落地就已經染上暗淡的灰色，它飄飄搖搖地落在路燈上，幾乎是瞬間就被燈火的熱度融化，向下滴落在路過的女孩身上。\n女孩穿著褐色衣裙，過大的袖管被草率地挽起，露出兩條瘦骨嶙峋的手臂。她艱難地小跑著，時不時提一提衣袖，努力追趕走在前方的女人。\n女人側頭瞥向女孩，嘖了一聲：「動作快點，不要以為你走得慢了就不用去了。」\n「好、好的，媽媽，」女孩趕緊跑到女人身旁，嘴裡還喘著氣，「對不起，媽媽。」\n「不要叫我媽媽！」女人一把抓住女孩的手臂，拖拽著女孩加快了腳步，「吸人血的廢物，要不是你，我哪裡至於淪落到這個破地方。」\n「對不起……」\n「閉嘴，沒用的東西。」女人的指甲嵌入女孩的手臂，掐出一排深深的痕跡，「我告訴你，從今往後工坊才是你的家，也不要想著什麼出來找我，我就是死都不想看見你，聽到了嗎？」\n「我……我知道了。」女孩低著頭，落下的淚水被鞋子踏過，與骯髒的雪水一同消失在石板路上。遠處的工廠拉響了放工的笛聲，一隻野貓竄過巷道，細碎的動靜隱沒在兩人的腳步聲中。她們轉過街角，走過晾了衣服，散發著潮氣的後院，終於在一個有著金屬大門的建築前停了下來。\n「你就在這兒等著吧，」女人的聲音非常平穩，甚至帶上了一絲木然，「天亮了裡面的人就出來了，他們會收留你的。\n別跟上來，不然你看我打不打死你。」\n女人轉身離開，同樣瘦削甚至有些佝僂的身影很快消失在了黑暗之中。女孩無助地捏著自己的手，一邊望著女人離開的地方，一邊用袖子擦去臉上的淚水。\n昏黃的燈光從她身後出現，將鐵門和她的影子拉長，一隻手落在了女孩肩上，將女孩嚇了一跳。\n「可憐的孩子，怎麼一個人在這兒？」來人是一個年輕女性，穿著修女一般的衣袍，「來，莎拉姐姐帶你進去。很快就不冷了。」"
  },
