  Item_9789_Name = {
    Text = "被縛的歌謠"
  },
  Item_9789_StoryDesc = {
    Text = "人是一種喜歡歌唱的生物，對荒星人而言也是如此。\n旋律自喉中自由湧出，無需任何意圖和目的。\n它們被風拆成散落的音符，再隨情緒一起凋零。\n據說，在沙漠中，所有流浪部族都擁有屬於自己的歌謠。\n荒星人卻遺落了自己的歌謠。\n\n隨著歌謠一起遺落的，還有名字。\n沒人知道荒星原本的名字。\n這是受到詛咒的星球。乾旱、風暴、饑荒……\n各式各樣的災厄競相登場，終於將荒星徹底拖垮。\n衣著華麗的大人物乘坐方舟離去，荒星成了名副其實的荒星，只剩下那些不被祝福的底層人。\n他們都被遺棄了。\n\n自那以後，荒星人決定，他們不需要歡笑，不需要詩，也不需要歌謠。\n他們將銘記被遺棄的苦與痛，周而復始地蠕行在白色的沙漠之中，直到星球毀滅的那一刻。"
  },
  Item_9790_Desc = {
