  Item_9798_Name = {
    Text = "認知範本"
  },
  Item_97991_Desc = {
    Text = "一個好的節日，應當是一場縱情狂歡的理由。\n評判一個節日是否足夠討人喜歡，它的來由尤為重要。節日太小，諸如鼓勵種樹或是紀念一隻愚蠢土撥鼠的節日，就不足以趁機享樂；節日太大，像是銀霜節那樣隆重的節日，則過於莊嚴，規矩太多。\n翻遍整本日曆，墨菲最期待的就是這個叫做巡聖節的日子。這個貼心的節日天然附贈了一場夜間派對，所有人都可以將自己盛裝打扮成奇形怪狀的樣子，最最關鍵的是，在這一天，無數的甜品與糖果將佔領彌薩格的每個角落。\n水果軟糖、酒心糖、奶糖、薄荷糖、太妃糖、各色巧克力……哈！這難道不是專門為淑女而準備的節日嗎？\n墨菲興致勃勃地戴好尖尖的女巫帽，換好蓬蓬的南瓜裙，然後認真挑選了一個最大的南瓜籃子推門而出。\n「什麼？你說這些糖是專門為小孩子準備的？」\n看著詹金滿載而歸離去的背影，淑女不可置信地豎起了眉毛，裙擺下的觸鬚不滿地甩動起來。\n兩排牙齒憤恨地磨了磨，她冷笑一聲，咚地將南瓜籃子狠狠地摔在了櫃檯上。\n「不能領是吧，那好，現在我不是小孩，是強盜！打劫！我數三個數，把你們這所有的糖都給我包起來！趕快！」\n滿頭大汗的餐廳侍者被迫清空了糖果臺，而後目送淑女拎著滿溢出來的籃子，在猖狂的笑聲中大搖大擺離開。\n這詭異的笑聲在校園四處持續了整夜，後來，彌薩格之中多了這樣一則傳聞：在巡聖節的那一夜，所有身上攜帶了糖果的人都會被一個幽靈環繞的獵糖女巫精准地找上，只有虔誠上繳所有的甜食，才能從可怕的女巫手中逃出生天。"
  },
  Item_97992_Desc = {
    Text = "被特地做成南瓜形狀的節慶糖果，裡面的夾心混雜了不同的餡料，據說有機會吃到極其詭異的口味。"
  },
