  Item_9815_StoryDesc = {
    Text = "臍帶連接著無窮無盡的未來。"
  },
  Item_9817_Desc = {
    Text = "屬性為銀鑰充能等級的命輪。"
  },
  Item_9817_Name = {
    Text = "溯洄時計"
  },
  Item_9817_StoryDesc = {
    Text = "雙手大劍長而沉重，在足夠的力道下足以將人斬成兩段。\n\n匕首輕便靈巧，便於隱藏，非常適合出其不意的攻擊。\n\n彎刀弧線華美，刀刃鋒利，劈砍時可以輕鬆嵌入皮肉，拉開一道深深的口子。\n\n槍械快而霸道，弩箭無聲且迅速，各種各樣的金屬部件在燈光下閃著冷酷的光。十歲的拉蒙娜站在掛滿了一牆的武器前，臉上是不符合年齡的成熟與慎重。\n\n「你想選哪個？」養父——不，是撫養自己長大的父親——的聲音從身後傳來，「選好了，我去給你物色老師。」\n\n哪個呢？大劍的沉重既是優點也是缺點；匕首難以應對較長的武器；彎刀雖然長，但切割總是會帶來很多不必要的損傷；槍械噪音太大，弩箭容易彈藥耗盡。\n\n在彌薩格訓練場旁觀了這麼多天，她知道自己能一眼看出作戰雙方的弱點，並能近乎直覺地計劃好攻擊路線。那些需要大量經驗積累才能知道的東西，在她這裡只需一秒便能推演出來。不，她要的不是這些。她需要一個更精確的，能夠用最少的力造成最大的傷害的武器。\n\n女孩思索片刻，從一旁搬來一個凳子，站在上面將手伸向掛在高處的細劍。\n\n細長優雅，靈活輕便，可以很准確地造成傷害——沒錯，就是它，它符合她的一切要求。"
  },
  Item_9818_Desc = {
    Text = "她究竟是如何說話的——這成了學院無數未解之謎中的一個。\n·在獲取力量與獲取戒備中來回切換\n·在超維躍遷時，能兼顧攻防"
  },
  Item_9819_Desc = {
    Text = "套裝：\n無垢啟示錄Ⅰ\n無垢啟示錄Ⅱ\n無垢啟示錄Ⅲ\n無垢啟示錄Ⅳ\n無垢啟示錄Ⅴ\n無垢啟示錄Ⅵ"
  },
