  },
  Item_9824_StoryDesc = {
    Text = "科學是光譜分析，藝術是光合作用。"
  },
  Item_9825_Desc = {
    Text = "它並非工藝品，而是蝴蝶撞上煉金術師後的悲慘結局。\n平凡的水晶蝴蝶。用於提升混沌界域喚醒體的技能等級。"
  },
  Item_9826_Desc = {
    Text = "那是古老意志的失落靈識。 彌薩格通過神秘的儀式啟發喚醒體的靈識，受到啟發的喚醒體將永久增強精神能力。\n重複獲得萊克時轉換獲得，用於啟動萊克的啟靈。"
  },
  Item_9826_Name = {
    Text = "殘片·萊克"
  },
  Item_9826_StoryDesc = {
    Text = "重複獲得萊克時轉換獲得，用於啟動萊克的啟靈。"
  },
  Item_98279_Desc = {
    Text = "獲得幻衣「落楓如血」後解鎖。\n「那搖曳的潔白裙擺之上，也盛滿了鮮紅的落楓。」"
  },
  Item_98279_Name = {
    Text = "「24」·落楓如血"
  },
  Item_9827_Desc = {
    Text = "釋放狂氣爆發後提供臨時暴擊傷害，並有機率降低持有者卡牌費用。"
  },
  Item_9827_StoryDesc = {
    Text = "分開。經歷。蜂擁而來。侵略。\n\n對於非利士人的閃族語詞根「p-l-sh」的真正涵義，經書學者們歷來分歧不斷。\n平生第一次，戈利亞覺得這些老學究還算有點真才實學，因為這四個簡短的詞彙幾乎概括了他作為非利士人的一生。\n\n非利士人是名副其實的海上民族。\n他們是群聚的長尾鯊，循著鮮血的味道找到可供棲息的島嶼，再殺光那裡所有的原住民。\n\n非利士人不知疲倦。\n他們從不逗留，當一切塵埃落定，躁動不安的基因又驅使他們離開，尋找新的獵物。\n\n非利士人不在乎明天。\n他們總是以驚人的速度揮霍掠奪來的財富，飲盡最後一滴葡萄酒，然後盡情繁衍、爭鬥、背叛……\n\n啟航的時候，戈利亞回望船隻在海面上拖曳而出的軌跡。\n非利士人的血，原住民的血，敵人的血，海鳥的血……\n它們匯到一處，就像暗紅的墨湧入無邊無際的藍。\n\n第二天，太陽照常升起，海水如萬片碎金動盪閃爍，一切都了無痕跡。\n他們身處海洋，海洋卻已將他們忘卻。"
  },
  Item_9828_Desc = {
    Text = "太過強硬之人，她會用戰鬥軟化你的靈魂。\n·提升隊伍力量。\n·擁有打擊敵方全體的技能"
  },
  Item_9828_Name = {Text = "蘿坦"},
  Item_9829_Desc = {
    Text = "他厭倦了超人的智慧，厭倦了狂熱的崇拜，也厭倦了超越萬古的長夢。\n·號令觸腕，降下攻擊\n·消耗算力，增強觸腕之力"
  },
  Item_9829_Name = {Text = "圖魯"},
  Item_9831_Desc = {
    Text = "主屬性從界域精通、狂氣回充等級、黑印掉落和銀鑰充能中隨機獲得1個。"
  },
  Item_9831_Name = {
    Text = "海歸線Ⅳ"
  },
  Item_9831_StoryDesc = {
    Text = "歸來吧，那終將重現的失落之城。"
  },
  Item_9833_Desc = {
    Text = "當靈知被無限放大，它將觸及真相的一角。\n由銀芯驅動的特殊儀器，能按照預設值永久提升喚醒體的能力。\n守密人達到30級後，可以選擇任一喚醒體，使其獲得以下增幅：\n·等級提升至40級\n·所有技能提升至2級\n·突破等階提升至3階"
  },
  Item_9833_Name = {
    Text = "靈知增幅器Ⅳ"
  },
  Item_9834_Desc = {
    Text = "由彌薩格大學創始人研究出的，能夠提升喚醒體能力的製劑。由銀芯與秘藥調配而成，呈現出一種奇異的色澤。\n可以為喚醒體提供2000經驗值。"
  },
  Item_9834_Name = {
    Text = "靈知製劑Ⅱ"
  },
  Item_9835_Desc = {
    Text = "縱然這並非她的本意，但世間或許就存在只適宜獨居於黑暗之中的生靈。\n·凝滯敵方行動\n·給予敵方易傷"
  },
  Item_9835_Name = {Text = "艾繼絲"},
  Item_9836_Desc = {
