  },
  Item_9837_Desc = {
    Text = "當靈知被無限放大，它將觸及真相的一角。\n由銀芯驅動的特殊儀器，能按照預設值永久提升喚醒體的能力。\n可以選擇任一喚醒體，使其獲得以下增幅：\n·等級提升至10級"
  },
  Item_9837_Name = {
    Text = "靈知增幅器Ⅰ"
  },
  Item_9838_Desc = {
    Text = "給予我們未可知曉的精神。\n源自菲林詩社的特殊膠片，能轉寫人的精神。\n用以升格超維界域喚醒體的材料。"
  },
  Item_9838_Name = {
