  },
  Item_9852_Name = {
    Text = "36室之環Ⅴ"
  },
  Item_9852_StoryDesc = {
    Text = "旋轉，然後遺忘——這是她生命的全部。"
  },
  Item_9853_Desc = {
    Text = "主屬性從狂氣回充等級、死亡抵抗、銀鑰充能等級和傷害強效中隨機獲得1個。"
  },
  Item_9853_Name = {
    Text = "有機形態Ⅴ"
  },
  Item_9853_StoryDesc = {
    Text = "鱗翅目正死於孤獨、愛與絕望。"
  },
  Item_9854_Desc = {
    Text = "主屬性從狂氣回充等級、死亡抵抗、銀鑰充能等級和傷害強效中隨機獲得1個。"
  },
  Item_9854_Name = {
    Text = "猩紅之擁Ⅴ"
  },
  Item_9854_StoryDesc = {
    Text = "傳說中最初的魔像創造者，以雙手殺死魔像。"
  },
  Item_9855_Desc = {
    Text = "屬性為傷害強效的命輪。"
  },
  Item_9855_Name = {Text = "苦咒縛"},
  Item_9855_StoryDesc = {
    Text = "他生命的前半段是混沌、黑暗與血腥的。\n\n吃了睡，睡了吃......後來，他睜開雙眼，擁有了意識。\n\n他們說他吃掉了自己所有的兄弟姐妹，是唯一的生還者。\n他們還說他是偉大的蛇神與人類交合誕下的子嗣。\n他的脖頸上有一圈黑色的咒縛，它們維繫著他的生命，也控制他，使他此生都無法違抗教會。\n他對這個世界有諸般疑惑與好奇，卻在誕生伊始便被剝奪了所有其他的可能性。\n\n美麗的、危險的。隱匿的、張揚的。這些都是他。\n遺憾的是，以上供述尚未觸及他的本質的十分之一。\n任何因此供述對阿爾比諾產生的惻隱之心都將令你萬劫不復。"
  },
  Item_9856_Desc = {
    Text = "提高持有者造成的護盾，並能夠允許玩家回合結束後保留溢出的護盾。"
  },
  Item_9856_Name = {
    Text = "記憶螺旋"
  },
  Item_9856_StoryDesc = {
    Text = "疼痛，劇烈的疼痛充斥著她的全部感官。\n\n金屬製的潛水服在水壓之下不值一提，外殼向內凹陷，螺絲崩裂，有什麼抵住了她的腹腔，有什麼刺穿了她的臂膀。冰冷的海水從潛水服破損的地方擠了進來，唯有使用了加厚金屬的頭盔還勉強維持著原樣，為她保留了一些綿薄的氧氣。\n\n透過頭盔僅有的窺探窗，她看到外面的海水由碧藍變成墨藍，再由墨藍變得漆黑。呼吸帶來的水汽凝結在玻璃上，漩渦的隆隆聲逐漸遠去，成為耳朵中殘存的幻影。她漸漸感受不到自己的四肢，呼吸也變得愈發沉重。\n\n她猜測自己應該暈過，寒冷、失血、缺氧，每一個都足以讓她意識模糊。同時她無法確定，因為無論她如何眨眼，面對的都是一樣的黑暗。\n\n這裡是光線無法抵達的地方，是大海深處未有人探知的領域。\n\n一種遲鈍的興奮最後攪動了一下她的血液——未知的領域，最後的冒險。她這也算完成夢想了吧？儘管她現在什麼都看不見。\n\n腳踝處傳來古怪的觸感，她下意識低頭望去，發現黑暗之中，似乎有什麼東西順著她的小腿向上攀登。是奇特的深海生物嗎，怎麼比海水還要冰冷？怎麼……在這樣的黑暗之中，她似乎能看到它的輪廓？\n\n漆黑的，蠕動的，如同泥漿一樣的……\n這是什麼？她在哪裡？她……是誰？"
  },
