  Item_9873_Name = {
    Text = "騎士之心"
  },
  Item_9873_StoryDesc = {
    Text = "他被大公指名成為騎士時，僅在世界上見證了七個四季。 \n\n大公一時興起逗弄小孩的玩笑話，卻被所有人當了真。\n騎士們訓練他的騎射武藝，女官教導著他的禮儀，公主也信任並依靠著這名小小騎士。\n\n漫步在亞奎丹與峽谷的曠野高原上，年輕的騎士牽著公主的馬。公主無力地趴伏在馬背上，不可視的黑暗正在吞噬她的身體。\n\n「公主，我們不能再往前了。」\n穿過這道峽谷，越過這條河流，就會離開養育他們的土壤。\n戰火在外界蔓延，敵人隔岸對豐沃的土地虎視眈眈。\n憑著天塹之隔，小小的土地得以苟延殘喘地活著，維持著「國家」的尊嚴。\n在峽谷的這頭，他們見證了對岸的覆滅與苦痛。\n無辜者的祈求與悲痛墜入了河流，成為了勝者詩篇的一部分。\n\n無論是多偉大的國度，都將無法阻攔地被捲入歷史。\n\n敵人斬下了稚嫩的雙手，他不再能舉起槍與盾。\n敵人踩碎了脆弱的雙膝，讓他只能眼睜睜看著鐵騎砸開行宮的大門。\n騎士掙扎著咬在了敵軍戰馬的腿上，卻並未能阻止敵人的暴行。\n\n然後，他第一次看見了公主口中的「黑色瘟疫」。\n\n洪水般的黑液衝出行宮大門，沒過鐵騎們的腿甲，卻無人一人因此而停下。\n洶湧的「黑色瘟疫」灌進了口鼻，嗆入了肺腑，他卻仍不想在這裡倒下。\n再然後，那無比熟悉的聲音直接在腦海響起。\n「你做的已經夠多了……我最忠實的騎士。」\n\n最後，眼前只剩空白一片。"
  },
  Item_9874_Desc = {
    Text = "套裝：\n詛咒兔Ⅰ\n詛咒兔Ⅱ\n詛咒兔Ⅲ\n詛咒兔Ⅳ\n詛咒兔Ⅴ\n詛咒兔Ⅵ"
  },
  Item_9874_Name = {Text = "詛咒兔"},
  Item_9875_Desc = {
    Text = "蠕動，扭曲，我們陰暗爬行……\n被寄生的蟲蛹。用於提升血肉界域喚醒體的技能等級。"
  },
  Item_9875_Name = {
    Text = "原生蟲蛹"
  },
  Item_9876_Desc = {
    Text = "屬性為暴擊率的命輪。"
  },
  Item_9876_Name = {Text = "海之夢"},
  Item_9876_StoryDesc = {
    Text = "奧瑞塔出生時，大洪水帶給城市的影響已經完全褪去了，但在偏遠的鄉鎮上，人們還在為了活下去而掙扎著。\n\n洪災讓人們開始恐懼海洋與江河，能離開的早就離開了，如今還留在這個小漁村的，都是些在外難尋立足之地的婦孺。\n在這個沉悶冷清的地方，奧瑞塔是唯一的小孩。\n\n她執拗地相信著婆婆講的童話——爸爸媽媽都已經回到了大海，他們在等待奧瑞塔長大。等她長大了，大家就能團聚，再次成為幸福的一家。\n\n在她還不會說話的時候，好像曾在很溫暖的懷抱睡著過，但其他有關父母的事情，奧瑞塔已經不太能想得起來了。\n但身為在寂靜之地出生長大的孩子，奧瑞塔並不理解「孤單」或「寂寞」，她自有一批朋友。\n\n和那些被洪水嚇破了膽子的大人不一樣，奧瑞塔從來都不懼怕海洋。\n海洋國王的住民，自然要和大海做朋友。\n奧瑞塔學會了和「同鄉」一起玩。\n她模仿蛤蜊移動的樣子舞動，學著小丑魚在海草中梭巡。\n她趴在棱皮龜的背上，順著海浪漂流到了離陸地很遠很遠的地方。\n她在被傾注滿月光的大海中，與水母群在海中嬉戲。\n\n她是快樂，她是想像，她是精靈。\n\n她是夢。\n"
  },
  Item_9877_Desc = {
    Text = "提高持有者狂氣爆發的傷害能力，並能夠在釋放狂氣爆發後獲得更多力量。"
  },
  Item_9877_StoryDesc = {
    Text = "多年來，我一直想著尤烏哈希。\n但只是在這些神廟的廢墟裡，我才第一次真正看清他。\n我看見他身上纏繞著沉重的枷鎖，因而不得不趴在地上，伸長脖頸，費力湊近早已變質的餐食。\n像條狗一樣。\n\n卡裡古拉死後，身為暴君的同謀，他被鎖在神廟的廢墟至今。\n我拖動手上的鎖鏈，將一個託雷斯的奴隸押送過來。\n他登時直立身軀，瞳孔放大，喉嚨裡發出急促的吞咽聲。\n\n「等等。」\n我拽住鎖鏈，將奴隸拉至他恰好無法夠到的距離。\n「幫我殺一個人。」\n他咧嘴笑了，露出一排尖利的獸齒。\n「你是第19個這麼和我說的人類，而我不得不拒絕你。」\n我竭力繃著臉，不讓他看出我的失落：\n「為什麼？」\n「如果你要我殺一千個人，我樂意至極。殺一個？你的籌碼遠遠不夠。」\n「如果那個人，是現在的皇帝呢。」\n我深吸一口氣。\n「這個籌碼足夠嗎？」\n尤烏哈希哈哈大笑：\n「這是數學問題，我的老夥計。一就是一，一千就是一千。」\n\n「著火了，金宮著火了！」\n遠方燃起熊熊火焰。\n暴君，暴君……\n我絕望地哭泣，為了塞內加，也為了那即將成為廢墟的華美宮殿。\n「這麼傷心？」\n尤烏哈希湊了過來。\n他已經享用了那個託雷斯的奴隸，正滿足地撮著嘴。\n是的，我向他許諾，只要能殺了暴君，除了自由，他還可以接著享用一千個無辜的生命。\n他能理解這場大火意味著什麼嗎？\n他能理解侍奉一個無可救藥的暴君意味著什麼嗎？\n恐怕不能。\n他只是個畜生罷了。\n\n「羅馬就像一個廢墟。」畜生說。\n「或者說，你們的國家，世界……\n在我看來，是既無意義也無止境的廢墟。\n你們為它流淚、互相殘殺，做了一切徒勞又無意義的事……\n說實話，我不理解。」\n\n我望向他傷痕累累的軀體。\n這是由數百萬血肉所鑄就的魔像，它在數百年的歲月裡，不斷被打碎、重組，就像羅馬一樣。\n「那你呢？你也是一座廢墟嗎？」\n「或許吧。」\n他伸了個懶腰，狹長的眼裡躍動著來自遠方的金色火光。\n「但我不在乎。」"
  },
