  Item_9881_Desc = {
    Text = "穩定獲取鑰能的同時伴隨鑰令的釋放為隊伍提供狂氣，額外的手牌上限和胚胎獲取帶來更靈活的選擇。"
  },
  Item_9881_StoryDesc = {
    Text = "歷史向來是贏家的一言堂，母樹消亡、國家傾覆，有關過去的一切都在悄然發生著改變。\n詩人傳唱著尼尼微美人的故事，旅人圍坐篝火側耳傾聽。\n\n「穿越銀色的沙漠，異國美人闖入了尼尼微\n天河之水從她的肩頭滑落，西奈珍珠從她的眼中墜下\n金黃雙瞳之中，凝視異度國土的過去\n蜜色肌膚之上，書寫尼尼微的未來」\n\n後來呢？這位美人成為王后了嗎？\n年邁詩人彈撥著七絃琴，發出一聲悠長歎息。\n\n「她是迷藥，眾生為之傾倒。\n她是猛毒，沁入王臣肺腑。\n她是洪水，蒼生無可逃脫。\n她是黑色瘟疫的使臣，她帶來疫病、噩夢、死亡和尼尼微的末日。」\n\n琴尚未放下，酒桌邊站起一人，引來眾酒客側目。\n那人纖長的指間漏下幾枚酒錢，金銀滾落，叮噹作響。\n她所行之處，目光追隨，燈火閃爍。\n\n「時間荏苒……但無妨，祂不會回應這些胡言亂語。\n終有一天，你們會理解祂的慈悲與寬厚……正如我所理解的那樣……」\n她推開酒館破舊的小門，如同推開一尊珠寶匣，月光落在裸露的肩頭，映照出琳琅的光。\n那被月光寵愛著的美人，確實有著如蜜的肌膚。"
  },
