  Item_9901_Desc = {
    Text = "那是古老意志的失落靈識。 彌薩格通過神秘的儀式啟發喚醒體的靈識，受到啟發的喚醒體將永久增強精神能力。\n重複獲得諾締拉時轉換獲得，用於啟動諾締拉的啟靈。"
