  Item_99102_Desc = {
    Text = "記錄此鑰令後，可在編隊時選擇鑰令技能：「虛世之彩」。\n\n潰爛的幻覺在視網膜上產下畸變的霓虹——\n於是「顏色」的概念於虛世昇華，僅剩譫妄的豔彩在現實的屍骸上流淌。"
