  Item_99724_Desc = {
    Text = "紀錄此鑰令後、可在編隊時選擇鑰令技能：「泣血的聖心」。\n\n他終於找回了一切記憶與力量、卻是以想要守護的所有為代價。\n他已來得太晚。\n 只有憤怒與悔恨的血淚灼燒著那顆顫抖的心臟。"
